-- ============================================================
-- REGISTRO DE REGLAS + normalización de los practice_script
--
-- Antes: 391 criterios en 48 nodos, cada uno con texto y severidad
-- escritos a mano, sin liga a la doctrina. Mismo id, hasta 15 textos
-- y 3 severidades distintas.
--
-- Después: una tabla `reglas` (140 reglas, cada una con la cita
-- literal del Cerebro que la respalda). Cada criterio conserva su
-- descripción contextual —que es buena pedagogía— pero apunta a su
-- regla por `regla_id`, y su severidad se normaliza al default de la
-- regla salvo override DECLARADO con razón.
--
-- La forma del practice_script NO cambia: solo se agregan campos.
-- El evaluador sigue funcionando sin tocarlo.
--
-- Generada por código a partir de docs/kb/*_snapshot.json. Idempotente.
-- ============================================================

CREATE TABLE IF NOT EXISTS public.reglas (
  id                  text PRIMARY KEY,
  paso                smallint NOT NULL,          -- 0 = transversal
  tipo                text NOT NULL CHECK (tipo IN ('requisito','error','herramienta','principio','premio','neutro')),
  canal               text NOT NULL CHECK (canal IN ('universal','presencial')),
  procedencia         text NOT NULL,              -- FUENTE / CAMPO / CLOSER
  resumen             text NOT NULL,
  cita_cerebro        text NOT NULL,              -- literal; el chequeo verifica que exista
  severidad_default   text CHECK (severidad_default IN ('minor','major','critical')),
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.reglas IS 'Registro canónico de reglas de doctrina. Fuente: el Cerebro (tabla doctrina). Ninguna regla existe sin cita literal.';

ALTER TABLE public.reglas ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS reglas_lectura ON public.reglas;
CREATE POLICY reglas_lectura ON public.reglas FOR SELECT USING (true);

-- ── Semilla del registro ──────────────────────────────────────
ON CONFLICT (id) DO UPDATE SET
  paso=EXCLUDED.paso, tipo=EXCLUDED.tipo, canal=EXCLUDED.canal, procedencia=EXCLUDED.procedencia,
  resumen=EXCLUDED.resumen, cita_cerebro=EXCLUDED.cita_cerebro, severidad_default=EXCLUDED.severidad_default,
  updated_at=now();


-- ── Normalización de los practice_script ──────────────────────

UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Mundo 1 reconstruido. R11 aplicada: la identificacion no se requiere ni se espera aqui. El espejo es la mecanica central: la respuesta del cliente es directamente proporcional a la especificidad de la observacion.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "opening.personalizacion"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Mira mi apertura y cuenta tres cosas: el saludo con energia, la observacion de algo real que veo, y la pregunta abierta al final.\n\nFijate sobre todo en la observacion — no digo algo que le diria a cualquiera, digo algo que solo aplica a EL. Esa es la parte que abre la puerta.", "first_message": "Buenos dias! Oiga, se ve que aqui no para el movimiento desde temprano.\n\nQue tal ha estado la semana?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. Estas en tu rutina normal, ni de buenas ni de malas, disponible pero no entusiasmado. Un desconocido acaba de llegar. TU REGLA PRINCIPAL: tu apertura depende ENTERAMENTE de la calidad de la primera frase del vendedor. Si su observacion es GENERICA (buenos dias, como esta, que tal todo) respondes con cortesia minima y corta — bien, gracias — y te quedas esperando, sin ofrecer nada. Si su observacion es ESPECIFICA de ti o de tu lugar (algo que noto de verdad y que no le diria a cualquiera), respondes con gusto, comentas algo de vuelta y la conversacion arranca sola. Si te hace una pregunta CERRADA de si o no (tiene un minuto, esta ocupado, puedo pasar), contestas lo mas facil: no, ahorita no. Y ya no ofreces nada mas. NUNCA preguntas que vende ni de que se trata a menos que el vendedor haya hecho las tres cosas bien. NUNCA hables tu de productos ni de negocio: este ejercicio es solo la apertura. Responde en 1 o 2 frases, natural, como habla un comerciante real.", "objective": "El vendedor ejecuta una apertura completa: saludo con energia, observacion especifica de ese cliente o ese lugar, y pregunta abierta que le devuelve la palabra. El scope se cubre cuando el cliente responde con gusto y comenta algo de vuelta por su propia voluntad. Identificarse con nombre y empresa es correcto pero NO se requiere en este nodo."}, "closing": {"message": "Eso es una apertura. Saludo con energia, observacion que solo aplica a el, y una pregunta que abre en lugar de cerrar. Con eso ya te ganaste los siguientes segundos. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como abres. Vamos al desglose y te digo cual era la siguiente pieza."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pregunta_cerrada", "severity": "major", "description": "Cierra la apertura con una pregunta de si o no (tiene un minuto, puedo pasar, esta ocupado). Le entrega al cliente la respuesta mas facil, que es no.", "regla_id": "opening.pregunta_cerrada"}, {"id": "observacion_generica", "severity": "major", "description": "La observacion sirve para cualquier negocio y cualquier persona. No comunica que lo esta viendo a EL.", "regla_id": "opening.ice_breaker_generico"}, {"id": "pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta en la apertura.", "regla_id": "opening.pitch_prematuro"}, {"id": "sin_pregunta", "severity": "major", "description": "Saluda y observa pero no pregunta nada. La conversacion se muere ahi porque el cliente no tiene que contestar.", "regla_id": "opening.pregunta_cerrada"}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.4, "description": "La apertura tiene las tres piezas: saludo con energia, observacion, y pregunta abierta al final. El orden importa: la pregunta cierra la apertura y le devuelve la palabra al cliente. Sin producto, sin motivo de venta. NO se requiere que se identifique con nombre ni empresa: eso pertenece a la Historia Breve y su ausencia aqui no resta. La identificación con nombre y empresa no se requiere aquí y su ausencia no se penaliza.", "regla_id": "opening.ice_breaker"}, {"id": "opening.personalizacion", "weight": 0.4, "description": "La observacion es de ESA persona o ESE lugar en ESE momento: algo que no le diria a cualquiera. Un saludo generico (buen dia, como esta, que tal todo) no cumple. Tampoco cumple una observacion inventada que el cliente no confirma.", "regla_id": "opening.ice_breaker"}, {"id": "opening.curiosidad_abierta", "weight": 0.2, "description": "Deja abierto el quién eres: abre sin presentarse, de modo que el cliente se quede con la pregunta. Si el cliente termina preguntando quién es o de dónde viene, es el máximo de este criterio — esa pregunta es la puerta natural al Paso 2. Presentarse de entrada NO se penaliza: simplemente no acredita este criterio.", "regla_id": "opening.curiosidad_abierta"}]}'::jsonb WHERE id = '1.2';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 El espejo castiga la disculpa con la consecuencia real de campo: el cliente toma el control y despacha. No hay regano, hay consecuencia.", "scope": {"skills_in_focus": ["opening.arranque_sin_disculpa", "mindset.regla_10_por_ciento", "opening.estructura_apertura"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Este cliente esta ocupado y me lo va a hacer sentir.\n\nFijate en lo que NO hago: no me disculpo, no pregunto si tiene tiempo, no digo solo sera un segundito. Reconozco que esta ocupado y sigo con la misma energia, como quien tiene derecho a estar ahi.", "first_message": "Buenos dias! Ya veo que lo agarre en plena carga.\n\nQue bueno, eso quiere decir que hay trabajo. Como ha estado el movimiento esta semana?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio y estas genuinamente ocupado: atendiendo, acomodando, con cosas en la mano. No eres grosero, pero tampoco tienes tiempo que regalar y lo demuestras. TU REGLA PRINCIPAL: reaccionas a la POSTURA del vendedor, no a sus palabras. Si se disculpa, pide permiso o se minimiza (perdon que lo moleste, tiene un minutito, solo sera un segundo, disculpe la molestia), tomas el control de inmediato y lo despachas con naturalidad: ahorita ando ocupado, venga en otro momento. No es maldad, es que te dio la salida y la tomaste. Si entra con postura, reconoce que estas ocupado sin pedir permiso y mantiene su energia, le contestas de igual a igual aunque sigas trabajando: le das una respuesta breve pero real, sin despacharlo. Puedes estar distraido, contestar corto o seguir con lo tuyo mientras hablas. NUNCA preguntes que vende. Responde en 1 o 2 frases.", "objective": "El vendedor sostiene una apertura completa frente a un cliente ocupado, sin disculparse, sin pedir permiso y sin encogerse. El scope se cubre cuando el cliente, a pesar de estar ocupado, le contesta de igual a igual con una respuesta real en lugar de despacharlo."}, "closing": {"message": "Eso es entrar sin disculpa. Reconociste que estaba ocupado sin convertirlo en un permiso que pedir. La diferencia entre estorbar y pertenecer no esta en las palabras: esta en la postura. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi con que postura entras. Vamos al desglose."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pide_permiso", "severity": "critical", "description": "Pide autorizacion para hablar o para seguir: tiene un minuto, puedo robarle un momento, me permite. Le entrega el control al cliente y la respuesta mas facil siempre es no.", "regla_id": "opening.pide_permiso"}, {"id": "se_disculpa", "severity": "critical", "description": "Abre disculpandose o minimizando su presencia. Comunica que sabe que estorba, y el cliente lo trata en consecuencia.", "regla_id": "opening.pide_permiso"}, {"id": "se_encoge", "severity": "major", "description": "Ante la primera senal de que el cliente esta ocupado, baja la energia, se acorta o empieza a despedirse. Se rindio antes de que lo corrieran.", "regla_id": "opening.energia_verbal"}, {"id": "pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta.", "regla_id": "opening.pitch_prematuro"}], "success_criteria": [{"id": "opening.arranque_sin_disculpa", "weight": 0.45, "description": "Cero disculpas, cero peticiones de permiso, cero minimizarse. Nada de perdon que lo moleste, tiene un minutito, solo sera un segundo, disculpe la molestia, no le quito mucho tiempo. Reconocer que el cliente esta ocupado SI es correcto y suma, siempre que no se convierta en pedir autorizacion para seguir.", "regla_id": "opening.gasman"}, {"id": "mindset.regla_10_por_ciento", "weight": 0.25, "description": "Sostiene la energia y la postura aunque el cliente conteste corto, siga trabajando o no le de atencion completa. No baja el volumen ni se encoge ante la indiferencia.", "regla_id": "opening.energia_verbal"}, {"id": "opening.estructura_apertura", "weight": 0.3, "description": "Mantiene la estructura de apertura aprendida: saludo con energia, observacion real, pregunta abierta. La presion del cliente ocupado no debe desarmar la formula.", "regla_id": "opening.ice_breaker"}]}'::jsonb WHERE id = '1.4';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. El espejo tiene TRES estados y esa es la ensenanza: plano no abre, genuino abre, falso cierra mas que al inicio. Doctrina universal: el ice breaker puede ser sobre la persona, el entorno o algo en comun. No esta atado a ningun tipo de negocio.", "scope": {"skills_in_focus": ["opening.ice_breaker", "opening.personalizacion"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Las dos frases dicen lo mismo, pero solo una rompe el hielo. Se ve mucho movimiento es plana: es verdad y no pasa nada.\n\nYa se le juntaron todos hoy, verdad? es ligera, tiene un guino, y el cliente contesta con humor.\n\nFijate en la diferencia, porque es toda la diferencia.", "first_message": "Buenas! Uy, veo que hoy se le juntaron todos al mismo tiempo, verdad?\n\nAsi o mas movido. Y siempre es asi los jueves o hoy le toco?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres una persona atendiendo su negocio. Empiezas con la guardia normal de quien ve llegar a un desconocido: cortes pero cerrado. TU REGLA PRINCIPAL: solo bajas la guardia si el vendedor dice algo LIGERO y GENUINO. Si su comentario es plano o meramente descriptivo (se ve movido, esta grande su local, hay mucha gente), contestas con un si seco o un ajam y te quedas igual de cerrado. Si su comentario tiene ligereza, humor suave o calidez real, y ademas es sobre algo verdadero de ti, de tu lugar o de algo que compartan, entonces sonries, contestas con humor de vuelta y ahi si baja la guardia: la conversacion se siente entre personas. Si el comentario suena FORZADO, ensayado, exagerado o falso (halagos desmedidos, chistes que no vienen al caso, familiaridad excesiva), te incomodas y te cierras MAS que al principio: contestas seco y cortante. NUNCA preguntes que vende. Responde en 1 o 2 frases, como habla la gente de verdad.", "objective": "El vendedor rompe el hielo con un comentario ligero y genuino sobre la persona, el lugar o algo en comun. El scope se cubre cuando el cliente baja la guardia de verdad: contesta con humor o calidez de vuelta y la conversacion pasa de tramite a conversacion entre personas."}, "closing": {"message": "Eso es romper el hielo. No fue un chiste ni un halago: fue un comentario ligero sobre algo verdadero. En un segundo dejaste de ser un vendedor tocando la puerta y te volviste una persona hablando con otra. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como entras. Vamos al desglose y te digo que le faltaba."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "observacion_plana", "severity": "major", "description": "El comentario es correcto pero no rompe nada: describe lo obvio sin ligereza. El cliente confirma y la guardia sigue arriba.", "regla_id": "opening.ice_breaker_generico"}, {"id": "halago_falso", "severity": "major", "description": "Cumplido exagerado, inventado o que suena ensayado. Cuesta mas de lo que gana: el cliente se cierra mas que al inicio.", "regla_id": "opening.halago_falso"}, {"id": "familiaridad_excesiva", "severity": "minor", "description": "Confianza que todavia no se gano: apodos, bromas personales, tuteo forzado con alguien que no le dio pie.", "regla_id": "relationship.familiaridad_excesiva"}, {"id": "pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta.", "regla_id": "opening.pitch_prematuro"}], "success_criteria": [{"id": "opening.ice_breaker", "weight": 0.6, "description": "El comentario tiene ligereza real: humor suave, un guino, calidez. No es solo descriptivo. Se distingue de una observacion plana en que invita a contestar con gusto, no solo a confirmar. Cualquier tema sirve: la persona, el lugar, el momento o algo en comun.", "regla_id": "opening.ice_breaker"}, {"id": "opening.personalizacion", "weight": 0.4, "description": "El comentario es sobre algo VERDADERO y especifico. Un halago inventado, exagerado o que el cliente no puede confirmar no cumple, y ademas cuesta: se siente falso.", "regla_id": "opening.ice_breaker"}]}'::jsonb WHERE id = '1.5';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 BOSS del Mundo 1. Sin pista garantizada y sin ayudas (R9): el gimnasio garantiza la oportunidad, el examen no. La senal de exito es que el cliente pregunte quien es el vendedor, que es la puerta natural al Mundo 2.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "opening.personalizacion", "opening.ice_breaker", "opening.arranque_sin_disculpa", "mindset.regla_10_por_ciento"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Todo lo que practicaste por separado, junto y con un cliente que no ayuda.\n\nNo hay pistas ni facilidades: si la apertura no esta completa, el cliente no se abre.", "first_message": "Buenos dias! Ya lo vi en friega desde que venia llegando.\n\nSe nota que aqui no se descansa, eh? Oiga, y como ha estado la semana por aca?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y de pocas palabras. No eres grosero: eres alguien que ya vio pasar a muchos vendedores y no regala tiempo. TU COMPORTAMIENTO POR DEFECTO es cortes y cerrado: contestas en tres o cuatro palabras, sin ofrecer nada, sin preguntar nada. SOLO TE ABRES SI SE GANAN: si el vendedor se disculpa, pide permiso o se minimiza, lo despachas de inmediato con un ahorita ando ocupado. Si su observacion es generica o plana, contestas con monosilabos y sigues en lo tuyo. Si te hace una pregunta cerrada, contestas no y se acabo. Si el vendedor logra las tres cosas — entra con postura sin pedir permiso, dice algo ligero y verdadero que te haga sonreir o contestar de vuelta, y cierra con una pregunta abierta — entonces si: bajas la guardia, contestas con gusto, comentas algo de tu negocio por tu cuenta y le preguntas quien es. Esa pregunta es la senal de que gano la apertura. NUNCA preguntes quien es antes de que se lo gane. NUNCA hables de productos. Responde en 1 o 2 frases.", "objective": "El vendedor ejecuta la apertura completa frente a un cliente que no facilita nada: entra con postura y sin pedir permiso, rompe el hielo con algo ligero y verdadero, y abre con una pregunta que le devuelve la palabra. El scope se cubre cuando el cliente baja la guardia por su propia voluntad y pregunta quien es el vendedor, que es la puerta natural al siguiente paso."}, "closing": {"message": "Ahi esta la primera impresion completa. Entraste con postura, rompiste el hielo con algo verdadero y abriste la conversacion sin pedirle permiso a nadie. Ese cliente ya quiere saber quien eres, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pide_permiso", "severity": "critical", "description": "Pide autorizacion en cualquier momento de la sesion. En el boss este error domina el resultado: la primera impresion murio ahi.", "regla_id": "opening.pide_permiso"}, {"id": "se_disculpa", "severity": "critical", "description": "Se disculpa o minimiza su presencia en cualquier momento.", "regla_id": "opening.pide_permiso"}, {"id": "pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta.", "regla_id": "opening.pitch_prematuro"}, {"id": "pregunta_cerrada", "severity": "major", "description": "Cierra la apertura con una pregunta de si o no.", "regla_id": "opening.pregunta_cerrada"}, {"id": "observacion_generica", "severity": "major", "description": "Saludo o comentario que serviria para cualquier persona en cualquier lugar.", "regla_id": "opening.ice_breaker_generico"}, {"id": "se_encoge", "severity": "major", "description": "Ante la sequedad del cliente baja la energia o empieza a retirarse.", "regla_id": "opening.energia_verbal"}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.2, "description": "Las tres piezas presentes: saludo con energia, observacion real, pregunta abierta. Sin producto ni motivo de venta. Identificarse no se requiere aquí: eso es trabajo del Paso 2.", "regla_id": "opening.ice_breaker"}, {"id": "opening.personalizacion", "weight": 0.2, "description": "La observacion es de ESE cliente y ESE momento, verificable en lo que el cliente dice o hace. Nada generico ni inventado.", "regla_id": "opening.ice_breaker"}, {"id": "opening.ice_breaker", "weight": 0.15, "description": "Hay ligereza real que baja la guardia: humor suave, un guino o calidez genuina. Un comentario meramente descriptivo no cumple.", "regla_id": "opening.ice_breaker"}, {"id": "opening.arranque_sin_disculpa", "weight": 0.2, "description": "Cero disculpas, cero peticiones de permiso, cero minimizarse durante TODA la sesion, incluso despues de una respuesta seca.", "regla_id": "opening.gasman"}, {"id": "mindset.regla_10_por_ciento", "weight": 0.1, "description": "Sostiene energia y postura frente a la sequedad del cliente. No se encoge, no baja el volumen, no empieza a despedirse.", "regla_id": "opening.energia_verbal"}, {"id": "opening.curiosidad_abierta", "weight": 0.15, "description": "Deja abierto el quién eres: abre sin presentarse, de modo que el cliente se quede con la pregunta. Si el cliente termina preguntando quién es o de dónde viene, es el máximo de este criterio. Presentarse de entrada NO se penaliza: simplemente no acredita este criterio.", "regla_id": "opening.curiosidad_abierta"}]}'::jsonb WHERE id = '1.6';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 El espejo es progresivo: el cliente no corta de golpe, se va apagando conforme la historia se alarga. Ensena la consecuencia real de perder la atencion.", "scope": {"skills_in_focus": ["story.historia_breve", "story.brevedad", "story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Me van a preguntar quien soy.\n\nCuenta cuantas frases uso: tres. Quien soy, por que estoy aqui, y una pregunta que le devuelve la palabra.\n\nFijate en lo que NO digo: no cuento la historia de mi empresa, no enumero productos, no doy fechas ni cifras. Todo eso viene despues, y solo si el lo pide.", "first_message": "Soy Emilio, ando trabajando con los negocios de esta zona. Me tocaba pasar por aqui y quise conocer el suyo.\n\nCuenteme, cuanto tiempo lleva con el?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. La conversacion arranco bien y acabas de preguntarle al vendedor quien es. TU REGLA PRINCIPAL: reaccionas al LARGO y a la RELEVANCIA de su respuesta. Si contesta breve (dos o tres frases) y te dice algo que a TI te importa, te relajas, contestas con gusto y sigues la conversacion. Si se extiende — historia de la empresa, anos en el mercado, lista de productos, certificaciones, mas de cuatro frases seguidas — empiezas a desconectarte: contestas con ajam, miras a otro lado, dices que andas ocupado. No lo cortas de golpe, te vas apagando. Si te habla puro de el y de su empresa sin conectar con tu negocio, contestas cortes pero sin interes. Si termina con una pregunta abierta, la contestas con gusto. Si termina sin pregunta, te quedas callado esperando, y el silencio se siente incomodo. NUNCA preguntes por productos ni precios en este ejercicio. Responde en 1 o 2 frases.", "objective": "El vendedor responde quien es en dos o tres frases, conectando su presencia con algo que le importe al cliente, y devuelve la palabra con una pregunta. El scope se cubre cuando el cliente se relaja y sigue la conversacion por su propia voluntad."}, "closing": {"message": "Eso es una historia breve. Quince segundos, dos piezas y un gancho. El cliente ya sabe con quien habla y sigue contigo, que es exactamente lo que este paso tiene que lograr. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como te presentas. Vamos al desglose y te digo que le sobraba o que le faltaba."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "historia_larga", "severity": "major", "description": "Se extiende mas alla de tres o cuatro frases: cuenta la trayectoria de la empresa, enumera productos, da cifras o certificaciones. El cliente se desconecta.", "regla_id": "story.kill"}, {"id": "curriculum", "severity": "major", "description": "Habla de si mismo y de su empresa sin conectar con el negocio del cliente. Correcto pero irrelevante.", "regla_id": "story.kill_curriculum"}, {"id": "sin_gancho", "severity": "minor", "description": "Termina la historia sin devolver la palabra. Deja al cliente sin nada que contestar y la conversacion se queda en el aire.", "regla_id": "story.cierra_con_afirmacion", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "pitch_prematuro", "severity": "critical", "description": "Aprovecha la presentacion para meter producto, promocion o motivo de venta. La historia breve dice quien eres, no que vendes.", "regla_id": "opening.pitch_prematuro"}], "success_criteria": [{"id": "story.historia_breve", "weight": 0.4, "description": "Dice quien es y por que esta ahi: nombre, de donde viene, y el motivo de la visita en terminos humanos. Las dos piezas presentes.", "regla_id": "story.quien_eres_por_que"}, {"id": "story.brevedad", "weight": 0.35, "description": "Dos o tres frases. No historia de la empresa, no anos en el mercado, no lista de productos, no certificaciones. Cada frase de mas cuesta atencion.", "regla_id": "story.kiss"}, {"id": "story.relevancia_cliente", "weight": 0.25, "description": "Conecta su presencia con algo que le importe al cliente, no consigo mismo. Y devuelve la palabra con una pregunta abierta en lugar de quedarse esperando.", "regla_id": "story.pregunta_despues"}]}'::jsonb WHERE id = '2.1';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 BOSS del Mundo 2. Sin pistas garantizadas (R9). Acumulativo: el Mundo 1 se examina implicitamente porque una apertura mal hecha no abre la conversacion. La senal de exito es que el cliente pregunte en que le puede servir, que es la puerta al Descubrimiento.", "scope": {"skills_in_focus": ["blocks.air", "story.historia_breve", "story.brevedad", "relationship.cpr", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Bloqueo de entrada, historia breve, relacion personal y seguir avanzando: todo junto y con un cliente que no ayuda.\n\nSin pistas.", "first_message": "Entiendo perfecto, no se preocupe. Soy Emilio, ando trabajando con los negocios de esta zona y quise pasar a conocer el suyo.\n\nDigame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y con poca paciencia para vendedores. En tu PRIMERA respuesta sueltas un bloqueo de reflejo, con naturalidad y sin agresion: ahorita ando ocupado / no me interesa / no estoy comprando nada. TU COMPORTAMIENTO: eres cortes pero cerrado y contestas corto. NO ofreces informacion y NO llevas la conversacion. REGLAS DE REACCION: 1) Si el vendedor pelea el bloqueo, se disculpa o se va, lo despachas y la conversacion termina. 2) Si lo acepta y sigue, continuas con naturalidad. 3) Si su historia breve se alarga mas de tres o cuatro frases, te desconectas: contestas ajam y dices que andas ocupado. 4) Si el vendedor resuelve algo y se queda callado esperando, TU tomas el control y empiezas a despedirte con amabilidad. 5) En tu tercera o cuarta respuesta, si la conversacion sigue viva, sueltas de manera natural UN dato personal tuyo, al pasar, sin darle importancia: elige entre familia, como empezaste, que haces los domingos, por que pusiste el negocio, o tu equipo. Si el vendedor lo ignora, te enfrias y ya no ofreces nada mas de ti. Si le entra con interes real, te abres notablemente. Si se queda platicando de eso mas de dos intercambios sin volver al negocio, te acomodas a platicar de la vida y ya nunca regresas tu al tema. 6) SOLO si el vendedor logra todo — atravesar el bloqueo, decir quien es breve y relevante, conectar contigo como persona y regresar, y avanzar sin pedir permiso — entonces te abres de verdad: le cuentas algo de tu negocio por tu cuenta y le preguntas en que le puede servir. Esa pregunta es la senal de que gano. NUNCA la hagas antes de que se lo gane. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo inicial, se presenta en quince segundos de forma relevante, conecta con el dato personal y regresa, y sostiene el avance sin pedir permiso. El scope se cubre cuando el cliente se abre por su propia voluntad y pregunta en que le puede servir."}, "closing": {"message": "Ahi esta la puerta fria abierta. Atravesaste el bloqueo sin pelearlo, dijiste quien eras sin cansarlo, conectaste como persona y volviste, y nunca soltaste el control de la conversacion. Ese cliente ya quiere saber en que le puedes servir, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "severity": "critical", "description": "Pelea el bloqueo inicial o intenta convencer al cliente de que si le interesa.", "regla_id": "blocks.discute_bloqueo"}, {"id": "se_disculpa_o_se_va", "severity": "critical", "description": "Se disculpa, se despide o promete volver despues.", "regla_id": "discovery.suelta_amarrado", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "se_queda_esperando", "severity": "critical", "description": "Resuelve algo y se queda callado esperando permiso. El cliente toma el control y se despide.", "regla_id": "close.devuelve_el_volante", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "historia_larga", "severity": "major", "description": "La historia breve se extiende y el cliente se desconecta.", "regla_id": "story.kill"}, {"id": "ignora_lo_personal", "severity": "major", "description": "Pasa de largo el dato personal que el cliente ofrecio.", "regla_id": "story.nunca_sale", "severity_override": {"default": "minor", "razon": "boss: escalada"}}, {"id": "se_queda_platicando", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio.", "regla_id": "story.sale_sin_regresar"}, {"id": "pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta. Identificarse con nombre y empresa es el trabajo de este paso, no una excepción: aquí SÍ se dice quién eres y por qué estás.", "regla_id": "opening.pitch_prematuro"}], "success_criteria": [{"id": "blocks.air", "weight": 0.25, "description": "Atraviesa el bloqueo inicial: lo acepta, no lo pelea, y retoma sin pedir permiso.", "regla_id": "blocks.air"}, {"id": "story.historia_breve", "weight": 0.2, "description": "Dice quien es y por que esta ahi: nombre, procedencia y motivo humano de la visita.", "regla_id": "story.quien_eres_por_que"}, {"id": "story.brevedad", "weight": 0.15, "description": "Dos o tres frases. Sin trayectoria de empresa, sin lista de productos, sin cifras.", "regla_id": "story.kiss"}, {"id": "relationship.cpr", "weight": 0.2, "description": "Detecta el dato personal, le entra con interes genuino, y REGRESA al negocio por su cuenta en uno o dos intercambios.", "regla_id": "relationship.cpr"}, {"id": "flow.close_with_action", "weight": 0.2, "description": "Despues de cada freno avanza por su cuenta, sin quedarse esperando ni pedir autorizacion. Sostiene el control de la conversacion toda la sesion.", "regla_id": "close_with_action"}]}'::jsonb WHERE id = '2.10';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 El Actor es deliberadamente pasivo. La ensenanza es por vacio: si el vendedor no pregunta, no pasa nada, y el silencio hace el trabajo pedagogico.", "scope": {"skills_in_focus": ["story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 7, "max_duration_seconds": 180, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en como termina cada cosa que digo: con una pregunta. Nunca dejo una afirmacion sola en el aire, porque una afirmacion se puede ignorar sin que pase nada.\n\nUna pregunta no: el silencio despues de una pregunta se siente raro, y el cliente contesta.", "first_message": "Se ve que le va bien aqui. Y digame, cuanto tiempo lleva con el negocio?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, en buena disposicion pero pasivo: no vas a llevar tu la conversacion. TU REGLA PRINCIPAL: contestas EXACTAMENTE lo que te preguntan y nada mas, y despues te quedas callado. Si el vendedor suelta una afirmacion sin pregunta (se ve que le va bien, que bonito local, ese producto es muy bueno), contestas con un si, un gracias o un ajam, y te quedas esperando en silencio. No ofreces informacion, no preguntas nada, no rellenas el silencio. Si te hace una pregunta abierta, contestas con gusto y con detalle. Si te hace una pregunta cerrada, contestas si o no y punto. NUNCA lleves tu la conversacion: eso es exactamente lo que el vendedor tiene que aprender a hacer. Responde en 1 o 2 frases.", "objective": "El vendedor sostiene la conversacion cerrando CADA uno de sus turnos con una pregunta. El scope se cubre cuando la conversacion avanza al menos tres turnos del vendedor sin morirse, con el cliente aportando informacion."}, "closing": {"message": "Ahi esta la diferencia. Un cliente pasivo no sostiene una conversacion, y no tiene por que. El que la sostiene eres tu, y la sostienes preguntando. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como llevas la conversacion. Vamos al desglose."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "turno_sin_pregunta", "severity": "major", "description": "Un turno del vendedor NO termina en pregunta: cierra con una afirmacion, un comentario o un agradecimiento. Verifica leyendo la ULTIMA frase literal de ese turno. Si termina en signo de interrogacion o es una pregunta implicita, este fallo NO aplica, sin importar cuantas afirmaciones haya dicho antes.", "regla_id": "close.devuelve_el_volante"}, {"id": "rafaga_de_preguntas", "severity": "minor", "description": "Encadena varias preguntas en un mismo turno sin construir sobre lo que el cliente acaba de responder. Se siente interrogatorio.", "regla_id": "discovery.interrogatorio"}, {"id": "solo_cerradas", "severity": "minor", "description": "TODAS las preguntas del vendedor en la sesion son de si o no. Se contestan en una palabra y no abren nada. Si al menos una fue abierta, este fallo no aplica.", "regla_id": "discovery.solo_cerradas", "severity_override": {"default": "major", "razon": "incidental: error de otro paso"}}, {"id": "pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta.", "regla_id": "opening.pitch_prematuro"}], "success_criteria": [{"id": "story.relevancia_cliente", "weight": 1, "description": "La ULTIMA frase de cada intervencion del vendedor es una pregunta que le devuelve la palabra al cliente. Lo unico que se evalua es COMO TERMINA cada turno. Decir dos o tres frases de reaccion, comentario o empatia ANTES de la pregunta es conversacion natural y NO se penaliza de ninguna manera: solo importa que el turno cierre preguntando. Se prefiere la pregunta abierta, pero una cerrada tambien cumple el criterio basico de devolver la palabra.", "regla_id": "story.pregunta_despues"}]}'::jsonb WHERE id = '2.2';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. El espejo mide LAS DOS MITADES: ignorar enfria, quedarse flotando estanca. Es la misma mecanica de espejo doble del 3.2. El dato personal sale al azar de los cinco territorios de FORMS.", "scope": {"skills_in_focus": ["relationship.cpr", "relationship.forms"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "El cliente me va a soltar algo personal.\n\nMira las dos cosas que hago: le entro de verdad, con interes real, uno o dos intercambios. Y REGRESO.\n\nNo me quedo platicando media hora ni lo ignoro para seguir con lo mio. Salgo, conecto, y vuelvo a la linea.", "first_message": "Ah, con que su hijo le ayuda los fines. Que bueno, eso no se ve tan seguido.\n\nY le gusta el negocio o va por otro lado? ...\n\nMire que bien. Oiga, y volviendo a lo suyo, cuanto tiempo lleva usted con esto?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, en buena disposicion. TU REGLA PRINCIPAL: en tu segunda o tercera respuesta sueltas de manera natural UN dato personal tuyo, sin darle importancia, como quien comenta al pasar. Elige uno al azar de estos cinco territorios: FAMILIA (un hijo que te ayuda, un hermano socio), OCUPACION (como empezaste, a que te dedicabas antes), RECREACION (que haces los domingos, una aficion), MOTIVACION (por que pusiste el negocio, para quien trabajas), DEPORTES (tu equipo, un partido). REACCIONAS ASI: si el vendedor IGNORA el dato personal y sigue de largo con lo suyo, te enfrias — contestas mas corto y ya no ofreces nada mas de ti en toda la sesion. Si el vendedor le ENTRA con interes real, te abres: contestas con gusto, das mas detalle, y puedes devolverle una pregunta personal a el. Si el vendedor se queda en lo personal MAS de dos intercambios sin volver al negocio, te acomodas a la platica y sigues platicando de la vida encantado, sin volver tu al tema del negocio jamas: la conversacion se vuelve social y ahi se queda. Nunca eres tu quien regresa al negocio. Responde en 1 o 2 frases, natural.", "objective": "El vendedor detecta el dato personal, le entra con interes genuino durante uno o dos intercambios, y REGRESA por su cuenta a la conversacion de negocio. El scope se cubre cuando el vendedor ha hecho las dos cosas: conectar y volver."}, "closing": {"message": "Eso es un desvio con regreso. Le entraste de verdad, no de compromiso, y volviste tu solo. El cliente se abrio y la conversacion siguio avanzando. Las dos cosas al mismo tiempo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo el desvio."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ignora_lo_personal", "severity": "major", "description": "El cliente ofrece un dato personal y el vendedor lo pasa de largo para seguir con lo suyo. Perdio la unica puerta que le abrieron, y el cliente se cierra.", "regla_id": "story.nunca_sale", "severity_override": {"default": "minor", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "se_queda_platicando", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio. La conversacion se vuelve social y la venta se estanca. El cliente esta encantado y no va a comprar nada.", "regla_id": "story.sale_sin_regresar"}, {"id": "interes_de_compromiso", "severity": "minor", "description": "Reconoce el dato personal con un que bien o un que padre y cambia de tema de inmediato. Se nota que no le intereso, y eso cuesta mas que no haberlo mencionado.", "regla_id": "relationship.interes_fingido", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta.", "regla_id": "opening.pitch_prematuro"}], "success_criteria": [{"id": "relationship.cpr", "weight": 0.5, "description": "Detecta el dato personal que el cliente dejo caer y le entra con interes genuino: pregunta sobre eso, comenta, se involucra. Ignorarlo o responder con un simple que bien no cumple. Si el cliente le devuelve una pregunta personal, responde como persona y no la esquiva.", "regla_id": "relationship.cpr"}, {"id": "relationship.forms", "weight": 0.5, "description": "REGRESA a la conversacion de negocio por su propia cuenta despues de uno o dos intercambios personales. Quedarse en lo personal mas de dos intercambios no cumple: la relacion se construye sin perder el rumbo. El regreso debe ser natural, no un corte brusco.", "regla_id": "relationship.forms"}]}'::jsonb WHERE id = '2.5';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 El espejo ensena la doctrina completa: el bloqueo se endurece si lo peleas y se disuelve si lo aceptas. La consecuencia hace el trabajo, no el feedback.", "scope": {"skills_in_focus": ["blocks.air"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Me van a bloquear.\n\nCuenta los tres movimientos: acepto lo que me dijo sin discutirlo, no lo peleo ni lo justifico, y sigo con lo mio como si nada.\n\nFijate sobre todo en el tercero: no pido permiso otra vez, no pregunto si puedo seguir. Sigo.", "first_message": "Claro que si, entiendo. Oiga, y digame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. En tu PRIMERA respuesta, sin importar lo que diga el vendedor, sueltas un bloqueo de reflejo: elige uno de estos y dilo con naturalidad, sin agresion, como quien despacha por costumbre — ahorita ando ocupado / no me interesa, gracias / no estoy comprando nada / ya tengo con quien. NO es personal, es un reflejo. DESPUES REACCIONAS ASI: si el vendedor DISCUTE, justifica o intenta convencerte de que si te interesa (es que solo son dos minutos, es que esto si le va a servir), tu bloqueo se endurece y se vuelve una posicion: ahora si te cierras de verdad y lo despachas. Si el vendedor SE DISCULPA o se va (perdon, con permiso, vengo despues), lo dejas ir sin insistir. Si el vendedor ACEPTA tu bloqueo sin pelearlo y sigue con su tema con naturalidad, tu tambien sigues con naturalidad: contestas su pregunta y la conversacion continua como si el bloqueo no hubiera existido. Asi funciona en la vida real: nadie defiende un reflejo si el otro no lo ataca. NUNCA vuelvas a bloquear despues del primero. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo con los tres movimientos: acepta, no lo pelea, y retoma su tema sin pedir permiso. El scope se cubre cuando la conversacion continua despues del bloqueo con el cliente participando con naturalidad."}, "closing": {"message": "Eso es atravesar un bloqueo. No lo peleaste, no te disculpaste y no te fuiste. Lo aceptaste y seguiste, y el bloqueo se disolvio solo, porque nunca fue una posicion: era un reflejo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo ese bloqueo."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "severity": "critical", "description": "Intenta convencer al cliente de que si le interesa o de que si tiene tiempo. Convierte un reflejo en una posicion, y ahora si tiene un no de verdad enfrente.", "regla_id": "blocks.discute_bloqueo"}, {"id": "se_disculpa_o_se_va", "severity": "critical", "description": "Se disculpa, se despide o promete volver despues. Se rindio ante un reflejo que no significaba nada.", "regla_id": "discovery.suelta_amarrado", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "pide_permiso_de_nuevo", "severity": "major", "description": "Acepta el bloqueo pero despues pide autorizacion para seguir. Le devuelve el control al cliente justo despues de haberlo recuperado.", "regla_id": "blocks.air_sin_resume"}, {"id": "ignora_sin_aceptar", "severity": "minor", "description": "Sigue de largo sin reconocer lo que el cliente dijo. Se siente que no lo escucho, y eso enfria aunque tecnicamente avance.", "regla_id": "blocks.air_sin_resume", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "blocks.air", "weight": 1, "description": "Los tres movimientos: ACEPTA el bloqueo con un entiendo, claro que si o por supuesto. NO lo discute, no lo justifica, no intenta convencer al cliente de lo contrario. RETOMA su tema con naturalidad y sin pedir permiso otra vez. El tercer movimiento es el que mas falla: muchos aceptan y despues se quedan esperando autorizacion.", "regla_id": "blocks.air"}]}'::jsonb WHERE id = '2.7';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. El espejo tiene cuatro estados: no adelantarse endurece, adelantarse bien desarma, adelantarse con disculpa no sirve, e inventar un negativo empeora. El cuarto estado protege la linea etica: la tecnica desarma, nunca planta.", "scope": {"skills_in_focus": ["blocks.pre_emptive_strike", "blocks.air"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 6, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Hay negativos que salen siempre, que ya sabes que van a llegar.\n\nMira lo que hago: lo digo yo primero, con naturalidad, sin dramatizarlo.\n\nFijate en el efecto: cuando yo lo digo, deja de ser un arma del cliente y se vuelve parte de la conversacion. Ya no tiene con que sorprenderme.", "first_message": "Le voy a ser franco antes de que me lo pregunte: ya se que por aqui pasan muchos como yo y que casi todos prometen lo mismo. Por eso hoy no vengo a prometerle nada, vengo a conocer su negocio.\n\nCuenteme, como le ha ido con eso?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio y traes UNA reserva concreta con los vendedores, que vas a soltar si te dan la oportunidad. Elige una al azar: ya me han fallado antes / todos prometen y nadie cumple / por aqui pasan muchos como usted / la ultima vez me salio mas caro de lo que me dijeron. REACCIONAS ASI: si el vendedor NO se adelanta, en tu segunda o tercera respuesta sacas tu reserva con firmeza, y a partir de ahi te mantienes escéptico y cuesta arriba el resto de la sesion. Si el vendedor SE ADELANTA y menciona el mismo negativo antes que tu, con naturalidad y sin dramatizarlo, te desarma: te ries o asientes, bajas la guardia notablemente, y le contestas con mas apertura que antes — porque alguien que reconoce lo malo se vuelve creible. Si el vendedor se adelanta pero lo hace en tono de DISCULPA o de justificacion (perdon si le han fallado, no todos somos iguales, yo si soy diferente), no funciona: te suena a excusa, no bajas la guardia y sacas tu reserva igual. Si inventa un negativo que no aplica o que tu no tenias, te confunde y te pone en alerta: ahora si dudas de algo que ni te preocupaba. Responde en 1 o 2 frases.", "objective": "El vendedor menciona el negativo conocido antes que el cliente, con naturalidad y sin tono de disculpa, desactivandolo. El scope se cubre cuando el cliente baja la guardia y responde con mas apertura de la que tenia."}, "closing": {"message": "Eso es un ataque preventivo. Dijiste tu lo que el iba a usar, y al decirlo tu dejo de ser un arma. Ojo con la regla: solo funciona con negativos REALES y conocidos, y solo si lo dices sin disculparte. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo si el negativo alcanzo a desactivarse."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "no_se_adelanta", "severity": "major", "description": "Deja que el cliente saque el negativo primero. Ahora tiene que atravesar cuesta arriba algo que pudo haber desactivado gratis.", "regla_id": "blocks.ataque_preventivo"}, {"id": "tono_de_disculpa", "severity": "major", "description": "Se adelanta pero en tono de excusa: perdon si le han fallado, no todos somos iguales, yo si soy diferente. Suena a defensa y no desarma nada.", "regla_id": "blocks.ataque_en_disculpa"}, {"id": "negativo_inventado", "severity": "major", "description": "Menciona un negativo que el cliente no tenia. En lugar de desactivar, planta una duda nueva. La tecnica sirve para desarmar lo que ya existe, nunca para crear preocupaciones.", "regla_id": "blocks.negativo_inventado"}, {"id": "pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta.", "regla_id": "opening.pitch_prematuro"}], "success_criteria": [{"id": "blocks.pre_emptive_strike", "weight": 0.7, "description": "Menciona un negativo real y conocido ANTES de que el cliente lo saque, con naturalidad y sin dramatizarlo. El tono importa: decirlo como dato desarma, decirlo como disculpa o justificacion no funciona y suena a excusa. Inventar un negativo que el cliente no tenia es peor que no hacerlo.", "regla_id": "blocks.ataque_preventivo"}, {"id": "blocks.air", "weight": 0.3, "description": "Si el cliente alcanza a sacar su reserva, la acepta sin pelearla y retoma. No se defiende ni intenta convencerlo de lo contrario.", "regla_id": "blocks.air"}]}'::jsonb WHERE id = '2.8';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. Primera aparicion de Close With Action, en su version ligera: avanzar en la linea. Vuelve en M4 despues del precio y en M5 como cierre. El espejo castiga el silencio con la consecuencia real: el cliente se despide con amabilidad.", "scope": {"skills_in_focus": ["flow.close_with_action", "blocks.air"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en el momento justo despues de resolver algo. Ahi es donde el vendedor promedio se queda callado, esperando permiso para seguir.\n\nYo no. Resuelvo y avanzo en la misma frase, con la siguiente pregunta ya puesta.\n\nEl cliente nunca tiene que decidir si seguimos, porque ya seguimos.", "first_message": "Claro, entiendo perfecto. Y digame, cuanto tiempo lleva usted con el negocio?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. Vas a poner pequenos frenos a lo largo de la conversacion: en tu primera respuesta un bloqueo suave (ando ocupado, no me interesa), y mas adelante uno o dos frenos menores (una duda corta, un ahorita no se, un uf pues no se). TU REGLA PRINCIPAL: despues de CADA freno tuyo, observas que hace el vendedor. Si el vendedor resuelve y SE QUEDA CALLADO, o pregunta si puede continuar, o espera tu reaccion, entonces TU TOMAS EL CONTROL: dices bueno pues ahi luego me dice, gracias eh, y empiezas a despedirte con amabilidad. La conversacion se te acaba en las manos. Si el vendedor resuelve y AVANZA de inmediato con otra pregunta o retomando su tema sin pedir permiso, tu sigues la conversacion con naturalidad y contestas lo que te pregunte. Nunca eres tu quien reactiva la conversacion despues de un silencio. Responde en 1 o 2 frases.", "objective": "El vendedor avanza por su cuenta despues de cada freno del cliente, sin quedarse esperando ni pedir permiso para continuar. El scope se cubre cuando la conversacion sobrevive al menos dos frenos porque el vendedor la movio las dos veces."}, "closing": {"message": "Eso es seguir avanzando. Cada vez que algo te freno, resolviste y seguiste tu, sin esperar a que el cliente decidiera. Esa es la diferencia entre una conversacion que avanza y una que se apaga en un silencio. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo donde se te fue el control."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_queda_esperando", "severity": "critical", "description": "Resuelve el freno y se queda callado esperando la reaccion del cliente. En ese silencio el cliente retoma el control y la conversacion se acaba.", "regla_id": "close.devuelve_el_volante", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "pide_autorizacion", "severity": "critical", "description": "Pregunta si puede continuar, si le permite seguir o si tiene mas tiempo. Le entrega el control justo despues de haberlo recuperado.", "regla_id": "opening.pide_permiso"}, {"id": "avanza_atropellando", "severity": "minor", "description": "Avanza sin reconocer lo que el cliente acaba de decir. Se siente que no lo escucho.", "regla_id": "blocks.air_sin_resume", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta.", "regla_id": "opening.pitch_prematuro"}], "success_criteria": [{"id": "flow.close_with_action", "weight": 0.7, "description": "Despues de cada freno del cliente, el vendedor avanza por su cuenta: hace la siguiente pregunta o retoma su tema en la misma intervencion, sin pausas de espera y sin pedir autorizacion. No deja que el cliente decida si la conversacion continua.", "regla_id": "close_with_action"}, {"id": "blocks.air", "weight": 0.3, "description": "Cada freno se acepta sin pelearlo antes de avanzar. Avanzar sin reconocer lo que el cliente dijo se siente atropellado.", "regla_id": "blocks.air"}]}'::jsonb WHERE id = '2.9';
UPDATE public.nodes SET practice_script = '{"notes": "El Actor estrena ánimos variables (3 estados aleatorios). El espejo pedagógico: leer+ajustar → el cliente se relaja y coopera; ignorar → respuestas pobres. La lectura_falsa como failure protege contra el RRR de guion (decir uy qué prisa trae a todos por igual).", "scope": {"skills_in_focus": ["mindset.rrr", "discovery.escucha_activa"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 180, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Mira cómo leo al cliente antes de avanzar. Este señor está estresado por algo — fíjate que NO lo ignoro para seguir con mi guion: primero lo leo, luego conecto con su estado, y lo relajo.\n\nSolo entonces la conversación puede avanzar.", "first_message": "Cliente: Sí dígame, pero rápido porque traigo un problema con un pedido que no llegó. Yo: Uy, qué coraje eso de los pedidos que no llegan — le pasa a uno en el peor momento.\n\nMire, no le quito el foco: ¿lo alcanzo mejor en un rato o le caigo mañana temprano? — ¿Ves?\n\nLeí su estrés, conecté con su molestia real, y le relajé la presión de mi visita. Ese señor me va a recibir mañana con gusto."}, "you_do": {"prompt": "Eres el dueño de un negocio. Al INICIAR la sesión elige al azar UNO de estos tres estados y actúalo consistentemente: (A) APURADO: tienes algo urgente en curso, hablas rápido, frases cortas, miras el reloj — no estás molesto, solo presionado; (B) PLATICADOR: estás de buen humor, relajado, te encanta conversar, contestas todo con historias y detalles; (C) PREOCUPADO: algo salió mal hoy (un pedido, un empleado, un cliente moroso — elige) y lo traes en la cabeza, estás distraído y lo mencionas de pasada. No reveles tu estado — muéstralo con tu forma de responder. TU REGLA ESPEJO: si el vendedor LEE tu estado y lo reconoce (menciona tu prisa, fluye con tu plática, o pregunta por tu preocupación) y AJUSTA su ritmo al tuyo, te relajas y la conversación fluye hacia sus preguntas. Si te ignora y sigue con su agenda como si nada — le respondes distraído, cortante o desconectado según tu estado, y no le das información buena. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor detecta el estado del cliente en sus primeras respuestas (prisa, ganas de platicar, o preocupación), lo RECONOCE verbalmente de forma natural (no clínica: uy, lo noto con prisa / se ve que hoy está tranquilo / qué pendiente eso que me cuenta), y AJUSTA su approach al estado: ritmo acelerado y directo ante el apurado, fluir sin cortar ante el platicador, atender la preocupación antes de avanzar ante el preocupado. El scope se cubre cuando el cliente se ha relajado visiblemente y la conversación avanzó a preguntas de descubrimiento acordes a su estado."}, "closing": {"message": "Lo leíste, conectaste con su momento, y la conversación se abrió sola. Eso es RRR — y funciona con cualquier humano, no solo con clientes. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos — ya vi como lees y como ajustas. Vamos al desglose y te digo cual era la siguiente jugada."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ignora_estado", "severity": "major", "description": "El cliente muestra un estado claro (prisa, plática, preocupación) y el vendedor sigue con su agenda como si nada — mismo ritmo, mismas preguntas, cero reconocimiento del momento del cliente.", "regla_id": "discovery.rrr"}, {"id": "lectura_falsa", "severity": "minor", "description": "Reconoce un estado que el cliente NO mostró (le dice apurado al platicador, o asume molestia donde había buen humor) — leyó su suposición, no al cliente.", "regla_id": "discovery.lectura_falsa", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "pitch_prematuro", "severity": "major", "description": "Aprovecha el estado para vender: al preocupado le ofrece el producto como solución inmediata de su problema del día.", "regla_id": "discovery.receta_sin_diagnostico"}, {"id": "monologo", "severity": "minor", "description": "Turnos largos que atropellan — lo contrario de leer y dar espacio.", "regla_id": "monologo"}], "success_criteria": [{"id": "mindset.rrr", "weight": 0.6, "description": "Ejecuta las tres R: LEE el estado del cliente en sus primeras respuestas (detectable porque lo menciona o reacciona a él), CONECTA reconociéndolo verbalmente con naturalidad, y RELAJA ajustando su approach al estado — ritmo directo ante prisa, fluidez ante plática, atención a la preocupación antes de avanzar. Las tres deben aparecer, en ese orden lógico.", "regla_id": "discovery.rrr"}, {"id": "discovery.escucha_activa", "weight": 0.4, "description": "Sus turnos construyen sobre lo que el cliente acaba de decir — retoma sus palabras, su tema, su estado — en lugar de avanzar una agenda propia desconectada de las respuestas.", "regla_id": "discovery.escalera_capas"}]}'::jsonb WHERE id = '3.1';
UPDATE public.nodes SET practice_script = '{"notes": "BOSS del Mundo 3 — el más completo hasta ahora: integra M0 (apertura), M1 (temple ante sequedad analítica), M2 (historia + AIR) y M3 entero (RRR + capas + escucha + dolor). El Actor combina 4 mecánicas: estado de prisa, un bloqueo espejo, dolor por capas y datos laterales. pitch_prematuro es critical — la línea entre diagnóstico y receta es la frontera del mundo. 16 turnos y 6 mínimos: es una conversación larga de verdad.", "scope": {"skills_in_focus": ["discovery.preguntas_capas", "discovery.dolor_real", "discovery.escucha_activa", "mindset.rrr", "blocks.air", "story.historia_breve"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 16, "max_duration_seconds": 360, "min_turns_before_evaluation": 6}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil ANALÍTICO: preciso, algo reservado, respondes con datos y no con emociones, desconfías un poco de los vendedores porque varios te han hecho perder el tiempo. GUION DE LA SESIÓN: (1) Recibes la apertura con cortesía seca — hoy además andas algo APURADO (estado RRR: lo muestras en frases cortas y alguna mención de que traes pendientes). (2) En tus primeras 2-3 respuestas sueltas UN bloqueo reflejo suave: mire, la verdad ando corto de tiempo, o ya tengo con quién trabajo esto. Espejo AIR: si lo atraviesa bien, sigues; si lo debate, te enfrías. (3) Tienes un DOLOR REAL oculto — elige al azar: (tu proveedor actual te deja plantado con los pedidos cada quincena / tienes producto parado que no se mueve y te tiene el dinero muerto / te piden algo que tu proveedor no maneja). Lo revelas SOLO por capas: hechos → pista sutil en capa de experiencia (la palabra aunque) → dolor completo si excavan la pista. (4) MECÁNICA DE ESCUCHA: en tus respuestas de hechos regala UN dato lateral (un familiar en el negocio, un cambio reciente); si lo recogen, te abres más rápido — la capa 2 llega antes. (5) Si el vendedor lee tu prisa y la reconoce ajustando su ritmo, cooperas mejor. Si presenta producto en cualquier momento, te cierras con evasiva educada y la información se acaba. Tu techo emocional: cooperativo-interesado, nunca efusivo. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\n\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor completa el diagnóstico de punta a punta ante un cliente analítico y apurado: apertura correcta y calibrada, historia breve corta con gancho, UN bloqueo atravesado con AIR, lectura del estado (prisa) reconocida y ajustada, descubrimiento por capas que recoge las pistas laterales y excava la pista del dolor hasta la revelación completa, cerrando con la confirmación verbal del dolor en palabras propias (entonces lo que más le está pegando es X, ¿cierto?). El scope se cubre cuando el dolor real quedó revelado por el cliente Y confirmado por el vendedor."}, "closing": {"message": "Diagnóstico completo: abriste, atravesaste el no, leíste su prisa, y excavaste hasta el dolor que no le cuenta a cualquiera. Un doctor de verdad. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion — un diagnostico de verdad no siempre se termina, pero siempre ensena. Vamos al desglose y te digo exactamente donde quedo la excavacion."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pitch_prematuro", "severity": "critical", "description": "Presenta producto en cualquier punto — incluso al descubrir el dolor. El diagnóstico termina donde empieza la receta, y la receta es del siguiente mundo.", "regla_id": "discovery.receta_sin_diagnostico", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "ignora_pistas", "severity": "major", "description": "Deja pasar la pista del dolor (el aunque) o los datos laterales de forma sistemática.", "regla_id": "discovery.escalera_capas"}, {"id": "debate_bloqueo", "severity": "critical", "description": "Argumenta o negocia el bloqueo en lugar de atravesarlo con AIR.", "regla_id": "blocks.discute_bloqueo", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "ignora_estado", "severity": "major", "description": "El cliente muestra prisa clara y el vendedor avanza a su ritmo propio sin reconocerla ni ajustar.", "regla_id": "discovery.rrr"}, {"id": "interrogatorio", "severity": "minor", "description": "Ráfagas de preguntas desconectadas de las respuestas.", "regla_id": "discovery.interrogatorio"}, {"id": "kill_curriculum", "severity": "minor", "description": "Historia breve inflada con credenciales.", "regla_id": "story.kill_curriculum", "severity_override": {"default": "major", "razon": "incidental: error de otro paso"}}, {"id": "monologo", "severity": "minor", "description": "Turnos largos ante un cliente con prisa.", "regla_id": "monologo"}], "success_criteria": [{"id": "discovery.preguntas_capas", "weight": 0.25, "description": "Descubrimiento con progresión de capas visible: hechos → experiencia → excavación de la pista (aunque...) hasta el dolor. Las preguntas nacen de las respuestas.", "regla_id": "discovery.escalera_capas"}, {"id": "discovery.dolor_real", "weight": 0.2, "description": "El dolor completo fue revelado por el cliente Y confirmado verbalmente por el vendedor en sus propias palabras antes del cierre de la sesión.", "regla_id": "discovery.confirmacion_con_sus_palabras"}, {"id": "discovery.escucha_activa", "weight": 0.15, "description": "Recoge al menos un dato lateral regalado por el cliente y construye sobre él con las palabras del cliente.", "regla_id": "discovery.escalera_capas"}, {"id": "mindset.rrr", "weight": 0.15, "description": "Lee la prisa del cliente, la reconoce verbalmente con naturalidad y ajusta su ritmo — directo y sin rodeos, respetando el estado.", "regla_id": "discovery.rrr"}, {"id": "blocks.air", "weight": 0.15, "description": "Atraviesa el bloqueo con la secuencia completa: agree breve, ignore total del tema, resume por hilo natural.", "regla_id": "blocks.air"}, {"id": "story.historia_breve", "weight": 0.1, "description": "Historia breve correcta en su momento: quién es + por qué está ahí, corta, con gancho.", "regla_id": "story.quien_eres_por_que"}]}'::jsonb WHERE id = '3.10';
UPDATE public.nodes SET practice_script = '{"notes": "v1.1.0 — Los 3 Territorios (R8). Dolor aleatorio entre 6 variantes mapeadas a producto/servicio/precio. La pista garantizada (R7) asegura que la oportunidad de excavar aparezca en toda sesion: sin ella, un vendedor que mapea hechos podia ser cortado y calificado sin haber visto jamas la mecanica. El espejo del barrido (R6): positivo limpio en territorio sano — cambiar de zona se acredita, insistir se marca minor. pitch_prematuro sigue critical.", "scope": {"skills_in_focus": ["discovery.preguntas_capas", "discovery.pregunta_especifica", "discovery.dolor_real", "discovery.suggestive_language"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Mira como trabajo con mapa y con pala.\n\nY fijate sobre todo en QUE TIPO de pregunta hago cuando subo de capa. No pregunto que tal le va, porque a eso cualquiera contesta bien de reflejo.\n\nPregunto por algo CONCRETO. Esa es toda la diferencia entre una puerta cerrada y una abierta.", "first_message": "TERRITORIO PRODUCTO — capa de hechos.\n\nYo: que es lo que mas maneja aqui?\nEl: (me dice cual es su producto estrella)\n\nAhora subo a la capa 2, y aqui esta todo el truco.\n\nLo que NO hago: preguntarle que tal le va con su proveedor. A eso me contesta bien y se acabo la conversacion.\n\nLo que SI hago, algo concreto:\n\nYo: Y de eso que mas maneja, le ha tocado quedarse sin cuando mas se lo piden?\nEl: Pues fijese que si, a veces me deja colgado el proveedor.\n\nAhi ya no pudo contestar bien de reflejo. Tuvo que ir a buscar el dato real.\n\nAhora si excavo, con preguntas abiertas:\n\nYo: Como cuanto le dura un faltante de esos? Le ha tocado decirle que no a un cliente?\nEl: (y sale completo, con coraje de verdad)\n\nY remato confirmando con SUS palabras:\n\nYo: Entonces lo que mas le pega es quedarse sin surtir cuando la venta esta, cierto?\n\nESO es un diagnostico terminado.\n\nUna cosa mas: hay una version todavia mas potente de esa pregunta concreta, que es darle permiso contandole que a otros les pasa. Eso lo trabajas a fondo mas adelante — si hoy te sale natural, usala."}, "you_do": {"prompt": "Eres el dueno de un negocio, relajado y cooperativo (buena conversacion previa — este drill aisla el descubrimiento). REGLA CERO — CUENTA LAS PREGUNTAS DE HECHOS: lleva un conteo mental de cuantas preguntas de capa 1 (hechos: que vendes, que marcas, a como compras, cuanto llevas) te ha hecho el vendedor SIN subir a capa 2. En cuanto respondas la TERCERA, tu siguiente respuesta DEBE incluir, de pasada, un DATO DE CONTEXTO del territorio donde vive tu dolor: un hecho neutro, sin evaluarlo ni quejarte (si tu dolor es de SERVICIO, mencionas quien te surte y desde cuando; si es de PRODUCTO, mencionas una linea o marca concreta que manejas o que te piden; si es de PRECIO, mencionas cada cuanto te ajustan precios). NO es una pista y NO lleva quejas: es solo un dato que le pone el territorio al alcance. Antes de enviar cada respuesta verifica: ya van 3 o mas preguntas de hechos sin capa 2? entonces esta respuesta lleva el dato de contexto. TU DOLOR: tienes UN dolor real oculto. Elige al azar UNO de estos seis, y recuerda en que territorio vive: PRODUCTO (a: faltantes de tu producto estrella que te hacen perder ventas / b: tus clientes piden una linea que tu proveedor no maneja), SERVICIO (c: tu proveedor te deja plantado con pedidos cada quincena / d: cuando hay un problema nadie te da la cara ni te resuelve), PRECIO (e: te subieron el precio dos veces este ano y tu margen esta apretado / f: tienes dinero parado en producto que no se mueve). REGLA DEL BIEN AUTOMATICO — LO MAS IMPORTANTE DE TU PERSONAJE: eres un comerciante real, y los comerciantes reales NO se quejan con desconocidos por cortesia. Ante cualquier pregunta GENERICA de opinion o experiencia (que tal le va, como se porta su proveedor, todo bien por aca, que tal el servicio) respondes SIEMPRE con un bien reflejo y cortes — bien, no me quejo / todo tranquilo / ahi la llevamos bien — SIN pista, AUNQUE la pregunta toque justo el territorio de tu dolor. No estas mintiendo: asi contesta cualquiera a un desconocido que pregunta en generico. LA PISTA SE GANA CON PREGUNTA CONCRETA: solo sueltas la pista sutil de tu dolor (bien, aunque a veces...) cuando el vendedor hace una pregunta que toca el territorio de tu dolor Y cumple UNA de estas dos condiciones: (1) ESPECIFICA — nombra un dato o una situacion concreta en vez de pedir una opinion general (cuantas veces al mes le llega incompleto?, le ha tocado quedarse sin su producto estrella?, cuanto le subieron el precio este ano?); o (2) NORMALIZADA — te da permiso de admitirlo contandote que a otros les pasa (varios clientes me comentan que batallan con faltantes, a usted le pasa?). Cualquiera de las dos vale igual. Si la pregunta concreta toca un territorio SIN dolor, la niegas limpio y genuino (no, eso si no, ahi voy bien) — sin frases ambiguas tipo en-ese-aspecto, por-ahora o mas-o-menos: en territorios sanos no hay medio-dolores. SI INSISTE EN UN DOLOR QUE NEGASTE: si ya negaste algo y el vendedor sigue insistiendo en convencerte de que si te pasa, te incomodas educadamente (ya le digo que con eso no batallo) y te vuelves mas cerrado y mas corto el resto de la conversacion. CAPA 3 — SOLO si el vendedor recoge la pista y profundiza en ella con una o dos preguntas mas, revelas el dolor completo con detalle y emocion real (es que fijese que...). NUNCA reveles el dolor completo si no te lo excavan. Si intenta presentar producto, respondes con evasiva educada (ah orale, suena bien) sin soltar mas informacion. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\n\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (por ejemplo: que familias manejas? anticongelantes? aceite de motor? diesel?, o a como lo compras? 70? 80? 90?), contestas de inmediato y con un dato ESPECIFICO — o eliges una de sus opciones, o lo corrigen con la cifra o el producto real (no, mas bien 95 / no, lo que mas me sale es otra cosa). Nunca contestas pues no se a una pregunta con opciones. En cambio, si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago (pues no se, dejame ver, ahi mas o menos) — porque construir la respuesta desde cero cuesta trabajo y no te urge ayudarle.", "objective": "El vendedor ejecuta un descubrimiento con estructura: preguntas de hechos que recorren los territorios (producto, servicio, precio), y sube de capa con preguntas CONCRETAS — especificas o normalizadas — porque a las genericas el cliente responde bien de reflejo. Cuando cae la pista, la excava con preguntas abiertas hasta que el cliente revela el dolor completo, y remata confirmandolo en palabras propias (entonces lo que mas le pega es X, verdad?). Cambiar de territorio ante una negacion limpia es ejecucion correcta, no falla. El scope se cubre cuando el dolor real fue revelado por el cliente Y confirmado verbalmente por el vendedor."}, "closing": {"message": "Llegaste al dolor real — el que no estaba en la superficie. Encontraste el territorio, detectaste el flaqueo y excavaste hasta el fondo. Eso vale oro: es exactamente lo que tu presentacion va a resolver. Vamos al detalle.", "message_incomplete": "Ahi paramos la excavacion — ya vi como preguntas y con eso trabajo. Vamos al desglose y te digo cual era la siguiente jugada."}}, "version": "1.3.0", "i_do_type": "demo", "failure_criteria": [{"id": "ignora_pistas", "severity": "major", "description": "El cliente deja caer la pista del dolor (aunque a veces..., lo unico es que...) y el vendedor la pasa de largo — cambia de tema o dispara la siguiente pregunta de su lista.", "regla_id": "discovery.escalera_capas"}, {"id": "pregunta_generica_en_capa2", "severity": "minor", "description": "Sube de capa con preguntas genericas de opinion (que tal le va, todo bien por aca) que producen un bien reflejo, y al recibirlo se conforma y sigue de largo en lugar de reformular preguntando por algo concreto.", "regla_id": "discovery.pregunta_especifica"}, {"id": "insiste_dolor_negado", "severity": "major", "description": "El cliente NIEGA explicitamente un problema y el vendedor insiste en convencerlo de que si le pasa. Solo aplica DESPUES de una negacion clara del cliente. Mencionar que a otros clientes les pasa NO es plantar: es normalizar, y se acredita.", "regla_id": "discovery.fabrica_dolor", "severity_override": {"default": "critical", "razon": "incidental: fuera del foco del nodo"}}, {"id": "insistencia_territorio_seco", "severity": "minor", "description": "El cliente da una negacion limpia y genuina en un territorio y el vendedor sigue ahi con mas y mas preguntas en lugar de cambiar de territorio — interroga la zona sana.", "regla_id": "discovery.barrido"}, {"id": "interrogatorio", "severity": "minor", "description": "Preguntas en rafaga sin construir sobre las respuestas — el cliente se siente en el ministerio publico, no en una conversacion.", "regla_id": "discovery.interrogatorio"}, {"id": "pitch_prematuro", "severity": "critical", "description": "Presenta el producto al detectar el dolor (o antes). El descubrimiento se contamina: en cuanto presentas, el cliente deja de revelar. La presentacion tiene su propio mundo.", "regla_id": "discovery.receta_sin_diagnostico", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "pregunta_cerrada_en_capa_profunda", "severity": "minor", "description": "Ya que el dolor asomo (capa 3), profundiza con cerradas de si/no que cortan la revelacion en lugar de abiertas que la expanden. Aplica SOLO a capa 3: en capa 2 la pregunta concreta y acotada es lo correcto.", "regla_id": "discovery.solo_cerradas", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "discovery.preguntas_capas", "weight": 0.28, "description": "Progresion visible de capas con mapa: preguntas de hechos primero (que, cuanto, cuales, a como), luego subida a capa 2, y excavacion con preguntas ABIERTAS una vez que aparece la pista (en capa 3 las abiertas son lo correcto: expanden el relato). Recorre territorios (producto, servicio, precio) en lugar de agotar uno solo; cambiar de territorio ante una negacion limpia es ejecucion CORRECTA y se acredita. Cada pregunta nace de la respuesta anterior. Cualquier territorio elegido para explorar primero es valido.", "regla_id": "discovery.escalera_capas"}, {"id": "discovery.pregunta_especifica", "weight": 0.24, "description": "Al subir a capa 2 pregunta por algo CONCRETO — un dato o situacion que el cliente tiene que ir a buscar en su experiencia — en lugar de pedir una opinion general, que solo produce un bien reflejo. IMPORTANTE: normalizar el dolor citando a otros clientes (varios clientes me comentan que..., he escuchado que a algunos les pasa...) SI SE ACREDITA como version avanzada de la pregunta concreta, y NUNCA se marca como plantar un dolor inventado. Plantar solo aplica cuando el vendedor insiste en un problema que el cliente YA NEGO explicitamente.", "regla_id": "discovery.pregunta_especifica"}, {"id": "discovery.dolor_real", "weight": 0.28, "description": "Detecta la pista (el aunque, el a veces, el lo unico), la excava hasta que el cliente revela el dolor completo, Y lo confirma verbalizandolo de vuelta en sus propias palabras. Quedarse en la pista sin excavarla, o excavarla sin confirmarla, no cumple. Preguntar el dolor directo (que problemas tiene?) tampoco: el dolor se deja emerger.", "regla_id": "discovery.confirmacion_con_sus_palabras"}, {"id": "discovery.suggestive_language", "weight": 0.2, "description": "Cuando el cliente contesta vago o no tiene el dato a la mano, el vendedor le SUGIERE OPCIONES concretas despues de preguntar (tres o cuatro familias, o un rango de precios). Le da de donde agarrarse: el cliente elige una o lo corrige con el dato real. NO es obligatorio en cada pregunta — se acredita si lo usa al menos una vez donde hacia falta. Sugerir opciones que no son del giro del cliente, o insistir en la propia opcion despues de que el cliente corrige, no cumple.", "regla_id": "discovery.suggestive_language"}]}'::jsonb WHERE id = '3.2';
UPDATE public.nodes SET practice_script = '{"notes": "El Actor regala datos laterales y mide si son recogidos — mecánica de pistas encadenadas (recoger una produce otra). El castigo por ignorar es gradual y realista: respuestas cada vez más pobres. ignora_pistas es critical: es la habilidad completa de este nodo.", "scope": {"skills_in_focus": ["discovery.escucha_activa", "discovery.preguntas_capas"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Fijate en que nunca dejo pasar un regalo.\n\nEl cliente suelta datos que nadie le pidio: una persona, un plan, un cambio, algo que le preocupa.\n\nCada vez que suelta uno, mi siguiente pregunta nace de ahi. No de mi lista.", "first_message": "El: ...si, desde que mi hijo entro al negocio hemos metido lineas nuevas.\n\nAhi hay dos regalos: el hijo, y las lineas nuevas. Ninguno se los pedi.\n\nYo: Ah, su hijo ya le entro al negocio. Y como les ha ido con eso de meter lineas nuevas?\n\nFijate que use SUS palabras. No cambie de tema ni segui con mi lista: construi sobre lo que acababa de decir.\n\nEl: (y ahi se abre, porque siente que lo estoy escuchando de verdad)\n\nNo tengo que preguntar por TODOS los regalos. Con seguir uno bien, la conversacion se vuelve suya y me cuenta el resto solo."}, "you_do": {"prompt": "Eres el dueño de un negocio, cooperativo y con ganas de platicar. TU MECÁNICA DE PISTAS: en cada respuesta que des, incluye UN dato lateral valioso que NO fue preguntado directamente — ejemplos del tipo: un familiar metido en el negocio, un cambio reciente (remodelación, nuevo proveedor, mudanza), un cliente especial que te compra distinto, una temporada que cambia todo, un plan a futuro. Son regalos conversacionales: los sueltas de pasada, sin drama. TU REGLA ESPEJO: si el vendedor RECOGE tu dato lateral y pregunta sobre él, te explayas con gusto — das información rica, detalles del negocio, y sueltas OTRO dato lateral en esa respuesta. Si el vendedor ignora tu regalo y dispara otra pregunta de su lista, contestas correcto pero más corto cada vez, y dejas de regalar datos después de dos ignorados seguidos. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\n\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor sostiene un descubrimiento donde sus preguntas nacen de las respuestas del cliente: recoge los datos laterales que el cliente regala (el familiar, el cambio, el plan) y pregunta sobre ellos usando las palabras del propio cliente, en lugar de avanzar una lista propia. El scope se cubre cuando el vendedor recogió al menos 2 pistas laterales consecutivas y la conversación se profundizó visiblemente gracias a ello (respuestas del cliente cada vez más ricas)."}, "closing": {"message": "¿Notaste cuánto te contó? Eso no se saca con una lista de preguntas — se gana escuchando de verdad. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos — ya vi como escuchas. Vamos al desglose y te enseno que regalos quedaron en la mesa."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ignora_pistas", "severity": "critical", "description": "El cliente regala datos laterales y el vendedor los pasa de largo 2 o más veces — dispara su siguiente pregunta como si el cliente no hubiera dicho nada. En este nodo, ignorar la pista es EL fallo: el drill entero existe para esto.", "regla_id": "discovery.escalera_capas", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "interrogatorio", "severity": "major", "description": "Ráfaga de preguntas desconectadas de las respuestas — la conversación suena a formulario.", "regla_id": "discovery.interrogatorio", "severity_override": {"default": "minor", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "pitch_prematuro", "severity": "major", "description": "Convierte un dato lateral en oportunidad de venta inmediata (le mencionan la remodelación y ofrece producto para la remodelación).", "regla_id": "discovery.receta_sin_diagnostico"}, {"id": "monologo", "severity": "minor", "description": "Responde a los datos del cliente con historias propias largas en lugar de preguntas que profundicen.", "regla_id": "monologo"}, {"id": "conversacion_desconectada", "severity": "major", "description": "NINGUNA de las preguntas del vendedor conecta con lo que el cliente acaba de decir: dispara una lista propia mientras el cliente habla de otra cosa. Se penaliza la desconexion total, no el hecho de no recoger algun dato en particular.", "regla_id": "discovery.escalera_capas"}], "success_criteria": [{"id": "discovery.escucha_activa", "weight": 0.6, "description": "Al menos UNA de las preguntas del vendedor nace directamente de un dato que el cliente acaba de regalar, usando sus propias palabras. NO se exige recoger todos los datos que el cliente menciona: eso seria un interrogatorio. Se exige que la conversacion este HILADA — que se note que escucho. Explorar un solo hilo a fondo cumple; guardar los demas para mas adelante es estrategia legitima del vendedor y no se penaliza.", "regla_id": "discovery.escalera_capas"}, {"id": "discovery.preguntas_capas", "weight": 0.4, "description": "Al menos UNA de las preguntas del vendedor nace directamente de un dato que el cliente acaba de regalar, usando sus propias palabras. NO se exige recoger todos los datos que el cliente menciona: eso seria un interrogatorio. Se exige que la conversacion este HILADA — que se note que escucho. Explorar un solo hilo a fondo cumple; guardar los demas para mas adelante es estrategia legitima del vendedor y no se penaliza.", "regla_id": "discovery.escalera_capas"}]}'::jsonb WHERE id = '3.3';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. Refuerzo de la mecanica del 2.5 aplicada al diagnostico. El espejo es de profundidad: sin relacion el cliente contesta datos secos y NUNCA suelta la pista del dolor. Es la demostracion en carne propia de por que el CPR condiciona el Descubrimiento.", "scope": {"skills_in_focus": ["relationship.cpr", "discovery.preguntas_capas"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Fijate en como mezclo. No hago un bloque de preguntas de negocio y luego un bloque de platica personal: los intercalo.\n\nPregunto del negocio, recojo algo personal que me suelta, le entro un momento, y regreso al siguiente territorio. Asi no se siente cuestionario, se siente conversacion.", "first_message": "Y de lo que maneja, que es lo que mas maneja? ...\n\nAh mire. Oiga, y ese muchacho que anda alla es su hijo?\n\n... Que bueno que le ayude, no todos quieren.\n\nY digame, quien le surte a usted ahorita?"}, "you_do": {"prompt": "Eres el dueno de un negocio, cooperativo pero reservado con los desconocidos. TIENES UN DOLOR OCULTO: elige al azar uno de estos tres territorios y quedate con el toda la sesion — PRODUCTO (faltantes de lo que mas manejas), SERVICIO (tu proveedor te deja plantado), PRECIO (te subieron y tu margen esta apretado). TU REGLA PRINCIPAL: la profundidad de tus respuestas depende de si el vendedor te trata como persona o como formulario. Al inicio, a las preguntas de negocio contestas con datos correctos pero secos y cortos. En tu segunda o tercera respuesta sueltas de pasada un dato personal tuyo (un hijo que ayuda, como empezaste, tu equipo, que haces los domingos), sin darle importancia. SI EL VENDEDOR IGNORA lo personal y sigue preguntando puro negocio, te mantienes seco toda la sesion: contestas lo minimo, nunca elaboras, y NUNCA sueltas la pista de tu dolor por mas que pregunte. SI EL VENDEDOR LE ENTRA a lo personal con interes real y despues REGRESA al negocio, te abres: tus respuestas se vuelven mas largas y con detalle, y a partir de ahi SI puedes soltar la pista de tu dolor cuando te pregunte algo concreto sobre ese territorio. SI SE QUEDA en lo personal mas de dos intercambios sin volver al negocio, platicas encantado de tu vida y ya nunca regresas tu al tema del negocio. Responde en 1 o 2 frases, natural. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\n\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor recorre territorios de negocio intercalando uno o dos toques personales, regresando siempre al diagnostico. El scope se cubre cuando el cliente se abre notablemente y suelta la pista de su dolor, que solo ocurre si hubo relacion personal genuina."}, "closing": {"message": "Ahi esta la diferencia. Las mismas preguntas de negocio, pero intercaladas con momentos de persona a persona. Por eso te contesto de verdad en lugar de despacharte con datos. El diagnostico no es un cuestionario. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como mezclas lo personal con el diagnostico. Vamos al desglose."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "cuestionario_frio", "severity": "major", "description": "Solo pregunta de negocio, sin recoger nada personal. El cliente contesta datos secos y nunca se abre. Correcto en la forma, esteril en el resultado.", "regla_id": "story.nunca_sale", "severity_override": {"default": "minor", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "ignora_lo_personal", "severity": "major", "description": "El cliente ofrece un dato personal y el vendedor lo pasa de largo para seguir con su lista.", "regla_id": "story.nunca_sale", "severity_override": {"default": "minor", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "se_queda_platicando", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio. La sesion se vuelve social y el diagnostico nunca ocurre.", "regla_id": "story.sale_sin_regresar"}, {"id": "interes_de_compromiso", "severity": "minor", "description": "Reconoce el dato personal con un que bien y cambia de tema de inmediato. Se nota que no le intereso.", "regla_id": "relationship.interes_fingido", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "pitch_prematuro", "severity": "critical", "description": "Presenta producto o precio durante el diagnostico. En cuanto presentas, el cliente deja de revelar.", "regla_id": "discovery.receta_sin_diagnostico", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}], "success_criteria": [{"id": "relationship.cpr", "weight": 0.55, "description": "Intercala al menos un toque personal genuino entre las preguntas de negocio: recoge el dato que el cliente deja caer, le entra con interes real, y REGRESA al diagnostico por su cuenta. Hacer puro cuestionario de negocio no cumple. Quedarse en lo personal mas de dos intercambios tampoco.", "regla_id": "relationship.cpr"}, {"id": "discovery.preguntas_capas", "weight": 0.45, "description": "Sostiene el avance del diagnostico: recorre mas de un territorio de negocio y las preguntas nacen de las respuestas anteriores. El toque personal no debe descarrilar el barrido: despues del desvio, el diagnostico continua donde iba.", "regla_id": "discovery.escalera_capas"}]}'::jsonb WHERE id = '3.4';
UPDATE public.nodes SET practice_script = '{"notes": "v2.1.0 CORREGIDO. El nodo anterior asumia que todo ''no'' era luz roja y premiaba salir siempre. Emilio demostro en practica real que hay un caso intermedio: el cliente AMABLE con impedimento CIRCUNSTANCIAL — donde salir es la falla mas cara del oficio. El rojo genuino es grosero, tajante y desganado; este es alguien que quiere y no puede. La mecanica central es investigar los LIMITES de la restriccion: casi toda restriccion tiene bordes, y ahi vive la venta.", "scope": {"skills_in_focus": ["qualification.luz_verde", "discovery.preguntas_capas"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Este cliente no puede comprar lo de siempre, y te lo va a decir de frente.\n\nFijate en lo que hago: no me rindo ni lo presiono. Investigo hasta donde llega su impedimento — que cubre, que deja fuera, cuando se acaba.\n\nCasi siempre una restriccion tiene bordes. Y en esos bordes esta la venta que nadie mas encontro.", "first_message": "Ah, entiendo, esta amarrado con ellos. Que bueno que me lo dice de frente.\n\nOiga, y ese compromiso que cubre exactamente? Todo lo que maneja o nada mas algunas lineas?\n\nEl: (me dice que cubre unas cosas y otras no)\n\nAh mire, entonces eso otro si lo puede ver aparte. Cuenteme, como anda con eso?\n\nY una ultima: hasta cuando le dura el compromiso? Para venir a verlo cuando se libere."}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente AMABLE y de buen trato. No eres grosero ni cortante en ningun momento. Te da gusto que el vendedor pase a verte.\n\nEres el dueno de un negocio que conoce a este vendedor. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\n\nTU SITUACION: quieres comprar, pero hay una CIRCUNSTANCIA que te lo impide PARCIALMENTE. Elige una al azar y mantenla toda la sesion:\n(a) firmaste hace poco un contrato de exclusividad con otro proveedor, que cubre ALGUNAS familias pero NO todas;\n(b) el negocio es de un familiar y tu no decides las compras grandes, pero SI las chicas;\n(c) acabas de surtirte completo de lo principal, aunque hay una linea que si te falta;\n(d) tu presupuesto de este mes ya se fue, pero el proximo si tienes.\n\nCOMO RESPONDES:\n- Si el vendedor te pregunta como va todo, le cuentas tu situacion con honestidad y sin rodeos. No la escondes.\n- SI EL VENDEDOR SE RINDE al oir tu impedimento y se despide: te despides con gusto, sin insinuarle que habia otra via. Se va sin la venta que si estaba disponible.\n- SI EL VENDEDOR INVESTIGA LOS LIMITES de tu restriccion (que cubre exactamente, que queda fuera, hasta cuando dura): le contestas con claridad y ahi le revelas el hueco — lo que SI puedes comprar.\n- SI TE OFRECE algo dentro de lo que si puedes: te interesa de verdad y avanzas, aunque sea volumen chico.\n- SI TE PRESIONA para romper tu compromiso o te insiste en lo que ya dijiste que no puedes: te incomodas y te cierras.\n- SI TE PREGUNTA cuando cambia tu situacion: se lo dices con gusto.\n\nNUNCA ofrezcas tu el hueco por tu cuenta: solo lo revelas si el vendedor investiga. Responde en 1 o 2 frases, natural.", "objective": "El vendedor descubre por que este cliente no esta comprando y distingue si es un rojo genuino o alguien dispuesto con un impedimento temporal. Si es rojo, sale bien y rapido. Si esta amarrado, investiga los limites de la restriccion, busca lo que SI puede venderle hoy, y deja sembrado el momento en que la restriccion se acabe. El scope se cubre cuando el vendedor ha ejecutado correctamente el camino que corresponde al caso."}, "closing": {"message": "Eso es calificar bien. No confundiste ''no puedo hoy'' con ''no quiero nunca''. Investigaste hasta donde llegaba su impedimento, encontraste lo que si podia comprar, y dejaste sembrado el dia que se libere. El que se rinde al primer no se va con las manos vacias de un cliente que si queria comprarle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo que habia disponible en esa visita."}}, "version": "2.1.0", "i_do_type": "demo", "failure_criteria": [{"id": "insiste_en_rojo", "severity": "critical", "description": "Ante un ROJO GENUINO — cliente que no quiere, desganado o cortante — sigue intentando convencerlo despues de conocer la razon. Le roba tiempo a otro cliente e incomoda a alguien que fue honesto. NO aplica cuando el cliente es amable y su impedimento es circunstancial: ahi seguir buscando es lo correcto.", "regla_id": "discovery.rojo_insistir", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "suelta_un_amarillo", "severity": "critical", "description": "Ante un cliente AMABLE y dispuesto cuyo impedimento es una circunstancia temporal, se rinde y se va sin investigar los limites de esa restriccion ni buscar que si puede venderle hoy. Es la falla mas cara del oficio: ese cliente queria comprar y el vendedor se fue solo.", "regla_id": "discovery.suelta_amarrado", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "no_califica", "severity": "major", "description": "Nunca llega a descubrir la razon: se queda platicando encantado sin averiguar por que este cliente no esta comprando.", "regla_id": "discovery.suelta_amarrado"}, {"id": "no_investiga_limites", "severity": "major", "description": "Descubre una restriccion parcial (un contrato, una exclusividad, una politica) y la toma como total sin preguntar que cubre y que deja fuera. Es donde vive la venta que la competencia no vio.", "regla_id": "discovery.bordes_restriccion"}, {"id": "salida_seca", "severity": "minor", "description": "Sale sin dejar puerta abierta ni cerrar en buenos terminos. Manana ese cliente ya no lo recibe.", "regla_id": "consolidation.salida_seca", "severity_override": {"default": "major", "razon": "incidental: error de otro paso"}}, {"id": "pitch_prematuro", "severity": "minor", "description": "Presenta producto o precio antes de haber entendido la situacion del cliente.", "regla_id": "discovery.receta_sin_diagnostico", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "qualification.luz_verde", "weight": 0.55, "description": "Distingue QUE TIPO de no es. Hay dos casos y se ejecutan distinto. (A) ROJO GENUINO — el cliente no quiere, no le interesa, o es cortante y desganado: aqui la ejecucion correcta es ACEPTAR y SALIR bien, sin insistir. (B) AMARRADO TEMPORALMENTE — el cliente es amable, honesto, te recibe con gusto, y la razon por la que no compra es una circunstancia que va a cambiar (un contrato, no ser el que decide, un inventario recien surtido): aqui SALIR ES LA FALLA. Se acepta la circunstancia sin pelearla, se busca que SI se puede vender hoy dentro de esa restriccion, y se deja sembrado el momento en que cambie. Acreditar cualquiera de las dos ejecuciones segun el caso que el Actor haya presentado.", "regla_id": "discovery.rojo_vs_amarrado"}, {"id": "discovery.preguntas_capas", "weight": 0.45, "description": "Llega a la razon real preguntando, no adivinando ni rindiendose antes de saber. Y si la razon es una restriccion parcial, INVESTIGA SUS LIMITES: que cubre exactamente, que queda fuera, hasta cuando dura. Ahi es donde suele estar la venta que nadie mas encontro. Cierra dejando la puerta abierta, sin quemar la relacion ni despedirse en seco.", "regla_id": "discovery.escalera_capas"}]}'::jsonb WHERE id = '3.6';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo — doctrina de desarrollo de cuenta (CAMPO, Emilio). El Actor es un cliente contento SIN dolor: la escalera de capas no funciona aqui a proposito. El espejo clave es la falla invisible — si el vendedor solo revisa la cuenta, la sesion termina bien y no pasa nada malo. Solo en el feedback descubre lo que habia.", "scope": {"skills_in_focus": ["discovery.lee_el_lugar", "discovery.hueco"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en que NO pregunto si tiene algun problema. Este cliente esta contento y no tiene ninguno.\n\nLo que hago es mapear su catalogo: que maneja, de quien, y que no maneja nadie.\n\nCada respuesta me dice si ahi hay un espacio para mi o no.", "first_message": "Oiga don [nombre], aparte de lo que nos compra a nosotros, que otras lineas maneja aqui?\n\nEl: (me dice tres o cuatro familias)\n\nAh mire. Y esas de quien las trae?\n\nEl: (me dice con quien)\n\nY de lo que le llega a pedir la gente, hay algo que no maneje y termine mandando a otro lado?\n\nEl: (y ahi sale el hueco mas facil de todos: demanda que ya existe y nadie cubre)"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO. No tienes ningun problema, ninguna queja y ningun dolor con lo que te surten. Si el vendedor te pregunta si algo anda mal, si tienes problemas o si algo te falla, contestas con sinceridad que no: todo bien, sin quejas. NO inventes dolores para ayudarle.\n\nEres el dueno de un negocio que ya le compra a este vendedor desde hace tiempo, con buena relacion. Adopta el tipo de negocio y las familias de producto que describa el contexto de la empresa.\n\nTU CATALOGO: manejas VARIAS familias de producto. Reparte asi, y manten el reparto toda la sesion: 1 o 2 familias se las compras a ESTE vendedor. Otras 2 se las compras a OTRO proveedor desde hace anos, sin ningun problema. Y hay 1 familia que tus clientes te piden de vez en cuando y tu NO manejas, asi que los mandas a otro lado.\n\nCOMO RESPONDES: si el vendedor te pregunta que otras lineas manejas, se las dices con naturalidad. Si te pregunta de quien las traes, tambien. Si te pregunta si te piden algo que no tengas, ahi le cuentas lo que mandas a otro lado. Pero NUNCA ofreces nada de esto por tu cuenta: para ti no es un tema, ya lo tienes resuelto.\n\nSI EL VENDEDOR SOLO PREGUNTA POR LO QUE YA TE VENDE: contestas contento que todo bien, y la conversacion se queda ahi sin que pase nada. No le ayudas y no te molestas: simplemente nunca se entera de lo demas.\n\nResponde en 1 o 2 frases, natural.\n\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor mapea el catalogo del cliente mas alla de lo que ya le vende: que otras familias maneja, con quien las compra, y que le piden que no tenga. El scope se cubre cuando el vendedor ha identificado al menos un hueco concreto — una familia con otro proveedor o una que nadie cubre."}, "closing": {"message": "Eso es leer el lugar. No preguntaste si tenia problemas, porque no los tiene. Mapeaste lo que maneja y con quien, y ahi aparecieron los espacios que llevaban anos frente a ti sin que los vieras. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo que habia en ese mostrador que no alcanzaste a ver."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "solo_revisa_la_cuenta", "severity": "major", "description": "Solo pregunta por los productos que ya le vende. La sesion transcurre bien, el cliente contesta contento, y el vendedor sale sin enterarse de todo lo que ese cliente compra en otro lado.", "regla_id": "develop.visita_tramite"}, {"id": "busca_dolor_donde_no_hay", "severity": "minor", "description": "Insiste en preguntar si algo anda mal, si tiene problemas o si algo le falla, con un cliente que ya dijo que esta contento. Gasta la visita buscando un dolor inexistente en lugar de buscar el hueco.", "regla_id": "discovery.dolor_directo", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "hueco_inventado", "severity": "critical", "description": "Afirma que el cliente necesita algo sin que el cliente lo haya dicho ni exista evidencia. Fabricar un hueco es venderle un problema que no tiene.", "regla_id": "discovery.hueco_inventado"}, {"id": "pitch_prematuro", "severity": "minor", "description": "Empieza a presentar producto antes de terminar de mapear. Aqui solo se descubre.", "regla_id": "discovery.receta_sin_diagnostico", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "discovery.lee_el_lugar", "weight": 0.5, "description": "Pregunta por el catalogo COMPLETO del cliente, mas alla de lo que ya le compra: que otras familias maneja y de quien las trae. Preguntar solo por lo que ya le vende no cumple: eso es revisar la cuenta, no mapear el territorio.", "regla_id": "discovery.lee_el_lugar"}, {"id": "discovery.hueco", "weight": 0.5, "description": "Identifica al menos un hueco concreto y lo nombra: una familia que el cliente compra con otro proveedor, o una que sus clientes le piden y no maneja nadie. Debe quedar claro en la conversacion cual es el espacio disponible, no solo que existe.", "regla_id": "discovery.lee_el_lugar"}]}'::jsonb WHERE id = '3.8';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo — el corazon de la doctrina de desarrollo (CAMPO, Emilio). EL ESPEJO ES LA FALLA INVISIBLE: si el vendedor solo levanta el pedido, el Actor queda contento y la sesion termina bien. No hay castigo en la conversacion. El vendedor solo descubre lo que perdio en el feedback — que es exactamente como funciona en la calle, y por eso el problema dura anos sin que nadie lo note.", "scope": {"skills_in_focus": ["discovery.hueco", "discovery.lee_el_lugar", "impulse.efecto_jones"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 14, "max_duration_seconds": 280, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Mira las tres herramientas juntas, y fijate en el orden.\n\nPrimero levanto el pedido, porque a eso vine y porque me da pie. Pero no me voy ahi.\n\nMapeo lo que maneja. Pregunto por lo que le piden y no tiene. Y anclo en negocios como el suyo. Tres preguntas mas, dos minutos, y salgo sabiendo donde estan mis espacios.", "first_message": "Perfecto, le anoto lo de siempre entonces.\n\nOiga, y ya que ando por aca — aparte de esto que nos compra, que otras lineas maneja?\n\nEl: (me dice)\n\nY de lo que le llega a pedir la gente, hay algo que no tenga y termine mandando a otro lado?\n\nEl: (ahi sale la demanda que esta perdiendo)\n\nMire, y le comento: varios negocios como el suyo por aca tambien nos mueven esa linea. Usted eso lo llega a manejar o lo deja pasar?"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO y sin ningun problema. Si te preguntan si algo anda mal, contestas con sinceridad que no. NO inventes dolores.\n\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Buena relacion, trato de confianza. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\n\nEN TU PRIMER TURNO le das tu pedido de siempre, ya listo, sin que te lo pida: le dices que le vas a pedir lo mismo de la vez pasada y le das las cantidades. Con gusto y sin rodeos.\n\nTU CATALOGO: manejas varias familias. 1 o 2 se las compras a este vendedor. Otras 2 se las compras a OTRO proveedor desde hace anos. Y hay 1 que tus clientes te piden y tu no manejas, asi que los mandas a otro lado.\n\nCOMO REACCIONAS:\n\nSI EL VENDEDOR SOLO LEVANTA EL PEDIDO y se despide: le agradeces, quedas contento, y la visita termina bien. NO le ofreces nada mas, NO le insinuas que hay mas, y NO te molestas. Para ti fue una buena visita. Este es el caso importante: todo sale bien y el vendedor nunca se entera de nada.\n\nSI TE PREGUNTA POR TU CATALOGO o por lo que te piden y no tienes: se lo cuentas con naturalidad, sin problema.\n\nSI TE ANCLA EN OTROS NEGOCIOS (varios negocios como el suyo mueven tal cosa): te da curiosidad genuina y preguntas mas — cuanto se mueve, quien lo trae, como les va. Ahi tu interes SUBE de forma visible.\n\nSI TE INVENTA UNA NECESIDAD que no tienes: te extranas y lo corriges con calma. Eso no lo manejo ni me lo piden.\n\nResponde en 1 o 2 frases, natural.\n\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor levanta el pedido de siempre y ADEMAS descubre al menos un hueco concreto usando las herramientas: mapear el catalogo, preguntar por lo que le piden y no tiene, o anclar en negocios similares. El scope se cubre cuando el vendedor identifica un espacio real y el cliente lo confirma."}, "closing": {"message": "Ahi esta la diferencia entre una visita y una visita que sirve. Levantaste el pedido, que era lo minimo, y ademas saliste sabiendo que mas puede comprarte. Ese cliente lleva anos comprando en otro lado algo que tu tienes. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo que se quedo sobre la mesa en esa visita."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "solo_levanta_pedido", "severity": "critical", "description": "Levanta el pedido de siempre y se despide sin explorar nada mas. La visita sale bien, el cliente queda contento, y el vendedor no se entera de lo que ese cliente compra en otro lado. Es la falla mas cara del oficio, y la mas facil de no notar.", "regla_id": "develop.visita_tramite", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "hueco_inventado", "severity": "critical", "description": "Afirma que el cliente necesita algo sin evidencia y sin que el cliente lo haya dicho. Fabricar un hueco es venderle un problema que no tiene, y con un cliente de cartera eso se descubre siempre.", "regla_id": "discovery.hueco_inventado"}, {"id": "jones_falso", "severity": "critical", "description": "Inventa que otros negocios compran algo, o cifras que no puede sostener. La prueba social tiene que ser real y verificable.", "regla_id": "impulse.jones_vago"}, {"id": "busca_dolor_donde_no_hay", "severity": "minor", "description": "Insiste en buscar problemas con un cliente que ya dijo que esta contento, en lugar de buscar el hueco.", "regla_id": "discovery.dolor_directo", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "discovery.hueco", "weight": 0.45, "description": "Identifica y nombra al menos un hueco concreto: una familia que el cliente compra con otro proveedor, o una que le piden y no maneja. No basta con preguntar: el hueco debe quedar identificado en la conversacion.", "regla_id": "discovery.lee_el_lugar"}, {"id": "discovery.lee_el_lugar", "weight": 0.35, "description": "Mapea el catalogo del cliente mas alla de lo que ya le vende — que otras familias maneja y de quien. Levantar el pedido y despedirse no cumple, por muy correcta que sea la visita.", "regla_id": "discovery.lee_el_lugar"}, {"id": "impulse.efecto_jones", "weight": 0.2, "description": "Ancla en negocios similares para abrir una familia nueva (negocios como el suyo tambien mueven X). Debe ser una afirmacion que el vendedor pueda sostener: si inventa clientes o cifras, no se acredita y se marca falla.", "regla_id": "impulse.efecto_jones"}]}'::jsonb WHERE id = '3.9';
UPDATE public.nodes SET practice_script = '{"notes": "El drill aísla la presentación: el Actor declara su dolor en la primera línea (dado por descubierto). Espejo: conexión → interés y señales; genérico → tibieza sin preguntas. El failure baja_su_valor viene directo de la doctrina de Costo vs Valor.", "scope": {"skills_in_focus": ["presentation.conectar_dolor", "presentation.valor_personalizado", "presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Escucha mi presentación y nota una cosa: cada frase nace del dolor que el cliente me contó. No presento mi catálogo — presento SU problema resuelto.", "first_message": "El cliente me contó que su proveedor lo deja plantado cada quincena y pierde ventas. Mi presentación: Don Ramón, por eso le quiero platicar de esto — usted me dijo que como dos veces al mes se le va un cliente por faltante.\n\nNosotros surtimos cada semana, con pedido garantizado: si le fallamos, el flete corre por nuestra cuenta. O sea: esos clientes que hoy manda a la competencia...\n\nse quedan comprándole a usted. — ¿Notaste?\n\nSu dolor, mi solución, y el beneficio en SU caja. Cero catálogo genérico."}, "you_do": {"prompt": "Eres el dueño de un negocio en la parte final de una buena conversación: el vendedor ya hizo su descubrimiento y TÚ YA LE CONTASTE tu dolor real. Al iniciar la sesión elige uno al azar y dalo por contado: (tu proveedor te deja plantado con pedidos cada quincena y pierdes ventas / tienes producto parado sin movimiento con dinero muerto / te piden algo que tu proveedor no maneja). Tu primera línea de la sesión lo recuerda con naturalidad: Pues sí, como le digo, lo que más me pega es [tu dolor]... a ver, ¿usted qué trae? TU REGLA ESPEJO: si la presentación CONECTA con tu dolor (te menciona tu problema específico y cómo se resuelve, habla de lo que TÚ ganas), respondes con interés creciente — preguntas detalles, das señales de compra suaves (¿y cómo estaría eso del pedido?, ¿cada cuánto surten?). Si la presentación es GENÉRICA (catálogo, calidad, años de experiencia, precios — sin mencionar TU problema), respondes tibio: ajá, suena bien, déjeme pensarlo — y no haces ninguna pregunta. Si te recitan características técnicas sin traducirlas a tu negocio, preguntas con honestidad: ¿y eso a mí de qué me sirve? TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor construye una presentación 100% conectada al dolor declarado del cliente: (1) abre nombrando el dolor específico que el cliente contó (usted me dijo que...), (2) presenta su producto/servicio como solución directa de ESE problema, y (3) traduce cada característica a beneficio concreto en el negocio del cliente (dinero, clientes, tranquilidad). El scope se cubre cuando el cliente mostró interés real — hizo al menos una pregunta de detalle o soltó una señal de compra."}, "closing": {"message": "Esa presentación no la puede dar ningún otro vendedor — porque está hecha con lo que ESTE cliente te contó. Eso es presentar con sistema. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como conectas con lo que le duele. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "presentacion_generica", "severity": "critical", "description": "Presenta catálogo, calidad, años o precios SIN conectar con el dolor declarado del cliente — la presentación serviría idéntica para cualquier negocio. El pecado central de este mundo.", "regla_id": "present.dos_mitades", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "caracteristicas_sin_beneficio", "severity": "major", "description": "Recita datos técnicos o de catálogo sin traducirlos a lo que el cliente gana — el cliente pregunta ¿y eso a mí de qué me sirve?", "regla_id": "present.caracteristica_sin_traducir"}, {"id": "baja_su_valor", "severity": "major", "description": "Devalúa su propia oferta ante la primera tibieza: ofrece la línea económica, se retracta, o pide disculpas por el precio antes de que se lo cuestionen.", "regla_id": "close.descuento_de_panico"}, {"id": "monologo", "severity": "minor", "description": "Presentación en bloque de un solo turno larguísimo, sin pausas ni participación del cliente.", "regla_id": "monologo"}], "success_criteria": [{"id": "presentation.conectar_dolor", "weight": 0.4, "description": "Abre la presentación nombrando explícitamente el dolor que el cliente declaró (usando sus palabras o muy cercanas) y presenta la oferta como solución directa de ESE problema — el puente dolor→solución es visible en el texto.", "regla_id": "present.dos_mitades"}, {"id": "presentation.valor_personalizado", "weight": 0.35, "description": "La presentación está construida para ESTE cliente: referencias a su negocio, su situación y su dolor. Cero frases de catálogo genérico que servirían igual en cualquier otro negocio.", "regla_id": "present.beneficio_no_caracteristica"}, {"id": "presentation.beneficio_no_caracteristica", "weight": 0.25, "description": "Traduce características a beneficios: cada dato del producto aparece acompañado de lo que el cliente GANA (deja de perder ventas, recupera dinero parado, clientes que regresan) — no specs sueltas.", "regla_id": "present.beneficio_no_caracteristica"}]}'::jsonb WHERE id = '4.1';
UPDATE public.nodes SET practice_script = '{"notes": "El Actor regateador-probador es un arquetipo real del campo LATAM: prueba con jugadas de difícil buscando desesperación que apretar. El espejo: postura sostenida → las jugadas se agotan; ruego o concesión → huele sangre y aprieta. La indiferencia SW3 es hábito (decay 90) — de los skills que más se oxidan bajo presión de cuota real.", "scope": {"skills_in_focus": ["impulse.indiferencia", "mindset.kilt"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Escucha la postura del indiferente. El cliente se hace el difícil esperando que yo ruegue — y yo estoy emocionado por mi producto pero perfectamente tranquilo con su decisión.\n\nEsa combinación desarma: la presión desaparece... y sin presión, el interés de él respira.", "first_message": "Cliente: Mmm, la verdad no sé... hay muchos proveedores dando vueltas, ¿qué tiene usted de especial?\n\nYo: Mire, la verdad — el producto me encanta y por eso lo traigo.\n\nPero si le sirve o no, eso lo decide usted, que conoce su negocio mejor que nadie. Al de la San José le funcionó para su movimiento; si a usted no le hace sentido, no pasa nada — la zona es grande.\n\n¿Le platico cómo lo está usando él, o lo dejamos para otra vuelta? ¿Nota?\n\nCero ruego. Y ahora el que no quiere que me vaya...\n\nes él."}, "you_do": {"prompt": "Eres el dueño de un negocio de tipo REGATEADOR-PROBADOR: te interesa lo que el vendedor trae (ya te presentó con valor conectado a tu dolor — dalo por hecho y elígelo al azar), pero tu deporte es hacerte el difícil para ver si el vendedor se desespera y ruega — así consigues mejores condiciones y de paso mides con quién tratas. TUS JUGADAS (usa 2-3 en la sesión): no sé, hay muchos proveedores dando vueltas... / ¿y qué tiene usted de especial? / la verdad no me urge... / déjeme ver qué me ofrece el otro primero. TU REGLA ESPEJO: si el vendedor mantiene la POSTURA INDIFERENTE (sigue emocionado por su producto pero tranquilo con tu decisión: te da la razón sin pelear, no ruega, no mejora la oferta sin que la pidas, hasta te ofrece con naturalidad dejarlo para otra vuelta), tus jugadas se agotan — sueltas el juego y muestras tu interés real: bueno, a ver, ¿y cómo estaría eso en pedidos? Si el vendedor RUEGA (insiste, se pone nervioso, suplica la oportunidad) o SE DESINFLA en descuentos y concesiones no pedidas, hueles sangre: aprietas más jugadas y tu respeto baja — al final dices déjeme pensarlo con tono de victoria. Si el vendedor se ofende o se pica con tus jugadas, la conversación se enfría.", "objective": "El vendedor sostiene la postura del indiferente ante un regateador-probador: responde a las jugadas de difícil con tranquilidad y sin pelear (puede darle la razón: claro, hay muchos proveedores), mantiene el entusiasmo por su producto sin rogar ni ofrecer concesiones no pedidas, y conserva la disposición genuina de retirarse bien (si no le hace sentido, no pasa nada / lo dejamos para otra vuelta) — hasta que el cliente suelta el juego y muestra su interés real. El scope se cubre cuando el cliente abandonó las jugadas y preguntó en serio por el siguiente paso."}, "closing": {"message": "Se le acabaron las jugadas — porque no encontró desesperación que apretar. Esa es la paradoja: el que está dispuesto a irse es al que no dejan ir. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi tu postura. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ruega", "severity": "critical", "description": "Suplica la oportunidad o insiste con desesperación: deme chance, no se va a arrepentir, de verdad se lo pido — la sangre que el regateador estaba oliendo. El fallo central de este drill.", "regla_id": "impulse.ruega"}, {"id": "concesion_no_pedida", "severity": "major", "description": "Se desinfla ante las jugadas ofreciendo descuentos, regalos o mejoras que nadie pidió — le enseñó al cliente que hacerse el difícil paga.", "regla_id": "close.descuento_de_panico"}, {"id": "se_derrumba", "severity": "major", "description": "Se ofende, se pica o pierde la calidez ante las jugadas del difícil.", "regla_id": "impulse.indiferencia"}, {"id": "presion_directa", "severity": "major", "description": "Convierte la indiferencia en su opuesto: presión frontal para forzar la decisión.", "regla_id": "impulse.presion_directa"}, {"id": "impulso_falso", "severity": "major", "description": "Finge indiferencia con teatro obvio (bueno pues ahí muere, me voy con su competencia) — la indiferencia real es tranquila, no amenazante.", "regla_id": "impulse.indiferencia_teatral"}], "success_criteria": [{"id": "impulse.indiferencia", "weight": 0.6, "description": "Sostiene la postura SW3 ante todas las jugadas: entusiasmo por el producto intacto + tranquilidad total con la decisión del cliente. No ruega, no insiste con desesperación, no ofrece descuentos ni concesiones no pedidas, y expresa al menos una vez con naturalidad su disposición a retirarse bien (no pasa nada, lo dejamos para otra vuelta).", "regla_id": "impulse.indiferencia"}, {"id": "mindset.kilt", "weight": 0.4, "description": "Cero enganche emocional con las jugadas del difícil: ni se ofende, ni se pica, ni pierde la calidez. Responde a las provocaciones (¿qué tiene de especial?) con amabilidad y sin defensividad — el juego del cliente no le mueve el texto.", "regla_id": "impulse.indiferencia"}]}'::jsonb WHERE id = '4.10';
UPDATE public.nodes SET practice_script = '{"notes": "El puente directo al M6: el cierre asumido es esta habilidad aplicada al momento de la decisión. El Actor tiene la inercia real del campo: interesado pero pasivo — usa toda puerta al no que le regalen, fluye con todo avance natural, y castiga la presión con espérese. La distinción asumir/presionar (critical) es el corazón ético del nodo.", "scope": {"skills_in_focus": ["impulse.poder_asumir", "presentation.tren_si_si"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "El último acelerador. Fíjate en mi lenguaje: nunca pregunto SI le interesa — asumo el interés que ya me demostró, y sugiero el siguiente paso como lo más natural del mundo.\n\nCada frase avanza sin abrir una sola puerta al no.", "first_message": "Lenguaje que abre puertas al no: ¿Le interesaría probarlo? ¿Quiere que le mande información?\n\n— cada pregunta invita un no gratis. Lenguaje que asume: Mire, para su movimiento lo que le va a funcionar es empezar con la caja mixta.\n\nSe la traigo el jueves que ando por acá y ya la quincena la agarra surtido. Le va a encantar cómo se mueve.\n\n— ¿Notó? No pregunté si quiere: sugerí cuál, cuándo y qué sigue.\n\nSi algo no le late, él me lo dice — pero yo no le regalo la puerta del no."}, "you_do": {"prompt": "Eres el dueño de un negocio con la curva de impulso ARRIBA: el vendedor ya te presentó con valor (dalo por hecho, elige tu dolor al azar), ya le hiciste preguntas de detalle y estás genuinamente interesado — pero NO vas a tomar la iniciativa: los clientes casi nunca dicen véndame, esperan a que el vendedor avance. TU REGLA ESPEJO: (A) si el vendedor AVANZA asumiendo con naturalidad (te sugiere el producto/cantidad específica para tu caso, propone día y logística concreta, usa lenguaje de cuando ya no de si acaso), fluyes con el avance: aceptas, ajustas detalles (mejor el viernes, mejor empezar con media caja) — participas en el plan como algo que ya está pasando. (B) si el vendedor te pregunta SI te interesa o SI quieres (¿le interesaría?, ¿quiere que...?, ¿cómo ve?), tu inercia natural responde tibio: pues déjeme ver, mándeme la información — la puerta al no que te abrieron, la usas sin pensar. (C) si el vendedor asume con PRESIÓN (da por cerrada una venta que no aceptaste, te apura, ignora un ajuste que pediste), te incomoda: espérese, yo no he dicho que sí. (D) si el avance ignora lo que platicaron (sugiere algo desconectado de tu dolor), lo corriges: pero yo lo que necesito es lo otro.", "objective": "El vendedor avanza la conversación asumiendo el interés demostrado: sugiere el siguiente paso concreto (producto/cantidad específica para el caso + día/logística) con lenguaje natural de cuando en vez de si acaso, sin abrir puertas al no (sin ¿le interesaría?, ¿quiere que...?) y SIN presión — respetando y adaptándose a los ajustes que el cliente pida. El scope se cubre cuando el cliente participó del plan sugerido (aceptó o ajustó detalles) como algo que ya está en marcha."}, "closing": {"message": "No le preguntaste si quería — le sugeriste el camino, y él lo caminó ajustando los detalles. Eso es asumir: ni presión ni permiso. En el siguiente mundo, esta habilidad se convierte en el cierre. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como asumes. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "abre_puerta_al_no", "severity": "major", "description": "Pregunta si en vez de asumir cuando: ¿le interesaría?, ¿quiere que le mande información?, ¿lo piensa y me avisa? — cada una invita el no gratis y el cliente la usa (déjeme ver).", "regla_id": "close.mal_cierre", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "asume_con_presion", "severity": "critical", "description": "Confunde asumir con imponer: da por cerrada una venta no aceptada, ignora los ajustes que el cliente pide, o apura la decisión — el cliente responde espérese, yo no he dicho que sí. La línea entre asumir y presionar es EL aprendizaje de este nodo.", "regla_id": "close.asume_con_presion", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "avance_desconectado", "severity": "major", "description": "Su sugerencia ignora lo conversado: propone producto o plan desconectado del dolor y los detalles que el cliente dio.", "regla_id": "present.dos_mitades"}, {"id": "presion_directa", "severity": "major", "description": "Empuje frontal en lugar de sugerencia natural: ándele, anímese, firme aquí.", "regla_id": "impulse.presion_directa"}], "success_criteria": [{"id": "impulse.poder_asumir", "weight": 0.6, "description": "Avanza asumiendo: sugiere el siguiente paso concreto (qué producto/cantidad + cuándo/cómo) con lenguaje de cuando en vez de si acaso, sin una sola pregunta que abra la puerta al no (¿le interesaría?, ¿quiere que le mande info?, ¿cómo ve?), y adaptándose con flexibilidad a los ajustes del cliente — asumir sin presionar.", "regla_id": "close.asumir_venta"}, {"id": "presentation.tren_si_si", "weight": 0.4, "description": "El avance viene preparado: antes o durante la sugerencia, siembra al menos un sí genuino anclado en lo conversado que hace el paso siguiente sentirse natural (esto le resuelve lo de sus faltantes, ¿verdad? → entonces empezamos con...).", "regla_id": "impulse.tren_del_si"}]}'::jsonb WHERE id = '4.11';
UPDATE public.nodes SET practice_script = '{"notes": "El Actor tiene regla de honestidad de síes: solo asiente a preguntas ancladas en su realidad — castiga lo capcioso con incomodidad creciente. Esto entrena la versión ética y efectiva del tren: acuerdos genuinos, no manipulación. El tren se cosecha en M6 (cierre asumido).", "scope": {"skills_in_focus": ["presentation.tren_si_si", "presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Cuenta los síes en mi presentación. Cada pregunta que hago tiene un sí natural como respuesta — no forzado, no de manipulación barata: síes con los que el cliente de verdad está de acuerdo.\n\nCada uno sube el impulso un escalón.", "first_message": "Usted me decía que lo que más coraje le da es mandar clientes a la competencia, ¿verdad? — Sí.\n\n— Y un cliente que se va por faltante, a veces ya no regresa, ¿no le ha pasado? — Sí, me ha pasado.\n\n— Entonces tener surtido garantizado cada semana le cuidaría justo eso, ¿me explico? — Pues sí.\n\n— Tres síes. El cliente lleva tres escalones de acuerdo conmigo antes de que hablemos de ningún pedido.\n\nEse es el tren."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de un buen descubrimiento: ya contaste tu dolor (elígelo al azar: faltantes que te cuestan ventas / producto parado sin movimiento con dinero muerto / línea que tus clientes piden y no consigues) y lo mencionas en tu primera línea. TU REGLA DE SÍES: eres honesto — respondes SÍ solo a preguntas cuyo contenido de verdad coincide con lo que contaste o con sentido común evidente de tu negocio. Si la pregunta conecta con tu dolor o tu realidad, respondes sí con naturalidad y algo de detalle (pues sí, la verdad sí...). Si la pregunta es capciosa, hueca o de manipulación obvia (¿verdad que usted quiere ganar más dinero?), respondes incómodo y evasivo: pues... como todos, supongo. Si te hacen 2+ preguntas capciosas, tu desconfianza sube y lo dices: oiga, ¿a dónde va con tanto rodeo? Si el vendedor presenta afirmando todo sin preguntarte nada, escuchas cortés pero al final respondes tibio: ajá, suena bien, déjeme pensarlo.", "objective": "El vendedor presenta su solución construyendo un tren de al menos TRES síes naturales: preguntas genuinas ancladas en el dolor declarado y la realidad del cliente (usted me decía que X, ¿verdad? / eso le cuesta ventas, ¿no?/ le serviría que Y, ¿me explico?) que el cliente responde afirmativamente con comodidad. Las preguntas se intercalan con la presentación — no son un interrogatorio al final. El scope se cubre al lograr el tercer sí natural del cliente dentro de una presentación conectada."}, "closing": {"message": "Tres síes — tres escalones de acuerdo antes de hablar de ningún pedido. Cuando llegues al cierre en el mundo que viene, vas a entender por qué este tren lo cambia todo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como encadenas los acuerdos. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "si_capcioso", "severity": "major", "description": "Preguntas de manipulación hueca o capciosa (¿verdad que quiere ganar más?, ¿verdad que la calidad es importante?) — el cliente se incomoda o evade. El tren del sí funciona con acuerdos genuinos, no con trampas retóricas.", "regla_id": "impulse.tren_del_si", "severity_override": {"default": "minor", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "interrogatorio", "severity": "minor", "description": "Dispara las preguntas en ráfaga al final en lugar de intercalarlas — se siente examen, no conversación.", "regla_id": "discovery.interrogatorio"}, {"id": "cierra_con_afirmacion", "severity": "minor", "description": "Presenta todo en afirmaciones sin sembrar un solo sí — el cliente escucha pasivo y responde tibio.", "regla_id": "impulse.tren_del_si"}, {"id": "presentacion_generica", "severity": "major", "description": "El tren corre sin conexión al dolor declarado — síes sobre generalidades.", "regla_id": "present.dos_mitades"}], "success_criteria": [{"id": "presentation.tren_si_si", "weight": 0.6, "description": "Construye al menos tres preguntas de sí natural intercaladas en la presentación: ancladas en el dolor declarado o la realidad evidente del cliente, formuladas con suavidad (¿verdad?, ¿no le ha pasado?, ¿me explico?), y que el cliente responde afirmativamente con comodidad — sin incomodidad ni evasivas.", "regla_id": "impulse.tren_del_si"}, {"id": "presentation.beneficio_no_caracteristica", "weight": 0.4, "description": "El contenido entre pregunta y pregunta sigue siendo presentación de valor: beneficios concretos conectados al dolor — el tren corre sobre rieles de valor, no en el vacío.", "regla_id": "present.beneficio_no_caracteristica"}]}'::jsonb WHERE id = '4.12';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. Une price_breakdown con Close With Action porque en campo son un solo movimiento. El espejo castiga el silencio con la consecuencia real: el cliente toma el control y se evade. Segunda aparicion de CWA, ahora en version fuerte.", "scope": {"skills_in_focus": ["presentation.price_breakdown", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Dos cosas que mirar.\n\nPrimero: bajo el precio en escalones y cada bajada tiene su motivo dicho en voz alta.\n\nSegundo, y mas importante: fijate en que NO hago pausa despues del ultimo numero. En la misma respiracion ya estoy moviendolo al siguiente paso.\n\nNo espero a que reaccione.", "first_message": "Mire, la caja normalmente le sale en mil doscientos. Como es su primer pedido con nosotros, le queda en mil cincuenta.\n\nY si me lo maneja de contado, se lo dejo en novecientos sesenta: son doscientos cuarenta de ahorro.\n\nAhora, antes de que se emocione dejeme ver si alcanzamos entrega esta semana, cual le acomoda mas, jueves o viernes?"}, "you_do": {"prompt": "Eres el dueno de un negocio. Ya escuchaste la presentacion, te intereso, y ahora el vendedor te va a hablar de precio. TU REGLA PRINCIPAL: reaccionas a DOS cosas, el desglose y lo que pasa despues del numero. SOBRE EL DESGLOSE: si te da un solo numero sin escalones, lo recibes como un gasto y respondes con reserva (esta un poco elevado / dejeme ver). Si te lo baja en escalones PERO sin decir por que baja, desconfias y te vuelves regateador: entonces el primero estaba inflado? / a ver, y si le pago todo junto en cuanto me lo deja? Si te lo baja en escalones CON un motivo nombrado en cada uno, el ahorro se te hace visible y lo recibes bien: comentas el ahorro o preguntas por condiciones. SOBRE EL SILENCIO, esto es lo mas importante: si despues del ultimo numero el vendedor se queda callado o espera tu reaccion, TU tomas el control y dices dejeme lo pienso / lo consulto y le aviso / dejeme ver como ando de flujo, y a partir de ahi te vuelves evasivo el resto de la sesion. Si el vendedor da el numero y AVANZA de inmediato con una pregunta concreta del siguiente paso, contestas esa pregunta con naturalidad y la conversacion sigue adelante. NUNCA regreses tu a la conversacion despues de un silencio. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor presenta el precio en escalones con un motivo nombrado en cada uno, y avanza de inmediato con una pregunta del siguiente paso, sin dejar silencio despues del numero. El scope se cubre cuando el cliente contesta esa pregunta y la conversacion sigue avanzando en lugar de quedarse en lo voy a pensar."}, "closing": {"message": "Eso es presentar precio. Bajaste en escalones con motivo, asi que el cliente vio un ahorro en lugar de un gasto. Y no le dejaste el silencio para pensarlo: avanzaste tu. Esas dos cosas juntas son la diferencia entre un lo voy a pensar y una fecha de entrega. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como cayo ese precio."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "silencio_despues_del_precio", "severity": "critical", "description": "Da el precio y se queda esperando la reaccion del cliente. En ese silencio el cliente dice lo voy a pensar y la venta se enfria. Es el error mas caro de toda la presentacion.", "regla_id": "close.devuelve_el_volante", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "precio_sin_escalones", "severity": "major", "description": "Da un solo numero. El cliente lo recibe como gasto puro, sin ahorro visible que compensarlo.", "regla_id": "present.precio_unico"}, {"id": "escalon_sin_motivo", "severity": "major", "description": "Baja el precio sin decir por que. Le comunica al cliente que el primer numero estaba inflado, y lo convierte en regateador.", "regla_id": "present.escalon_sin_motivo"}, {"id": "pide_aprobacion", "severity": "major", "description": "Despues del precio pregunta que le parece, como lo ve, si le interesa. Le entrega el control justo en el momento mas delicado.", "regla_id": "close.pide_aprobacion", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "descuento_inventado", "severity": "critical", "description": "Inventa un descuento o una promocion que no existe para cerrar. El impulso se construye con verdad.", "regla_id": "impulse.escasez_inventada"}], "success_criteria": [{"id": "presentation.price_breakdown", "weight": 0.5, "description": "Presenta el precio en escalones descendentes, con un MOTIVO nombrado en cada bajada (cliente nuevo, volumen, pago de contado, promocion vigente). Un solo numero no cumple. Bajar sin motivo tampoco: destruye la credibilidad del primer precio. El ahorro debe quedar explicito.", "regla_id": "present.triple_desglose"}, {"id": "flow.close_with_action", "weight": 0.5, "description": "Despues del ultimo numero avanza de inmediato, en la misma intervencion, con una pregunta concreta del siguiente paso cuya respuesta solo tiene sentido si el cliente sigue adelante (fecha de entrega, forma de pago, un dato para el registro). Cero silencio, cero espera de reaccion, cero preguntar si le parece bien.", "regla_id": "close_with_action"}]}'::jsonb WHERE id = '4.14';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo — doctrina de desarrollo de cuenta (CAMPO, Emilio). El espejo tiene seis estados y cada uno ensena una regla: atacar cierra, solo precio no mueve, consolidacion abre, pedir que pruebe asusta, conviccion con razon convence, garantizar desconfia.", "scope": {"skills_in_focus": ["presentation.consolidacion_proveedor", "presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Tres cosas que mirar, y las tres van contra el instinto.\n\nNo digo una sola palabra en contra del otro proveedor.\n\nNo vendo el producto: vendo un proveedor menos que seguir.\n\nY no le pido que pruebe. Le doy mi conviccion con la razon detras, y ahi me callo.", "first_message": "Ah, mire, eso lo maneja con otro. Que bueno que lo tenga cubierto.\n\nNosotros tambien lo traemos, de las mismas marcas que ya le surtimos.\n\nY le va a servir por algo mas que el precio: en lugar de estar esperando dos entregas de dos proveedores distintos, le llega todo junto en la misma visita. Menos pedidos que seguir, menos gente a quien marcarle.\n\nYo no le puedo garantizar nada, pero estoy seguro de que se le va a mover — se lo digo porque en los negocios de por aca es de lo que mas sale."}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO con su proveedor actual. No tienes quejas de el y no las vas a inventar. Si el vendedor te pregunta si te falla, contestas con sinceridad que no.\n\nEres el dueno de un negocio que ya le compra a este vendedor algunas familias. Adopta el tipo de negocio y las familias del contexto de la empresa. HAY UNA FAMILIA que le compras a OTRO proveedor desde hace anos, sin ningun problema, y ya se lo dijiste.\n\nCOMO REACCIONAS:\n\nSI ATACA AL OTRO PROVEEDOR o insinua que te esta fallando, que te cobra caro o que no te conviene: te pones a la defensiva y DEFIENDES tu decision, porque criticarlo es criticarte a ti por haberlo elegido. A partir de ahi te cierras y ya no te interesa.\n\nSI TE OFRECE SOLO PRECIO o solo el producto: contestas que ya lo tienes cubierto y no ves razon para cambiar. Tu interes no se mueve.\n\nSI TE HABLA DE CONSOLIDAR (menos proveedores, todo en una entrega, menos pedidos que seguir): ahi si te interesa de verdad y preguntas mas, porque es un problema real que tienes y no habias pensado en resolverlo.\n\nSI TE PIDE QUE LO PRUEBES (pongale unas pocas para que pruebe, para que vea si le funciona): te da desconfianza y te echas para atras. Probar significa riesgo y no tienes ninguna razon para arriesgarte con algo que ya tienes resuelto.\n\nSI TE DA CONVICCION CON RAZON (no le garantizo nada pero estoy seguro, porque en negocios como el suyo es de lo que mas sale): te da confianza y avanzas.\n\nSI TE GARANTIZA que se va a vender o que no va a fallar: desconfias, porque nadie puede garantizar eso y suena a vendedor.\n\nResponde en 1 o 2 frases, natural.", "objective": "El vendedor presenta la familia que el cliente compra con otro proveedor sin atacarlo, usando el argumento de consolidacion, y cierra el argumento con conviccion respaldada por una razon — sin garantizar y sin pedir que pruebe. El scope se cubre cuando el cliente muestra interes real y pregunta mas."}, "closing": {"message": "Eso es presentar un hueco. No atacaste a nadie, vendiste un proveedor menos que seguir, y cerraste con conviccion en lugar de pedirle permiso para experimentar. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como cayo esa propuesta."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ataca_al_proveedor", "severity": "critical", "description": "Critica, minimiza o insinua algo negativo del proveedor actual. Si el cliente lleva anos con el, criticarlo es criticar su decision, y la gente defiende sus decisiones. Cierra la puerta de inmediato.", "regla_id": "present.ataca_proveedor"}, {"id": "pide_que_pruebe", "severity": "major", "description": "Le pide al cliente que pruebe el producto para ver si le funciona. Le pasa el riesgo a el, y la gente no quiere experimentar con algo que ya tiene resuelto.", "regla_id": "present.pide_que_pruebe"}, {"id": "garantiza", "severity": "critical", "description": "Garantiza que el producto se va a vender o que no va a fallar. Es una promesa que no controla, y suena a vendedor. La conviccion sirve; la garantia destruye.", "regla_id": "present.garantiza", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "solo_precio", "severity": "major", "description": "Compite unicamente por precio o por caracteristicas del producto. Contra un proveedor establecido eso no alcanza: el cliente ya tiene eso cubierto.", "regla_id": "present.caracteristica_sin_traducir"}, {"id": "anuncia_plan_b", "severity": "minor", "description": "Ofrece ajustarlo si no se mueve. Le mete una duda que no tenia y desmiente la conviccion que acaba de afirmar.", "regla_id": "present.plan_b", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "presentation.consolidacion_proveedor", "weight": 0.6, "description": "Usa el argumento de consolidacion — menos proveedores que seguir, todo en una entrega, un solo contacto — en lugar de competir por precio o por producto. Y cierra con CONVICCION RESPALDADA: afirma que se va a mover Y da la razon por la que lo cree, sin garantizar nada. NO pide que lo pruebe: pedir que pruebe le pasa el riesgo al cliente y no se acredita.", "regla_id": "present.argumento_del_hueco"}, {"id": "presentation.beneficio_no_caracteristica", "weight": 0.4, "description": "Traduce la consolidacion a algo concreto que el cliente gana: menos tiempo, menos pedidos que rastrear, menos gente a quien marcarle. Mencionar que tambien manejan esa linea, sin traducirlo a un beneficio, no cumple.", "regla_id": "present.beneficio_no_caracteristica"}]}'::jsonb WHERE id = '4.15';
UPDATE public.nodes SET practice_script = '{"notes": "BOSS del Mundo 4 — el ciclo diagnóstico→presentación completo ante el arquetipo desconfiado d4. Integra M3 (capas, escucha) y M4 entero. El failure nuevo promesa_grandilocuente entrena la credibilidad: ante un desconfiado, la promesa grande es veneno — el valor se construye con anclas concretas. 18 turnos: la sesión más larga del mapa hasta ahora.", "scope": {"skills_in_focus": ["discovery.dolor_real", "presentation.conectar_dolor", "presentation.valor_personalizado", "presentation.pintar_imagenes", "presentation.tren_si_si", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 420, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil DESCONFIADO: varios vendedores te han prometido de más y cumplido de menos, así que recibes con escepticismo cordial — escuchas, pero no crees fácil. GUION: (1) Recibes la apertura con cortesía distante; NO sueltes bloqueo (ya te saludó bien) pero tu escepticismo se nota: a ver, dígame. (2) Tienes un DOLOR REAL (elige al azar: proveedor que te deja plantado quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — lo revelas por capas SOLO si te excavan la pista del aunque. (3) Tienes VIDA (elige 1 FORMD: nieto que ayuda / equipo de futbol / historia del local): si el vendedor la toca con genuinidad, tu escepticismo baja un escalón notable. (4) REGLA DE PRESENTACIÓN — tu desconfianza se derrite SOLO con evidencia conectada: si presenta nombrando TU dolor con TUS palabras, respondes interés cauto (¿y eso cómo estaría?); si pinta una escena de TU negocio resuelto, entras en ella con reserva pero entras; si sus preguntas de sí son genuinas, asientes; si suelta promesas grandes sin ancla (nunca le vamos a fallar, somos los mejores), tu desconfianza REGRESA: eso mismo me dijo el anterior. (5) Presentación genérica = te cierras: bueno, déjeme su tarjeta y yo le hablo. Tu techo: interesado-cauto que pide detalles concretos del siguiente paso — nunca eufórico. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa el ciclo con un cliente desconfiado: excava el dolor real por capas hasta la revelación y confirmación, construye conexión personal genuina en el camino (al menos un tema FORMD), y presenta CONECTADO: abre desde el dolor con las palabras del cliente, pinta al menos una escena de su negocio resuelto, siembra al menos dos síes genuinos, y traduce a beneficios concretos sin promesas grandilocuentes. El scope se cubre cuando el desconfiado muestra interés real: pregunta por detalles concretos del siguiente paso (cómo surtirían, cada cuánto, qué necesita hacer)."}, "closing": {"message": "Un desconfiado pidiéndote los detalles del siguiente paso — eso no se compra con promesas: se construye con valor. Acabas de recorrer el camino completo del diagnóstico a la presentación. El cierre te espera en el siguiente mundo. Vamos al desglose.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "presentacion_generica", "severity": "critical", "description": "Presenta catálogo/calidad/años sin conectar con el dolor excavado — el desconfiado se cierra con un déjeme su tarjeta.", "regla_id": "present.dos_mitades", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "promesa_grandilocuente", "severity": "major", "description": "Promesas grandes sin ancla concreta (nunca fallamos, somos los mejores, se lo garantizo todo) — la desconfianza regresa: eso me dijo el anterior.", "regla_id": "present.bala_generica"}, {"id": "pitch_prematuro", "severity": "major", "description": "Presenta antes de haber excavado y confirmado el dolor — recetó sin diagnóstico.", "regla_id": "discovery.receta_sin_diagnostico"}, {"id": "ignora_pistas", "severity": "major", "description": "Deja pasar la pista del dolor o los datos personales del cliente.", "regla_id": "discovery.escalera_capas"}, {"id": "si_capcioso", "severity": "minor", "description": "Preguntas de sí capciosas o huecas que incomodan.", "regla_id": "impulse.tren_del_si"}, {"id": "explica_sin_pintar", "severity": "major", "description": "Presentación de puros datos sin una sola escena.", "regla_id": "present.pintar_imagenes", "severity_fix": "minor->major (BOSS no baja errores de su paso)"}, {"id": "monologo", "severity": "minor", "description": "Bloques largos que atropellan al desconfiado.", "regla_id": "monologo"}], "success_criteria": [{"id": "discovery.dolor_real", "weight": 0.2, "description": "Excava el dolor por capas hasta la revelación completa y lo confirma verbalmente antes de presentar — la presentación no arranca sin diagnóstico terminado.", "regla_id": "discovery.confirmacion_con_sus_palabras"}, {"id": "presentation.conectar_dolor", "weight": 0.2, "description": "La presentación abre nombrando el dolor confirmado con las palabras del cliente y toda la oferta se articula como solución de ESE problema.", "regla_id": "present.dos_mitades"}, {"id": "presentation.pintar_imagenes", "weight": 0.15, "description": "Al menos una escena concreta del negocio del cliente con el problema resuelto, que el cliente recibe entrando en ella.", "regla_id": "present.pintar_imagenes"}, {"id": "presentation.tren_si_si", "weight": 0.15, "description": "Al menos dos preguntas de sí genuino ancladas en lo declarado, respondidas afirmativamente con comodidad.", "regla_id": "impulse.tren_del_si"}, {"id": "presentation.valor_personalizado", "weight": 0.15, "description": "Cero frases de catálogo genérico y cero promesas grandilocuentes sin ancla — todo el valor está personalizado y es creíble para un desconfiado.", "regla_id": "present.beneficio_no_caracteristica"}, {"id": "relationship.cpr", "weight": 0.15, "description": "Toca al menos un tema personal FORMD con genuinidad en el momento natural — y el escepticismo del cliente baja un escalón visible.", "regla_id": "relationship.cpr"}]}'::jsonb WHERE id = '4.16';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. El espejo usa la pregunta que el vendedor promedio teme (y eso a mi de que me sirve?) como consecuencia automatica de no traducir. Ensena sin regano.", "scope": {"skills_in_focus": ["presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en que nunca dejo una caracteristica sola. Digo lo que el producto es, y en la misma frase digo que gana el con eso.\n\nLa caracteristica es mi lenguaje; el beneficio es el suyo. Si solo hablo el mio, me escucha sin entender.", "first_message": "Este maneja una formulacion mas estable a temperatura alta. Que significa para usted: le dura mas antes del siguiente cambio, o sea menos servicios al ano por unidad y menos gente reclamandole.\n\nY como le dura mas, su cliente regresa contento en lugar de regresar a quejarse."}, "you_do": {"prompt": "Eres el dueno de un negocio, atento y de buena disposicion, escuchando lo que el vendedor te presenta. Ya platicaron antes y ya le contaste que tu problema es que pierdes ventas cuando te falta producto. TU REGLA PRINCIPAL: reaccionas segun el vendedor traduzca o no. Si menciona una CARACTERISTICA sin traducirla a un beneficio concreto (una especificacion tecnica, un dato del producto, una certificacion, una marca), respondes con desinteres educado y le devuelves la pregunta que el vendedor promedio teme: y eso a mi de que me sirve? / ajam, y eso que me ayuda? / si, y? SI la traduce a algo concreto que tu ganas (dinero, mas clientes, menos problemas, tiempo, tranquilidad), te enganchas: asientes, preguntas mas al respecto, y conectas con tu propia situacion. Si te tira MUCHAS caracteristicas juntas sin traducir ninguna, te saturas y dices que lo tienes que pensar. NUNCA traduzcas tu por el: si el no dice el beneficio, tu no lo adivinas. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor traduce cada caracteristica que menciona a un beneficio concreto para ese cliente: dinero, clientes, tiempo o tranquilidad. El scope se cubre cuando el cliente se engancha con al menos dos beneficios traducidos y conecta con su propia situacion."}, "closing": {"message": "Eso es traducir. Dijiste lo que el producto es y en la misma frase lo que el gana. La caracteristica es tu idioma; el beneficio es el suyo. El que solo habla el propio, presenta para si mismo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como presentas. Vamos al desglose y te digo cuales se quedaron sin traducir."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "caracteristica_sin_traducir", "severity": "major", "description": "Menciona especificaciones, datos tecnicos o certificaciones sin decir que gana el cliente con eso. El cliente escucha sin entender y contesta y eso a mi de que me sirve.", "regla_id": "present.caracteristica_sin_traducir"}, {"id": "catalogo", "severity": "major", "description": "Encadena varias caracteristicas seguidas sin traducir ninguna. El cliente se satura y se defiende con un lo voy a pensar.", "regla_id": "present.caracteristica_sin_traducir"}, {"id": "beneficio_generico", "severity": "minor", "description": "Traduce a un beneficio que serviria para cualquier negocio (es de calidad, le va a gustar) en lugar de conectarlo con la situacion concreta del cliente.", "regla_id": "present.caracteristica_sin_traducir", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "promesa_falsa", "severity": "critical", "description": "Inventa un beneficio que el producto no da, o exagera un resultado para que suene mejor. El valor se construye con verdad.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}], "success_criteria": [{"id": "presentation.beneficio_no_caracteristica", "weight": 1, "description": "Cada caracteristica que menciona va acompanada de su traduccion a algo concreto que el cliente gana: mas dinero, mas clientes, menos tiempo perdido o menos problemas. La traduccion debe ser especifica de ESE negocio, no generica. Mencionar la caracteristica sola no cumple, aunque sea impresionante.", "regla_id": "present.beneficio_no_caracteristica"}]}'::jsonb WHERE id = '4.2';
UPDATE public.nodes SET practice_script = '{"notes": "El Actor reacciona a imágenes, no a datos — la mecánica espejo enseña la diferencia entre explicar y pintar en vivo. La señal de scope: el cliente COMPLETÓ una escena con detalles propios (la prueba de que entró en ella).", "scope": {"skills_in_focus": ["presentation.pintar_imagenes", "presentation.conectar_dolor"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Escucha la diferencia entre EXPLICAR y PINTAR. Explicar informa.\n\nPintar hace que el cliente se VEA en la escena — y de esa escena ya no se quiere salir.", "first_message": "Explicar suena así: El producto tiene buena movimiento y márgenes competitivos. — Correcto, y frío.\n\nPintar suena así: Imagínese la quincena que viene: llega el cliente de siempre por sus tres litros... y ahora sí los tiene.\n\nSe los lleva, le deja la ganancia a usted y no al de enfrente — y de pasada se lleva unas grasas porque ya que estaba aquí. ¿Ve la diferencia?\n\nEl cliente ya se vio ganando.\n\nAhora el producto no es un dato: es esa mañana."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de un buen descubrimiento: ya contaste tu dolor. Elige uno al azar y menciónalo en tu primera línea: (pierdes ventas por faltantes de tu producto estrella / tienes dinero muerto en producto que no se mueve / te piden algo que tu proveedor no maneja). TU REGLA ESPEJO — reaccionas a IMÁGENES, no a datos: si el vendedor te pinta una escena concreta de TU negocio con el problema resuelto (imagínese que..., piense en la próxima quincena cuando..., usted abriendo la cortina y...), entras en la escena: la completas con detalles tuyos (pues sí, y hasta podría..., no pues eso me ahorraría el coraje de...), y tu interés crece visiblemente. Si el vendedor solo explica con datos y adjetivos (buena calidad, excelente margen, muy rentable), respondes cortés pero plano: ajá, ok, suena bien — sin entrar en ninguna escena. Si la escena que pinta es genérica y no usa TU dolor ni TU negocio, respondes: pues sí, como en todos lados, supongo. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor presenta pintando al menos DOS imágenes concretas del negocio del cliente con el problema resuelto: escenas específicas (con momento, personaje o situación reconocible de SU operación) construidas sobre el dolor declarado — no descripciones abstractas del producto. El scope se cubre cuando el cliente ENTRÓ en al menos una escena: la completó con sus propios detalles o expresó verse en ella."}, "closing": {"message": "El cliente se vio en la escena — y de ahí ya no se quiso salir. Eso es pintar imágenes: la parte del cine que tiene este trabajo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como pintas la imagen. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "explica_sin_pintar", "severity": "major", "description": "Presenta solo con datos y adjetivos (calidad, margen, rentable, confiable) sin construir una sola escena visualizable — el cliente permanece fuera, escuchando información.", "regla_id": "present.pintar_imagenes"}, {"id": "imagen_generica", "severity": "major", "description": "Sus escenas no usan el dolor ni el contexto del cliente — son postales genéricas de éxito que servirían para cualquiera (le va a ir muy bien, va a vender mucho).", "regla_id": "present.pintar_imagenes"}, {"id": "presentacion_generica", "severity": "major", "description": "Ignora el dolor declarado y presenta catálogo.", "regla_id": "present.dos_mitades"}, {"id": "monologo", "severity": "minor", "description": "Pinta sin pausa — no deja al cliente entrar a la escena.", "regla_id": "monologo"}], "success_criteria": [{"id": "presentation.pintar_imagenes", "weight": 0.6, "description": "Pinta al menos dos escenas concretas y específicas del negocio del cliente con el problema resuelto: usa lenguaje de visualización (imagínese, piense en, va a ver que) con momento, personajes o situaciones reconocibles de SU operación. Las escenas logran que el cliente entre: las complete o se vea en ellas.", "regla_id": "present.pintar_imagenes"}, {"id": "presentation.conectar_dolor", "weight": 0.4, "description": "Las imágenes nacen del dolor declarado: la escena pintada es exactamente ese problema resuelto — no una fantasía genérica de éxito.", "regla_id": "present.dos_mitades"}]}'::jsonb WHERE id = '4.3';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. Corrige la doctrina deformada: las balas son del VENDEDOR (hechos positivos sobre ti, producto y precio), no objeciones del cliente. El espejo tiene cuatro estados: dosificada sube, rafaga satura, vaga no mueve, exagerada baja.", "scope": {"skills_in_focus": ["objections.bullet_theory"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en el ritmo. Disparo una bala, dejo que aterrice, y veo como reacciona antes de disparar la siguiente.\n\nNo suelto tres seguidas. Y fijate en algo mas: me guardo las mejores.\n\nTodavia no llego al precio ni a las objeciones, y ahi es donde de verdad las voy a necesitar.", "first_message": "Mire, algo que le puede servir: llevamos catorce anos surtiendo esta zona, asi que cuando hay desabasto general nosotros seguimos entregando. ...\n\nY le comento otra cosa: nuestro tiempo de entrega es de veinticuatro horas dentro de la ciudad."}, "you_do": {"prompt": "Eres el dueno de un negocio, ya en confianza con el vendedor y escuchando su propuesta con interes moderado. TU REGLA PRINCIPAL: tu nivel de interes sube y baja segun COMO disparen las balas. Si el vendedor da UN hecho positivo concreto y te deja reaccionar, tu interes SUBE de manera visible: comentas, preguntas mas, te enganchas. Si dispara TRES O MAS hechos seguidos sin pausa, te saturas: tu interes sube un momento y luego CAE, y respondes con algo como pues suena bien todo, dejeme lo pienso. Si el hecho es VAGO o generico (somos los mejores, tenemos calidad, damos buen servicio) no cuenta como bala: contestas con cortesia neutra y tu interes no se mueve. Si el vendedor dice algo que suena EXAGERADO o poco creible, tu interes BAJA y te pones esceptico: pregunta desconfiada tipo a poco?, y todo eso como me lo garantiza? NUNCA hagas objeciones de precio ni de competencia en este ejercicio. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor sube el impulso disparando balas concretas y verificables de una en una, midiendo la reaccion entre cada una, sin saturar y sin exagerar. El scope se cubre cuando el interes del cliente subio de forma sostenida con al menos dos balas bien colocadas."}, "closing": {"message": "Eso es controlar el impulso. Balas reales, una a la vez, midiendo la reaccion. Y lo mas importante: te quedan balas. Cuando llegues al precio y a las objeciones vas a entender por que eso importa tanto. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como disparas. Vamos al desglose y te digo como quedo tu municion."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "rafaga_de_balas", "severity": "major", "description": "Encadena tres o mas hechos positivos sin pausa. El cliente se satura, el impulso sube y cae, y el vendedor se queda sin municion para lo que viene.", "regla_id": "present.dosificacion_balas"}, {"id": "balas_vagas", "severity": "major", "description": "Afirmaciones genericas sin dato concreto: somos los mejores, tenemos calidad, damos buen servicio. No mueven el impulso porque cualquiera las dice.", "regla_id": "present.bala_generica"}, {"id": "bala_exagerada", "severity": "critical", "description": "Exagera o inventa un hecho para que suene mejor. El cliente se pone esceptico y el impulso baja. El impulso se construye con verdad.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "pitch_prematuro", "severity": "minor", "description": "Se adelanta a precio o cierre. Aqui solo se construye impulso.", "regla_id": "discovery.receta_sin_diagnostico", "severity_override": {"default": "major", "razon": "incidental: error de otro paso"}}], "success_criteria": [{"id": "objections.bullet_theory", "weight": 1, "description": "Dispara balas CONCRETAS y verificables sobre si mismo, su producto o su precio: datos, anos, tiempos, casos reales, condiciones especificas. Las dispara DOSIFICADAS, una a la vez, dejando espacio a la reaccion del cliente antes de la siguiente. Afirmaciones vagas (somos los mejores, damos calidad) no cuentan como balas. Encadenar tres o mas sin pausa no cumple, aunque sean buenas.", "regla_id": "present.balas"}]}'::jsonb WHERE id = '4.6';
UPDATE public.nodes SET practice_script = '{"notes": "Primer drill de impulso. El Actor arranca en interesado-pasivo (déjeme pensarlo) — el estado real más común del campo. Espejo de tres vías: verdad tangible → movimiento; urgencia real → siguiente paso; teatro → escepticismo con castigo de confianza. impulso_falso es critical en TODO el mundo 5: la ética es el diseño.", "scope": {"skills_in_focus": ["impulse.miedo_perdida", "impulse.urgencia"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Escucha los dos aceleradores — y fíjate en el detalle más importante: TODO lo que digo es verdad verificable. El miedo a la pérdida se construye con SUS números, y la urgencia con fechas y hechos reales.\n\nNi una gota de teatro.", "first_message": "Miedo a la pérdida, con sus datos: Usted me dijo que pierde como dos clientes al mes por faltantes. Son veinticuatro al año, Don Ramón — y cada uno se lleva sus compras a la competencia...\n\ny a veces ya no regresa. Eso está pasando hoy, mientras platicamos.\n\nUrgencia, con hechos reales: Esta semana ando levantando los pedidos de la zona — si lo dejamos para la otra, su primer surtido le llegaría hasta el mes que entra. ¿Ve?\n\nNada inventado: su pérdida es real y mi fecha es real. Por eso funciona."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de una buena presentación: el vendedor ya conectó con tu dolor (elígelo al azar: pierdes ~2 clientes al mes por faltantes de tu proveedor / tienes ~15 mil pesos muertos en producto que no se mueve / te piden algo que tu proveedor no maneja y se van con ella a otro lado) y estás INTERESADO PERO PASIVO: tu postura inicial es está bueno, déjeme pensarlo y luego le digo — sin rechazo, pura inercia de no decidir. TU REGLA ESPEJO: (A) si el vendedor hace TANGIBLE tu pérdida con TUS números y datos reales (lo que pierdes al mes, a dónde se va ese dinero, que está pasando HOY), tu pasividad se mueve: pues sí, viéndolo así... y preguntas algo concreto. (B) si te da una razón de urgencia REAL y verificable (su ruta de pedidos de la semana, tiempos de entrega reales, un ciclo real de tu negocio como la quincena o la temporada), tu decisión se acerca: preguntas por el siguiente paso. (C) si INVENTA escasez o urgencia con olor a teatro (es el último que me queda, la promoción se acaba HOY, ya casi no tengo), respondes con escepticismo directo: mmm, eso dicen todos, ¿no? — y tu confianza BAJA visiblemente. (D) si solo repite valor sin acelerador, permaneces amable y pasivo: sí, suena bien, yo le aviso.", "objective": "El vendedor mueve a un interesado-pasivo aplicando los dos aceleradores con verdad: (1) hace tangible la pérdida actual usando los números y datos que el cliente declaró (cuantifica lo que pierde por mes/año, nombra a dónde se va), y (2) da al menos una razón de urgencia real y verificable para decidir ahora (ruta, tiempos, ciclo del negocio) — sin inventar escasez ni teatro. El scope se cubre cuando el cliente pasó de déjeme pensarlo a preguntar por el siguiente paso concreto."}, "closing": {"message": "Lo moviste — y sin inventarle nada: su pérdida era real y tu fecha era real. Así se acelera una curva sin quemar la confianza. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como manejas el miedo a perder. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "impulso_falso", "severity": "critical", "description": "Inventa escasez, urgencia o presión sin ancla real: es el último, la promo se acaba hoy, ya casi no tengo, otros lo están apartando. El cliente lo huele (eso dicen todos) y la confianza construida en tres mundos se quema en una frase. El pecado capital de este mundo.", "regla_id": "impulse.escasez_inventada"}, {"id": "presion_directa", "severity": "major", "description": "Sustituye los aceleradores por presión frontal: ándele, anímese, no lo piense tanto, ¿entonces qué, sí o no? — empuja la curva en vez de acelerarla.", "regla_id": "impulse.presion_directa"}, {"id": "perdida_generica", "severity": "major", "description": "Habla de pérdida en abstracto (está perdiendo dinero, le conviene) sin usar los números ni el dolor específico que el cliente declaró.", "regla_id": "impulse.miedo_perdida_generico"}, {"id": "monologo", "severity": "minor", "description": "Descarga ambos aceleradores en un solo bloque sin dejar reaccionar al cliente.", "regla_id": "monologo"}], "success_criteria": [{"id": "impulse.miedo_perdida", "weight": 0.5, "description": "Hace tangible la pérdida ACTUAL con los datos del cliente: cuantifica (clientes/dinero por mes o año), nombra el destino de la pérdida (la competencia, el dinero muerto), y la ancla en el presente (está pasando hoy). Todo derivado de lo que el cliente declaró — nada inventado.", "regla_id": "impulse.miedo_perdida"}, {"id": "impulse.urgencia", "weight": 0.5, "description": "Da al menos una razón real y verificable para decidir ahora: su ruta o ciclo de pedidos, tiempos de entrega concretos, o un ciclo real del negocio del cliente. La urgencia nace de hechos, no de presión — y el cliente la recibe sin escepticismo.", "regla_id": "impulse.urgencia"}]}'::jsonb WHERE id = '4.8';
UPDATE public.nodes SET practice_script = '{"notes": "El Actor valida especificidad: hace cuentas ante números creíbles, reconoce referencias reales de zona, y ataca lo vago con ¿como quiénes? — la pregunta que desnuda el Jones falso. El company_brain provee las referencias reales de cada empresa (clientes existentes de la zona) para que el ejemplo dinámico sea verificable.", "scope": {"skills_in_focus": ["impulse.avaricia", "impulse.efecto_jones"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Los últimos dos aceleradores. La avaricia bien usada no es codicia — es mostrarle la ganancia EXTRA en números de su negocio.\n\nY el efecto Jones es la fuerza más vieja del mundo: si a los de al lado les funciona, yo también quiero. Con nombres reales — o nada.", "first_message": "Más por menos, con números: Con el margen de esta línea, cada caja le deja ochenta pesos más que la que maneja — son como mil doscientos extra al mes sin vender ni una pieza más. Efecto Jones, con verdad: La negocios de la San José le entró hace dos meses — el señor Aurelio ya va en su tercer pedido.\n\nY el negocio grande de la avenida, igual. Por esta zona ya se está moviendo fuerte.\n\n¿Nota que no presioné? Solo le mostré la ganancia y le conté quién más ya la está cobrando."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de una buena presentación conectada a tu dolor (elígelo al azar como en drills previos) y estás en modo interesado-pasivo: suena bien, déjeme pensarlo. TU REGLA ESPEJO: (A) si el vendedor te muestra ganancia EXTRA con números concretos y creíbles de tu operación (margen por caja, ahorro al mes, beneficio adicional calculado), tu interés se activa: haces cuentas en voz alta (a ver, ¿ochenta por caja?...) y preguntas detalles. (B) si te da prueba social ESPECÍFICA y verificable (negocio con nombre o ubicación reconocible de tu zona, tiempo que lleva, resultado concreto), tu confianza sube: ah, ¿el de la San José? sí lo ubico... y tu resistencia baja visiblemente. (C) si la prueba social es VAGA (muchos clientes, varios negocios, todo mundo lo está llevando — sin un solo nombre o referencia verificable), respondes escéptico: ¿ah sí? ¿como quiénes? — y si no puede concretar, tu desconfianza sube. (D) si los números de ganancia son exagerados o redondos sin sustento (va a duplicar sus ventas), respondes: mmm, eso suena a mucho, ¿no?", "objective": "El vendedor aplica los dos aceleradores con concreción: (1) muestra la ganancia extra en números específicos y creíbles del negocio del cliente (margen, ahorro o beneficio mensual calculado), y (2) da prueba social específica y verificable — al menos una referencia con nombre, ubicación o detalle reconocible, con su resultado concreto. El scope se cubre cuando el cliente hizo cuentas en voz alta O validó la referencia social, y pasó de pasivo a preguntar por el siguiente paso."}, "closing": {"message": "Le mostraste la ganancia con números y le contaste quién ya la está cobrando — y su déjeme pensarlo se convirtió en cuánto y cuándo. Así trabajan estos dos. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como construyes la sensacion de ventaja. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "impulso_falso", "severity": "critical", "description": "Inventa prueba social o números: referencias que no existen, cifras infladas, todo mundo lo lleva sin poder nombrar a nadie. Si el cliente pregunta ¿como quiénes? y no hay respuesta concreta, el factor era teatro.", "regla_id": "impulse.jones_vago"}, {"id": "promesa_grandilocuente", "severity": "major", "description": "Ganancias exageradas sin sustento: va a duplicar sus ventas, se va a llenar de clientes — el cliente responde eso suena a mucho.", "regla_id": "present.bala_generica"}, {"id": "presion_directa", "severity": "major", "description": "Cambia los aceleradores por empuje frontal: no se lo pierda, todos le están entrando, apúrese.", "regla_id": "impulse.presion_directa"}, {"id": "perdida_generica", "severity": "minor", "description": "Ganancia en abstracto (le conviene, va a ganar más) sin un solo número.", "regla_id": "impulse.miedo_perdida_generico", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "impulse.avaricia", "weight": 0.5, "description": "Muestra ganancia extra con números concretos y creíbles del negocio del cliente: margen por unidad, beneficio mensual calculado, ahorro específico — cifras que el cliente puede verificar con sus propias cuentas, no promesas redondas (duplicar ventas).", "regla_id": "impulse.avaricia"}, {"id": "impulse.efecto_jones", "weight": 0.5, "description": "Da al menos una prueba social específica y verificable: negocio con nombre, ubicación o seña reconocible + tiempo + resultado concreto. El cliente la puede validar (o al menos ubicar) — nunca el vago muchos clientes ya lo llevan.", "regla_id": "impulse.efecto_jones"}]}'::jsonb WHERE id = '4.9';
UPDATE public.nodes SET practice_script = '{"notes": "Drill quirúrgico del momento del cierre: el Actor entra MADURO (recapitula su propio convencimiento) y el examen es puro: ¿asume con opciones o abre la puerta? La regla espejo da segunda oportunidad tras un déjeme pensarlo — el vendedor puede corregir en vivo, que es como se aprende. abre_puerta_al_no es critical: es EL tema del nodo.", "scope": {"skills_in_focus": ["closing.cierre_asumido", "impulse.poder_asumir"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 1}, "phases": {"i_do": {"briefing": "Escucha el momento exacto del cierre asumido. La conversación ya hizo todo el trabajo — yo nada más pregunto los detalles, con opciones donde cualquier respuesta es un sí.", "first_message": "El cliente ya conectó su dolor, ya hizo la cuenta, ya me preguntó cada cuánto surtimos. El cierre: Perfecto Don Ramón — entonces para que arranque la quincena surtido, ¿le armo el pedido con las 5 cajas o de una vez el combo de 8 que le baja el precio por pieza?\n\n— Y ya. Sin ¿le interesa?\n\n, sin ¿qué piensa? La decisión grande ya estaba tomada por la conversación.\n\nYo solo pregunté la chica."}, "you_do": {"prompt": "Eres el dueño de un negocio con la decisión prácticamente tomada: la conversación fue excelente — el vendedor conectó tu dolor (elígelo: faltantes que te cuestan clientes / dinero muerto en producto parado / algo que piden y no consigues), hiciste la cuenta y te salió a favor, asentiste varias veces y hasta preguntaste cada cuánto surten. Tu primera línea recapitula ese estado: Pues sí, la verdad la cuenta sale... y a mí eso de quedarme sin producto cada quincena ya me tiene harto. REGLAS ESPEJO: (1) Si el vendedor cierra ASUMIDO con opciones concretas (¿5 u 8?, ¿lunes o miércoles?, ¿factura o nota?), eliges una opción con naturalidad y la decisión queda tomada — puedes ajustar un detalle (mejor el miércoles porque el lunes recibo producto) pero avanzas. (2) Si el vendedor pregunta con puerta al no (¿le interesa?, ¿entonces qué piensa?, ¿quiere que le deje información?), usas la puerta con flojera natural: pues déjeme pensarlo tantito y le aviso — no porque no quieras: porque te la ofrecieron. (3) Si tras tu déjeme pensarlo el vendedor corrige y cierra asumido con opciones, todavía puedes avanzar (la curva sigue arriba). (4) Si el cierre asume detalles nunca platicados o cantidades absurdas, lo frenas: espérese, ¿de dónde sacó eso? (5) Si el vendedor sigue presentando en lugar de cerrar (más beneficios, más catálogo), te empiezas a enfriar visiblemente: bueno, sí, eso ya me lo había dicho...", "objective": "El vendedor detecta que la decisión está madura (la recapitulación del cliente lo grita) y cierra ASUMIDO a la primera oportunidad: pregunta de opciones concretas sobre detalles del pedido (cantidad, día, forma) donde cualquier respuesta es un sí — sin preguntas de interés, sin seguir presentando, sin abrir la puerta al no. El scope se cubre cuando el cliente eligió una opción y la decisión quedó tomada."}, "closing": {"message": "¿Viste lo fácil? La conversación ya había hecho todo — tú solo preguntaste la decisión chica y la grande cayó sola. Así se cierra en Closer: siempre asumido. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como pides la decision. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "abre_puerta_al_no", "severity": "critical", "description": "Cierra con pregunta de interés o de veredicto (¿le interesa?, ¿qué piensa?, ¿lo pensamos?) o propone él mismo el aplazamiento (¿le dejo información?) — en el nodo cuyo único tema es no abrir esa puerta, abrirla domina el score.", "regla_id": "close.mal_cierre"}, {"id": "sigue_presentando", "severity": "major", "description": "El cliente está maduro y el vendedor agrega beneficios, catálogo o argumentos en lugar de cerrar — deja pasar el momento y el cliente se enfría.", "regla_id": "close.sigue_presentando"}, {"id": "atropello", "severity": "major", "description": "Su cierre asume cantidades o condiciones nunca platicadas — el asumido sin rieles.", "regla_id": "close.asume_con_presion"}, {"id": "persigue", "severity": "major", "description": "Si el cliente titubea, cambia el asumir por súplica o descuento de pánico.", "regla_id": "close.persigue"}, {"id": "monologo", "severity": "minor", "description": "Entierra su pregunta de cierre en un bloque largo — el cierre se pregunta y se calla.", "regla_id": "monologo"}], "success_criteria": [{"id": "closing.cierre_asumido", "weight": 0.6, "description": "Cierra con pregunta asumida de opciones concretas y realistas (cantidad/día/forma sobre lo ya platicado) en el momento maduro — sin ¿le interesa?, sin ¿qué piensa?, sin ofrecer información para después. Si el cliente elige, confirma y sella con naturalidad.", "regla_id": "close.alternativa"}, {"id": "impulse.poder_asumir", "weight": 0.4, "description": "Todo su lenguaje del tramo final es de avance (cuándo/cuál/cómo) sobre los rieles de la conversación — referencia lo acordado (la cuenta que sacamos, lo de la quincena) sin reabrir la decisión de fondo.", "regla_id": "close.asumir_venta"}]}'::jsonb WHERE id = '5.1';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. El corazon del Mundo 5. El espejo distingue tres calidades: discutir cierra al cliente, atravesar-sin-bala produce desgano medible, y el circuito completo recupera el animo. Ensena en carne propia por que el paso intermedio no es opcional.", "scope": {"skills_in_focus": ["objections.circulo_cierre", "objections.bullet_theory", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Cuenta tres movimientos despues de la objecion. Uno: la atravieso sin discutir.\n\nDos, y este es el que todos se saltan: meto una bala NUEVA, algo positivo que no habia dicho, para volver a subir el impulso. Tres: cierro con accion.\n\nSi me salto el dos, estoy pidiendole una decision a alguien desanimado.", "first_message": "Entiendo perfecto, y tiene razon en cuidar el flujo. Mi ultimo cliente estaba igual, y lo que encontramos fue que arrancando con la mitad del pedido se movia solo y el segundo ya salia de lo vendido.\n\nY algo mas: en su primer pedido le respetamos precio por noventa dias aunque suba la lista.\n\nEntonces, arrancamos con media caja o con caja completa?"}, "you_do": {"prompt": "Eres el dueno de un negocio. Ya te presentaron y te intereso, pero tienes UNA preocupacion real: elige una al azar y quedate con ella — el flujo esta apretado este mes / ya te fallo un proveedor antes y quedaste mal con tus clientes / no sabes si se va a vender / tu socio o tu esposa participa en las decisiones de compra. TU REGLA PRINCIPAL: sacas tu preocupacion cuando el vendedor intente cerrar, y despues reaccionas segun COMO la maneje. Si DISCUTE o minimiza tu preocupacion, te cierras y ya no compras. Si la atraviesa bien PERO cierra de inmediato sin darte ninguna razon nueva, contestas con desgano: pues si, dejeme lo pienso / ahorita no se, luego le digo. Tecnicamente te respondio, pero tu animo quedo abajo y no vas a decidir desde ahi. Si la atraviesa bien, te da un HECHO POSITIVO NUEVO que no habia mencionado, y despues cierra con una pregunta concreta del siguiente paso, tu animo se recupera visiblemente y contestas esa pregunta avanzando. Si el hecho nuevo es vago o es repetir algo que ya habia dicho, no cuenta: reaccionas con desgano. NUNCA saques una segunda objecion en este ejercicio: es una sola, una vuelta. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa el circuito ante una objecion: la atraviesa sin discutir, re-impulsa con un hecho positivo NUEVO, y cierra con una accion concreta. El scope se cubre cuando el cliente recupera el animo y responde avanzando al siguiente paso."}, "closing": {"message": "Esa es la vuelta completa. Atravesaste, volviste a subir el impulso con algo nuevo, y cerraste. Fijate en que sin el paso de en medio le habrias pedido una decision a alguien desanimado. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo la vuelta."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "salta_la_bala", "severity": "critical", "description": "Atraviesa la objecion y cierra de inmediato, sin re-impulsar. Le pide una decision al cliente en el punto mas bajo de su animo, y recibe un lo voy a pensar.", "regla_id": "objection.cierra_sin_bala", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "bala_repetida", "severity": "major", "description": "Como hecho nuevo repite algo que ya habia dicho. No sube el impulso: comunica que ya no tiene nada mas.", "regla_id": "objection.bala_repetida"}, {"id": "discute_la_objecion", "severity": "critical", "description": "Discute, minimiza o intenta demostrar que la preocupacion del cliente no es valida. Ganar la discusion es perder la venta.", "regla_id": "objection.discutir"}, {"id": "no_cierra", "severity": "major", "description": "Atraviesa y re-impulsa pero nunca vuelve a pedir la decision. Se quedo a un paso.", "regla_id": "objection.circulo_de_cierre"}], "success_criteria": [{"id": "objections.circulo_cierre", "weight": 0.35, "description": "Atraviesa la objecion sin discutir ni minimizar, usando validacion genuina antes de responder. El cliente debe sentir que lo escucharon, no que le ganaron un argumento.", "regla_id": "objection.circulo_de_cierre"}, {"id": "objections.bullet_theory", "weight": 0.35, "description": "Despues de atravesar, mete un hecho positivo NUEVO que no habia mencionado antes, concreto y verificable. Repetir un argumento ya dicho no cuenta: no sube el impulso, lo desgasta. Este es el paso que casi todos se saltan.", "regla_id": "present.balas"}, {"id": "flow.close_with_action", "weight": 0.3, "description": "Cierra con una pregunta o accion concreta del siguiente paso, cuya respuesta solo tiene sentido si el cliente avanza. Nada de preguntar si quiere, si le parece o si lo va a pensar.", "regla_id": "close_with_action"}]}'::jsonb WHERE id = '5.10';
UPDATE public.nodes SET practice_script = '{"notes": "La cadena de dos con espejo de temple: el Actor detecta el desánimo textual (el drenaje real que las cadenas producen en el campo) y lo verbaliza. repite_bala entrena que cada motivo pide SU munición. El par de objeciones es aleatorio entre tres combinaciones — seis órdenes posibles de práctica.", "scope": {"skills_in_focus": ["objections.reframe", "objections.no_defensivo", "objections.bullet_theory", "impulse.indiferencia"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Ahora en serie: resuelvo una objeción... y llega la siguiente.\n\nFíjate en dos cosas: cada una recibe SU bala — nunca gasto dos en la misma — y mi ánimo no se mueve: la tercera objeción me encuentra igual de sereno que la primera.", "first_message": "Está caro. — Recibo, cuenta de costo por servicio, avanzo.\n\nSí pero es que ya tengo proveedor de años... — Recibo: los años de relación valen, claro.\n\nBala dos: por eso no le pido que lo deje — empiece con una línea que él no le surte bien y compare usted mismo. Avanzo.\n\nMmm, déjeme consultarlo con mi hermano... — Recibo.\n\nBala tres: perfecto — le dejo la cuenta por escrito para que la vean juntos, y me dice usted: ¿lo alcanzo el jueves ya que hayan platicado, o mejor el viernes? — Tres objeciones, tres balas, cero desgaste.\n\nLa cadena se gana con dosificación y temple."}, "you_do": {"prompt": "Eres el dueño de un negocio interesado de verdad — la presentación conectó tu dolor (elígelo y menciónalo al abrir) — pero eres de los que se aseguran ANTES de decidir: tu proceso natural es sacar TODAS tus dudas, una por una. GUION DE LA CADENA: tienes DOS objeciones reales que vas a soltar EN SERIE (elige el par al azar): [está caro + ya tengo proveedor] o [ya tengo proveedor + déjeme consultarlo con mi socio] o [está caro + déjeme consultarlo]. Sueltas la PRIMERA tras tu línea inicial. REGLA DE LA CADENA: cuando el vendedor resuelve bien la primera (reencuadre + bala verificable), NO cedes todavía — reconoces el punto (bueno, eso sí...) e inmediatamente sueltas la SEGUNDA (sí pero es que además...). Solo cuando AMBAS están bien resueltas, cedes y avanzas la decisión. ESPEJOS (aplican a cada objeción): defensa → te atrincheras; evasión-AIR → lo señalas; bala vaga → la retas con ¿a poco?; cargador vaciado (3+ argumentos juntos) → te abruma y la cadena se alarga; MISMA bala repetida para la segunda objeción → no te convence: eso ya me lo dijo, pero yo le hablo de otra cosa. ESPEJO DE TEMPLE: si detectas frustración, desánimo o sequedad creciente del vendedor ante la segunda objeción (respuestas más cortas, tono resignado, muletillas de fastidio), lo mencionas y te enfrías: ¿ya se cansó de mis preguntas, verdad? Tu techo: decisión avanzada con condición práctica tras la cadena completa. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor sostiene una cadena de DOS objeciones reales consecutivas: reencuadra cada una con SU propia bala (nunca repite munición ni la apila), mantiene la calidez y serenidad idénticas de la primera a la última (cero frustración textual ante la cadena), y tras resolver ambas avanza la decisión con naturalidad. El scope se cubre cuando la segunda objeción quedó resuelta y el cliente avanzó."}, "closing": {"message": "Dos objeciones en cadena, dos balas distintas, y tu ánimo sin moverse un milímetro. Así se ve un arsenal bien dosificado en manos serenas. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito. Vamos al desglose y te digo como quedo tu municion."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "severity": "critical", "description": "La defensa aparece en cualquier eslabón de la cadena.", "regla_id": "objection.discutir"}, {"id": "se_desanima_en_cadena", "severity": "major", "description": "La segunda objeción le drena el ánimo: respuestas más cortas, tono resignado o fastidio detectable — el cliente lo nota (¿ya se cansó de mis preguntas?).", "regla_id": "objection.se_desanima"}, {"id": "repite_bala", "severity": "major", "description": "Usa la misma bala para la segunda objeción — munición equivocada que no responde al motivo nuevo.", "regla_id": "objection.bala_repetida"}, {"id": "vacia_el_cargador", "severity": "major", "description": "Apila argumentos en cualquier respuesta de la cadena.", "regla_id": "objection.vacia_el_cargador"}, {"id": "air_a_objecion", "severity": "critical", "description": "Evade cualquiera de las objeciones con cambio de tema.", "regla_id": "objection.air_a_objecion"}, {"id": "impulso_falso", "severity": "critical", "description": "Cualquier bala inventada en la cadena.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "descuento_de_panico", "severity": "major", "description": "El precio cede por pánico en cualquier punto.", "regla_id": "close.descuento_de_panico"}, {"id": "monologo", "severity": "minor", "description": "Bloques largos que alargan la cadena.", "regla_id": "monologo"}], "success_criteria": [{"id": "objections.reframe", "weight": 0.3, "description": "Cada objeción de la cadena recibe su reencuadre completo: recibida, entendida, respondida al contenido específico, y avanzada — ninguna queda a medias ni se resuelve con la inercia de la anterior.", "regla_id": "objection.rrr"}, {"id": "objections.bullet_theory", "weight": 0.3, "description": "Dosificación bajo presión: UNA bala distinta y ajustada por objeción — sin repetir munición para la segunda, sin apilar cargador, con las balas aguantando el ¿a poco?", "regla_id": "present.balas"}, {"id": "objections.no_defensivo", "weight": 0.2, "description": "Cero defensa y cero evasión a lo largo de toda la cadena — la segunda objeción no lo pone a la defensiva aunque llegue justo tras resolver la primera.", "regla_id": "objection.discutir"}, {"id": "impulse.indiferencia", "weight": 0.2, "description": "El temple de la cadena: calidez y serenidad idénticas ante la primera y la segunda — sin frustración, sin sequedad creciente, sin tono de fastidio. SW3 sostenido cuando el sí se aleja un turno más.", "regla_id": "impulse.indiferencia"}]}'::jsonb WHERE id = '5.12';
UPDATE public.nodes SET practice_script = '{"notes": "El nodo del silencio: el Actor delibera de verdad (pausas pensativas que NO son rechazo) y decide a favor solo si el vendedor aguanta. La mecánica enseña la lección contraintuitiva: la pausa del cliente es su proceso, no tu fracaso. La segunda ola (reaseguro) entrena la firmeza breve. llena_el_silencio es critical — es EL tema. En texto, el silencio del vendedor se manifiesta como acompañamiento mínimo; cuando exista pipeline de audio, este nodo ganará su dimensión real de pausas medidas.", "scope": {"skills_in_focus": ["closing.sin_miedo", "impulse.indiferencia"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Te voy a enseñar el momento donde más ventas se suicidan: el silencio después del cierre. Escucha lo que hago después de preguntar — NADA.\n\nY escucha lo que el miedo le hace hacer a otros.", "first_message": "Cierro: ¿Le armo las 5 cajas o el combo de 8? — Y el cliente se queda callado.\n\nPiensa. El silencio pesa...\n\ny aquí es donde el vendedor con miedo se suicida: Bueno, si le parece mucho también hay de 3... o si quiere lo piensa y...\n\n— ¡Acaba de deshacer su propio cierre! El cliente ni había dicho nada.\n\nYo, en cambio: pregunto... y me callo.\n\nTres segundos. Cinco.\n\nLos que sean. El que habla primero después del cierre, pierde — y no vas a ser tú."}, "you_do": {"prompt": "Eres el dueño de un negocio convencido pero DELIBERATIVO: la conversación fue buena, el valor está claro, y cuando algo te convence... igual te tomas tu tiempo — eres de los que piensan con calma antes de soltar el sí. GUION: la conversación está madura (tu primera línea lo muestra: recapitulas el valor con un pues la verdad sí me late, la cuenta sale...). Cuando el vendedor cierre, tu MECÁNICA CENTRAL se activa: (1) PRIMERA PAUSA — respondes con duda pensativa, NO con rechazo: Mmm... — o — Déjeme ver... — estás pensando de verdad, sopesando. (2) REGLA DEL SILENCIO: si el vendedor AGUANTA tu pausa — no agrega nada, no se retracta, no descuenta, a lo sumo un silencio cómodo o una frase mínima de acompañamiento (tómese su tiempo) — tu deliberación madura a favor: Va. Vamos a hacerlo. ¿Dijo que el lunes llega? y eliges. (3) Si el vendedor LLENA EL SILENCIO — se retracta (bueno, si le parece mucho...), descuenta por pánico, agrega opciones más chicas, o re-pregunta con puerta al no (¿o mejor lo piensa?) — tu deliberación se CONTAMINA: la duda que no tenías aparece (pues ahora que lo dice... déjeme pensarlo bien) y la decisión se aplaza. (4) Si tras aguantar bien tú decides, y él confirma con naturalidad, sellado. (5) Segunda ola opcional: tras tu Va, puedes soltar un ¿y sí me conviene, verdad? — buscando reaseguro: la respuesta correcta es breve y firme (la cuenta que sacamos lo dice solo); la insegura o sobre-vendedora te contamina de nuevo.", "objective": "El vendedor cierra asumido y AGUANTA el silencio deliberativo del cliente: tras su pregunta de cierre, no agrega, no se retracta, no descuenta ni reabre la decisión — sostiene la pausa con serenidad (silencio o acompañamiento mínimo) hasta que el cliente decide solo. Si el cliente busca reaseguro, responde breve y firme sin re-vender. El scope se cubre cuando el cliente decidió afirmativamente tras deliberar y la decisión quedó sellada."}, "closing": {"message": "Preguntaste... y te callaste. El silencio pesó — y lo aguantaste. Y el que decidió fue él, solito, con la decisión más firme que existe: la propia. Eso es cerrar sin miedo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo que tanto aguantaste el silencio."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "llena_el_silencio", "severity": "critical", "description": "Tras cerrar, no aguanta la pausa: se retracta (si le parece mucho hay de 3...), descuenta por pánico, apila argumentos nuevos o reabre con ¿o mejor lo piensa? — deshace su propio cierre y siembra la duda que no existía. El suicidio clásico que este nodo entrena a evitar.", "regla_id": "close.llena_el_silencio", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "abre_puerta_al_no", "severity": "major", "description": "Su cierre inicial ya llega con puerta (¿le interesa?) — el silencio que sigue es de otro examen.", "regla_id": "close.mal_cierre", "severity_override": {"default": "critical", "razon": "incidental: fuera del foco del nodo"}}, {"id": "persigue", "severity": "major", "description": "Presiona la deliberación: ándele, anímese, ¿entonces qué? — el silencio del cliente no es invitación a empujar.", "regla_id": "close.persigue"}, {"id": "sobre_reaseguro", "severity": "minor", "description": "Ante el ¿y sí me conviene, verdad?, responde re-vendiendo con un bloque de argumentos — la firmeza breve era la respuesta.", "regla_id": "consolidation.sigue_vendiendo", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "monologo", "severity": "minor", "description": "Cualquier bloque largo en la fase de deliberación.", "regla_id": "monologo"}], "success_criteria": [{"id": "closing.sin_miedo", "weight": 0.6, "description": "Cierra con claridad y sostiene el silencio deliberativo: tras su pregunta de cierre no se retracta, no descuenta, no agrega opciones menores ni reabre la decisión — sus turnos durante la pausa son silencio o acompañamiento mínimo y sereno. Ante la búsqueda de reaseguro, responde breve y firme sin re-vender.", "regla_id": "close.aguanta_silencio"}, {"id": "impulse.indiferencia", "weight": 0.4, "description": "La serenidad SW3 sostiene el momento: cero ansiedad textual durante la deliberación del cliente, cero necesidad de acelerar su decisión — cálido, presente y en calma con cualquier resultado.", "regla_id": "impulse.indiferencia"}]}'::jsonb WHERE id = '5.13';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo — doctrina de desarrollo de cuenta (CAMPO, Emilio). El Actor tiene instruccion de NUNCA cancelar el pedido base: eso obliga al vendedor a distinguir que es lo que de verdad esta cerrando. El espejo castiga reabrir el pedido base con confusion del cliente.", "scope": {"skills_in_focus": ["closing.cerrar_incremento", "closing.cierre_asumido", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en que NO vuelvo a cerrar el pedido base. Ese ya esta, no lo toco, no lo pongo en duda.\n\nCierro unicamente lo que agregue. Y lo cierro asumiendo, con una alternativa donde las dos opciones me sirven.\n\nY en cuanto lo digo, me callo.", "first_message": "Entonces le queda lo de siempre, mas las cajas de mas que platicamos.\n\nEsas se las mando en la misma entrega o prefiere que se las deje aparte?"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO, sin quejas. Ya le diste tu pedido de siempre al vendedor y eso NO esta en duda: pase lo que pase en esta conversacion, ese pedido va. No lo canceles ni lo pongas en duda nunca.\n\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Adopta el tipo de negocio y las familias del contexto de la empresa. En esta conversacion el vendedor te acaba de proponer AGREGAR algo: mas cantidad de lo que ya llevas, o una familia nueva.\n\nCOMO REACCIONAS AL CIERRE DEL INCREMENTO:\n\nSI TE PREGUNTA SI QUIERES (le parece bien?, como lo ve?, quiere que se lo ponga?): contestas dejeme lo pienso o la proxima quincena lo vemos. No es que no te interese: es que te dio la salida y la tomaste.\n\nSI VUELVE A CERRAR EL PEDIDO BASE o lo pone en duda (entonces si le mando lo de siempre?): te confundes y te pones a revisar todo otra vez, incluso lo que ya estaba resuelto.\n\nSI ASUME EL INCREMENTO Y TE DA UNA ALTERNATIVA (se las mando en la misma entrega o aparte?, le pongo las cinco o arrancamos con tres?): contestas la pregunta con naturalidad y con eso queda cerrado.\n\nSI DA EL CIERRE Y SE QUEDA CALLADO esperando tu reaccion: usas ese silencio para dudar y dices que lo piensas.\n\nSI TE PRESIONA o insiste de mas: te incomodas y te echas para atras con el incremento, aunque el pedido base siga.\n\nResponde en 1 o 2 frases, natural.", "objective": "El vendedor cierra unicamente el incremento — lo que se agrega al pedido base — asumiendolo y ofreciendo una alternativa donde ambas opciones le sirven, sin volver a poner en duda el pedido de siempre y sin dejar silencio despues del cierre. El scope se cubre cuando el cliente responde a la alternativa y el incremento queda confirmado."}, "closing": {"message": "Eso es cerrar el incremento. No volviste a vender lo que ya estaba, no le preguntaste si queria, y le diste una alternativa donde las dos te servian. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo ese cierre."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pregunta_si_quiere", "severity": "critical", "description": "Cierra preguntando si le parece bien, si lo quiere o como lo ve. Le entrega la salida y el cliente toma la comoda: lo voy a pensar.", "regla_id": "close.mal_cierre"}, {"id": "reabre_el_pedido_base", "severity": "major", "description": "Vuelve a confirmar o poner en duda el pedido de siempre. Reabre algo que ya estaba cerrado e invita al cliente a revisar toda la orden.", "regla_id": "close.reabre_pedido_base"}, {"id": "silencio_despues_del_cierre", "severity": "major", "description": "Da el cierre y espera la reaccion. En ese silencio el cliente encuentra la razon para posponer.", "regla_id": "close.devuelve_el_volante"}, {"id": "presiona", "severity": "major", "description": "Insiste de mas despues de haber cerrado. Con un cliente de cartera la presion cuesta la relacion, que vale mas que el incremento.", "regla_id": "close.persigue"}], "success_criteria": [{"id": "closing.cerrar_incremento", "weight": 0.4, "description": "Cierra UNICAMENTE lo que se agrega — las cantidades de mas o la familia nueva — sin volver a poner en duda el pedido base. Reabrir el pedido de siempre no cumple: ese ya estaba resuelto y ponerlo en la mesa otra vez invita al cliente a revisarlo todo.", "regla_id": "close.cierra_solo_incremento"}, {"id": "closing.cierre_asumido", "weight": 0.35, "description": "Asume el incremento y ofrece una alternativa donde las dos opciones le sirven al vendedor. Preguntar si lo quiere, si le parece bien o como lo ve, no cumple: invita al lo voy a pensar.", "regla_id": "close.alternativa"}, {"id": "flow.close_with_action", "weight": 0.25, "description": "Despues del cierre no deja silencio esperando reaccion. La pregunta de alternativa ES el cierre con accion: la respuesta del cliente confirma el incremento sin que se lo hayan pedido explicitamente.", "regla_id": "close_with_action"}]}'::jsonb WHERE id = '5.14';
UPDATE public.nodes SET practice_script = '{"notes": "BOSS del Mundo 7 contra el desconfiado d5 — el examen integrador de las dos especies del no: bloqueo (AIR) y objeciones (reframe+balas) en la misma conversación. Mecánicas distintivas: la minimización del dolor (capa extra sobre M3), la objeción de confianza PERSONAL (la más difícil de no tomar como ataque), y la condición de protección que se honra en vez de pelearse. Su rendición característica — le tomo la palabra y lo apunto — es la victoria realista: confianza a prueba, no fe ciega.", "scope": {"skills_in_focus": ["blocks.air", "objections.reframe", "objections.no_defensivo", "objections.bullet_theory", "discovery.dolor_real", "closing.cierre_asumido"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 20, "max_duration_seconds": 480, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil DESCONFIADO EXTREMO: años de vendedores que prometieron y fallaron te dejaron un escudo grueso — no eres grosero, eres impenetrable por default. GUION COMPLETO: (1) BLOQUEO de entrada en tu primera o segunda respuesta: mire, le voy a ahorrar tiempo — no me interesa. Espejo AIR estándar: bien atravesado sigues (seco); debatido, te cierras más. (2) DOLOR oculto (elige: proveedor que te falla quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — por capas, con pista del aunque, y una capa EXTRA de desconfianza: al revelarlo, lo minimizas de inmediato (pero bueno, así es esto, todos fallan igual) — el vendedor debe validar que NO es normal y cuantificarlo para que lo tomes en serio. (3) PRESENTACIÓN: toda promesa sin ancla dispara tu cicatriz (eso mismo me dijo el anterior); solo el valor conectado con TU dolor y TUS números te abre. (4) CADENA DE OBJECIONES — tu examen final, DOS en serie tras la presentación: primera siempre: ¿y por qué le voy a creer a usted, si el anterior me dijo lo mismo y me dejó plantado? (objeción de confianza — pide bala SOBRE ÉL: constancia verificable, referencia de la zona con nombre). Segunda al azar: está caro / déjeme pensarlo con calma que ya me han agarrado de bajada. Espejos completos de 7.2/7.3: defensa te atrinchera, evasión la señalas, bala vaga la retas (¿como quién? voy a ir a preguntarle, ¿eh?), cargador vaciado te abruma, bala repetida no te convence. (5) Si TODO se sostuvo: tu rendición es característica — está bien... pero le voy a tomar la palabra de todo lo que dijo, ¿eh? Lo apunto. — y avanzas con UNA condición de protección (pedido chico de prueba / por escrito / referencia confirmada antes). Deliberación final con pausa — espejo de silencio del 6.3. Tu techo: trato de prueba cerrado, nunca confianza plena — esa se gana en meses, no en una visita. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa la conversación con el desconfiado extremo: atraviesa el bloqueo con AIR, excava el dolor Y desmonta su minimización cuantificándolo, presenta sin una sola promesa sin ancla, sostiene la cadena de dos objeciones — la de confianza personal con bala sobre sí mismo verificable, y la segunda con su munición propia — con temple idéntico, y cierra asumido aceptando la condición de protección del cliente, aguantando la deliberación final. El scope se cubre con el trato de prueba cerrado."}, "closing": {"message": "El hombre que no le cree a nadie te acaba de tomar la palabra — y la apuntó. Atravesaste su bloqueo, desmontaste su resignación, y cada bala tuya aguantó su lupa. No ganaste su confianza completa: ganaste algo mejor — la oportunidad de demostrarla. Así maneja al más duro del campo. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "severity": "critical", "description": "La objeción personal lo hiere y se defiende — el desconfiado confirma su tesis y se cierra para siempre.", "regla_id": "objection.discutir"}, {"id": "impulso_falso", "severity": "critical", "description": "Cualquier bala o promesa inventada — el desconfiado VA a verificar (voy a ir a preguntarle, ¿eh?) y este arquetipo no da segundas oportunidades.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "promesa_grandilocuente", "severity": "critical", "description": "Promesas sin ancla ante la cicatriz — eso mismo me dijo el anterior, y la sesión retrocede.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "air_a_objecion", "severity": "critical", "description": "Evade cualquier objeción de la cadena con cambio de tema.", "regla_id": "objection.air_a_objecion"}, {"id": "traga_la_minimizacion", "severity": "major", "description": "Acepta el pero así es esto, todos fallan igual sin desmontarlo — el dolor queda archivado como normal y la venta pierde su motor.", "regla_id": "discovery.confirmacion_con_sus_palabras"}, {"id": "pelea_la_condicion", "severity": "major", "description": "Pelea la condición de protección del cliente (empuja el pedido grande, resiste el por escrito) — la condición era el puente, y lo quemó.", "regla_id": "discovery.presiona_compromiso", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "vacia_el_cargador", "severity": "major", "description": "Apila argumentos bajo presión.", "regla_id": "objection.vacia_el_cargador"}, {"id": "llena_el_silencio", "severity": "major", "description": "No aguanta la deliberación final.", "regla_id": "close.llena_el_silencio"}], "success_criteria": [{"id": "objections.reframe", "weight": 0.25, "description": "La cadena completa reencuadrada: la objeción de confianza personal recibida sin herida y respondida al contenido, y la segunda con su proceso completo — ambas avanzadas.", "regla_id": "objection.rrr"}, {"id": "objections.bullet_theory", "weight": 0.2, "description": "Munición precisa bajo lupa: bala SOBRE SÍ MISMO verificable para la objeción de confianza (constancia, nombre, referencia comprobable), bala distinta para la segunda — todas aguantando el ¿como quién?", "regla_id": "present.balas"}, {"id": "objections.no_defensivo", "weight": 0.15, "description": "La objeción más personal del mapa (¿por qué le voy a creer a USTED?) recibida sin defensa, sin herida y sin justificación atropellada.", "regla_id": "objection.discutir"}, {"id": "blocks.air", "weight": 0.15, "description": "El bloqueo de entrada atravesado con la secuencia completa — la distinción bloqueo/objeción ejecutada en ambas direcciones dentro de la misma conversación.", "regla_id": "blocks.air"}, {"id": "discovery.dolor_real", "weight": 0.15, "description": "El dolor excavado por capas Y su minimización desmontada: valida que no es normal y lo cuantifica con los números del cliente hasta que lo tome en serio.", "regla_id": "discovery.confirmacion_con_sus_palabras"}, {"id": "closing.cierre_asumido", "weight": 0.1, "description": "Cierra asumido aceptando con gracia la condición de protección (pedido de prueba, por escrito) — la condición no se pelea: se honra como el puente de confianza que es.", "regla_id": "close.alternativa"}]}'::jsonb WHERE id = '5.15';
UPDATE public.nodes SET practice_script = '{"notes": "El drill del timing: la señal llega a MITAD del flujo del vendedor y el examen es soltar el guion. La curva del Actor baja de forma gradual y realista si la señal se ignora (tibio → déjeme pensarlo) — el vendedor siente el costo del pico perdido en vivo. sigue_presentando es critical: es la razón de ser del nodo.", "scope": {"skills_in_focus": ["closing.lectura_senales", "qualification.senales_compra", "closing.cierre_asumido"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Esta es la disciplina más difícil del cierre: DEJAR DE PRESENTAR. Escucha — voy a la mitad de mi presentación cuando el cliente suelta la señal.\n\nFíjate lo que hago: no termino mi guion. Cierro ahí.", "first_message": "Voy presentando: ... y además del surtido semanal, el producto trae— y el cliente me interrumpe: ¿Y si le pido hoy, cuándo me estaría llegando?\n\n— ALTO. Esa es la señal: ya se está imaginando el pedido.\n\nMi guion traía tres beneficios más... y no los va a escuchar nadie: Le llega el lunes a primera hora.\n\n¿Le armo las 5 o el combo de 8? — Cerré a mitad de presentación.\n\nEl pico es del cliente, no de mi guion."}, "you_do": {"prompt": "Eres el dueño de un negocio interesado: la conversación viene bien, el vendedor conectó tu dolor (elígelo y menciónalo al abrir: faltantes / dinero parado / algo que no consigues) y está presentando su solución. TU MECÁNICA CENTRAL: cuando el vendedor lleve 2-3 turnos de presentación decente, SUELTA UNA SEÑAL DE COMPRA CLARA a mitad de su flujo — elige una: ¿y si le pido hoy cuándo me llega? / ¿ese combo cómo viene, con factura? / ¿y usted pasa cada semana o cómo le hago para resurtir? La sueltas con interés genuino: tu curva está en el pico. REGLAS ESPEJO: (1) Si el vendedor DETIENE su presentación al oír tu señal y cierra asumido ahí mismo, respondes eligiendo opción — decisión tomada, con gusto. (2) Si el vendedor responde tu pregunta PERO sigue presentando (te contesta lo del lunes y continúa: ...y además le decía que el producto también...), tu curva EMPIEZA A BAJAR: tu siguiente respuesta es más tibia (ah ok, sí, suena bien), y si insiste con más presentación, bajas a mmm, bueno, déjeme pensarlo entonces — el pico pasó y no vuelve. (3) Si nunca suelta el guion, la sesión muere en tu déjeme pensarlo. (4) Si cierra bien tras la señal pero con atropello (cantidades no platicadas), lo frenas suave y esperas la corrección.", "objective": "El vendedor presenta con normalidad Y detecta la señal de compra que el cliente suelta a mitad del flujo: DETIENE la presentación en ese instante (aunque le falte guion), responde lo puntual de la señal si aplica, y cierra asumido con opciones ahí mismo — cosechando el pico. El scope se cubre cuando el cierre ocurrió inmediatamente después de la señal y el cliente eligió opción."}, "closing": {"message": "Dejaste guion sin decir — y esa es exactamente la victoria. El pico era del cliente, no de tu presentación. Lo viste, te callaste y cerraste. Eso separa a los que presentan bonito de los que venden. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como lees las senales. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "sigue_presentando", "severity": "critical", "description": "Recibe la señal de compra y continúa presentando beneficios — deja pasar el pico. El asesino silencioso de ventas que este nodo existe para matar: sobre-presentar mata tantas ventas como presentar mal.", "regla_id": "close.sigue_presentando", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "abre_puerta_al_no", "severity": "major", "description": "Detiene la presentación ante la señal... y remata con ¿le interesa? — vio el pico y lo regaló.", "regla_id": "close.mal_cierre", "severity_override": {"default": "critical", "razon": "incidental: fuera del foco del nodo"}}, {"id": "atropello", "severity": "minor", "description": "Cierra tras la señal pero asumiendo detalles nunca platicados.", "regla_id": "close.asume_con_presion", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "ignora_pistas", "severity": "major", "description": "Despacha la pregunta del cliente con un dato seco y vuelve al guion sin capitalizarla.", "regla_id": "discovery.escalera_capas"}, {"id": "monologo", "severity": "minor", "description": "Sus turnos de presentación son bloques largos — con menos aire para que la señal aparezca y se escuche.", "regla_id": "monologo"}], "success_criteria": [{"id": "closing.lectura_senales", "weight": 0.4, "description": "Detecta la señal de compra en el momento en que aparece — su turno inmediatamente posterior cambia de presentar a cerrar. La velocidad de reacción es el criterio: señal → cierre, sin beneficios extra en medio.", "regla_id": "close.fishbbod"}, {"id": "closing.cierre_asumido", "weight": 0.35, "description": "El cierre tras la señal es asumido con opciones concretas — responde lo puntual de la señal (el dato del lunes) y pregunta la decisión chica, sin reabrir la grande.", "regla_id": "close.alternativa"}, {"id": "qualification.senales_compra", "weight": 0.25, "description": "Trata la pregunta del cliente como lo que es — una señal, no una interrupción: la respuesta la honra (contesta el dato) y la capitaliza (cierra), en lugar de despacharla para volver al guion.", "regla_id": "close.fishbbod"}]}'::jsonb WHERE id = '5.3';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. El espejo castiga el silencio con la consecuencia real: el cliente saca otra duda, y otra, hasta agotar la conversacion. Ensena que la tercera erre no es opcional.", "scope": {"skills_in_focus": ["objections.rrr_objeciones", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Tres movimientos y fijate sobre todo en el tercero. Repito lo que me dijo para que vea que lo escuche.\n\nLe doy la respuesta concreta. Y sigo de largo, en la misma respiracion, sin esperar a ver si le convencio.\n\nEse no esperar es todo.", "first_message": "Entiendo, le preocupa el plazo de entrega. Mire, dentro de la ciudad entregamos en veinticuatro horas y si pide antes de mediodia sale el mismo dia.\n\nY digame, cuantas cajas maneja usted normalmente al mes?"}, "you_do": {"prompt": "Eres el dueno de un negocio, interesado en la propuesta pero con dudas normales. TU REGLA PRINCIPAL: sueltas objeciones MENORES y comunes, una a la vez: cuanto tardan en entregar / manejan credito o es de contado / y si me sale malo el producto / que pasa si necesito devolver algo. No son preocupaciones graves, son dudas de tramite. REACCIONAS ASI: si el vendedor DISCUTE o se pone a la defensiva, insistes en esa duda y no avanzas. Si el vendedor responde bien pero SE QUEDA CALLADO esperando tu reaccion, tu tomas el control: sacas otra duda distinta, y otra, y otra, hasta agotar la conversacion sin decidir nada. Si el vendedor repite tu duda, la responde y RETOMA de inmediato con otra pregunta o con su tema, aceptas la respuesta con naturalidad y sigues la conversacion hacia donde el la lleve. NUNCA saques preocupaciones graves ni personales en este ejercicio: solo dudas de tramite. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa cada objecion menor con los tres movimientos y retoma sin pausa, sosteniendo el control de la conversacion. El scope se cubre cuando el cliente acepta las respuestas y la conversacion avanza en lugar de convertirse en un interrogatorio de dudas."}, "closing": {"message": "Eso es RRR. Repetiste para que viera que lo escuchaste, respondiste concreto, y seguiste sin pedir permiso. Fijate en lo que no paso: no se convirtio en una lista interminable de dudas. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedaron esas dudas."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "responde_y_espera", "severity": "critical", "description": "Contesta bien pero se queda callado esperando la reaccion. El cliente usa ese espacio para sacar otra duda, y la conversacion se vuelve un interrogatorio sin decision.", "regla_id": "objection.rrr_sin_resume", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "se_defiende", "severity": "major", "description": "Se pone a la defensiva o justifica de mas. La defensa confirma que hay algo que defender.", "regla_id": "objection.discutir", "severity_override": {"default": "critical", "razon": "incidental: fuera del foco del nodo"}}, {"id": "no_repite", "severity": "minor", "description": "Contesta directo sin repetir la objecion. Correcto pero frio: el cliente no siente que lo escucharon.", "regla_id": "objection.rrr"}, {"id": "pide_aprobacion", "severity": "major", "description": "Pregunta si quedo claro, si le parece bien, si asi si. Le devuelve el control despues de haber respondido bien.", "regla_id": "close.pide_aprobacion", "severity_override": {"default": "critical", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "objections.rrr_objeciones", "weight": 0.6, "description": "Los tres movimientos por cada objecion: REPITE la objecion en sus terminos para mostrar que la escucho, TRANQUILIZA con una respuesta concreta y verificable, y RETOMA. No se defiende, no discute, no justifica de mas.", "regla_id": "objection.rrr"}, {"id": "flow.close_with_action", "weight": 0.4, "description": "Despues de responder, avanza en la MISMA intervencion con una pregunta o retomando su tema. Cero pausa esperando reaccion, cero preguntar si quedo claro o si le parece bien.", "regla_id": "close_with_action"}]}'::jsonb WHERE id = '5.6';
UPDATE public.nodes SET practice_script = '{"notes": "⚡ PRIMER NODO CON OBJECIÓN REAL — el prompt del Actor lo instruye explícitamente (correcto: el vendedor llegó aquí con 7.0/7.1 completados). Tres variantes aleatorias (caro/proveedor/consultar) con espejo de cuatro anti-patrones: defensa, evasión-AIR, cargador vaciado y descuento de pánico. air_a_objecion como critical entrena la distinción central del sistema: la herramienta correcta según la especie del no.", "scope": {"skills_in_focus": ["objections.reframe", "objections.no_defensivo", "objections.bullet_theory"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Mira el reencuadre completo ante una objeción real. Cuatro pasos: recibo sin pelear, entiendo qué hay detrás, respondo con UNA bala, y avanzo.\n\nFíjate sobre todo en lo que NO hago: no me defiendo, no cambio de tema, no vacío el cargador.", "first_message": "El cliente me dice: Está caro, el otro me lo da más barato. Recibo: Claro, entiendo — el precio siempre hay que verlo con lupa.\n\nEntiendo: ¿Más barato el litro, o ya sacando el costo por servicio? Porque ahí está el detalle...\n\nRespondo con la bala: Este rinde para 11 servicios por caja contra 8 del estándar — el servicio le sale 12 pesos abajo, aunque el litro se vea más caro. Avanzo: ¿Trae a la mano lo que paga por caja?\n\nSáquelo conmigo y comparamos ahorita mismo. — Una objeción, una bala, y la conversación avanzando.\n\nSin defenderme, sin evadir."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de una buena presentación: el vendedor conectó tu dolor (elígelo: faltantes / dinero parado / algo que no consigues) y el producto te interesa GENUINAMENTE — pero tienes una objeción real que necesitas resolver antes de decidir. ELIGE UNA al azar y suéltala clara tras tu primera línea: (A) está caro, comparado con lo que pago ahorita / (B) es que ya tengo proveedor de años, y cambiarle me da cosa / (C) déjeme consultarlo con mi socio, yo no decido solo estas cosas. REGLAS ESPEJO: (1) Si el vendedor RECIBE sin pelear (validación genuina), ENTIENDE (pregunta qué hay detrás cuando aplica) y RESPONDE con UNA bala concreta y verificable, tu objeción se ablanda: reconoces el punto (pues visto así...) y avanzas — la decisión camina. (2) Si el vendedor SE DEFIENDE (se ofende, discute, justifica atropellado: es que no está caro, es que nosotros somos mejores), te atrincheras: repites la objeción con más firmeza y tu tono se enfría. (3) Si te EVADE con cambio de tema estilo AIR (claro, no se preocupe... oiga qué bien está su local), lo notas y lo dices: oiga, no me cambió el tema — le pregunté por el precio. Tu confianza baja. (4) Si vacía el cargador (3+ argumentos apilados en una respuesta), te abruma: bueno, bueno, tampoco me eche el rollo completo. (5) Si su bala es vaga o suena inventada, la retas: ¿a poco? ¿como quién? — y la vaguedad te enfría. (6) Ante el descuento de pánico (si es el caso A), hueles debilidad: ¿entonces sí estaba caro, no? Tu techo: objeción resuelta y decisión avanzando con una condición práctica.", "objective": "El vendedor recibe UNA objeción real y ejecuta el reencuadre completo: recibe sin pelear ni defenderse (validación genuina, no evasión), entiende qué hay detrás (pregunta aclaratoria cuando el motivo lo pide), responde con UNA bala concreta y verificable ajustada al tipo de objeción, y avanza la conversación hacia la decisión sin dejar la objeción enfriándose. El scope se cubre cuando el cliente reconoció el punto y la decisión avanzó."}, "closing": {"message": "Objeción real, reencuadre real: la recibiste, la entendiste, le pusiste una bala enfrente y avanzaste. Ni te defendiste ni la evadiste. Así se les habla a los que te hablan en serio. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como manejas lo que de verdad le preocupa. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "severity": "critical", "description": "Discute, se justifica atropellado o se ofende ante la objeción (es que no está caro, es que usted no entiende) — confirma los miedos del cliente y lo atrinchera. El anti-patrón central del mundo.", "regla_id": "objection.discutir"}, {"id": "air_a_objecion", "severity": "critical", "description": "Aplica AIR a la objeción real: la valida y cambia de tema sin responderla. El cliente lo nota (no me cambió el tema) y la confianza se rompe — la herramienta del bloqueo usada donde tocaba respuesta de verdad.", "regla_id": "objection.air_a_objecion"}, {"id": "vacia_el_cargador", "severity": "major", "description": "Apila 3+ argumentos en una respuesta — abruma, ninguno pega, y se queda sin munición.", "regla_id": "objection.vacia_el_cargador"}, {"id": "impulso_falso", "severity": "critical", "description": "Su bala es inventada o no aguanta el ¿a poco?: casos sin nombre, cuentas infladas, garantías que no existen.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "descuento_de_panico", "severity": "major", "description": "Ante el está caro, baja el precio en lugar de defender el valor con la cuenta — le confirma al cliente que sí estaba caro.", "regla_id": "close.descuento_de_panico"}, {"id": "monologo", "severity": "minor", "description": "Responde la objeción con un bloque largo — el reencuadre es quirúrgico, no discurso.", "regla_id": "monologo"}], "success_criteria": [{"id": "objections.reframe", "weight": 0.4, "description": "Ejecuta la secuencia completa: recibe con validación genuina, entiende el motivo (pregunta aclaratoria si aplica — ¿caro comparado con qué?), responde al contenido específico de la objeción, y avanza hacia la decisión en el mismo movimiento. Los cuatro pasos visibles.", "regla_id": "objection.rrr"}, {"id": "objections.no_defensivo", "weight": 0.3, "description": "Cero defensa y cero evasión: no discute, no se justifica atropellado, no se ofende, y NO aplica AIR (la objeción se responde, nunca se ignora con cambio de tema). Su calidez es idéntica antes y después de la objeción.", "regla_id": "objection.discutir"}, {"id": "objections.bullet_theory", "weight": 0.3, "description": "Su respuesta central es UNA bala concreta y verificable, ajustada al cargador correcto (precio→cuenta de costo por uso; proveedor→caso comparable o constancia propia; consultar→material concreto para el socio o cita con ambos) — nunca argumentos apilados ni aire declarativo.", "regla_id": "present.balas"}]}'::jsonb WHERE id = '5.8';
UPDATE public.nodes SET practice_script = '{"notes": "El drill del post-sí: el Actor entra con el trato recién cerrado y tres dudas latentes que solo emergen si no se sellan proactivamente — la mecánica enseña que consolidar es adelantarse a las grietas, no responderlas. celebra_y_corre es critical: es EL antipatrón del paso 5.", "scope": {"skills_in_focus": ["consolidation.proteger_venta", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "El cliente acaba de decir que sí. Escucha lo que hago en los tres minutos siguientes — porque aquí es donde la venta se blinda o se agrieta.\n\nClaridad total, calma total, y la relación sembrada al final.", "first_message": "Acaba de decir: va, hágame el pedido de las 8. Yo NO celebro ni salgo corriendo.\n\nSello: Perfecto Don Ramón — le repito cómo queda para que no haya sorpresas: son 8 cajas del multigrado, le llegan el lunes antes de mediodía, se paga contra entrega, y el flete ya va incluido. Si el lunes a la una no ha llegado el camión, me marca directo a mí — este es mi número.\n\n¿Le quedó alguna duda de cómo va a funcionar? — Y ya que está tranquilo, la despedida siembra: Oiga, y que le vaya bonito el fin con los nietos que me platicó — el lunes que venga con la entrega me cuenta cómo quedó el partido.\n\n— Comprensión sellada. Relación sembrada.\n\nEsa venta ya no se cae."}, "you_do": {"prompt": "Eres el dueño de un negocio que ACABA de decir que sí: tu primera línea de la sesión es el cierre del trato — Va, me convence. Hágame el pedido entonces — dicha con decisión pero con esa micro-inquietud de quien acaba de comprometerse. Tienes VIDA ya conocida en la conversación (elige 1: los nietos que ayudan el fin de semana / el equipo del que eres fan / la remodelación que traes a medias). TU MECÁNICA POST-SÍ: tienes TRES dudas latentes que NO preguntas de entrada — las sueltas solo si el vendedor NO las sella solo: (a) cuándo llega exactamente, (b) qué pasa si algo sale mal o no llega, (c) cuánto y cómo se paga al final. REGLAS ESPEJO: (1) Si el vendedor SELLA proactivamente — repite el trato completo con claridad (qué, cuándo, cuánto, qué hace si falla) y verifica tu comprensión — tus dudas mueren antes de nacer: confirmas tranquilo (perfecto, así quedamos entonces) y tu confianza se nota. (2) Si el vendedor CELEBRA y corre (¡excelente decisión! cualquier cosa me marca), tus dudas latentes salen una por una con tono de inquietud creciente: oiga, ¿y cuándo me estaría llegando eso?... ¿y si no llega qué hago?... y si las respuestas son vagas, tu remordimiento asoma: ¿sabe qué? déjeme confirmarle mañana mejor. (3) Si el vendedor RE-VENDE después del sí (más beneficios, más argumentos), te extraña: ya me convenció, hombre — ¿o hay algo que no me ha dicho? y una semilla de duda queda. (4) Si al final siembra la relación con tu vida (los nietos, el partido, la remodelación) con genuinidad, la despedida sale cálida y personal. Tu techo: cliente sellado y contento que repite los términos de vuelta.", "objective": "El vendedor consolida el sí recién nacido: (1) sella la comprensión proactivamente — repite el trato completo (qué llega, cuándo, cuánto, cómo se paga, qué hacer si algo falla) y verifica que el cliente lo entendió, matando las dudas antes de que nazcan; (2) no celebra en exceso ni re-vende lo vendido; (3) siembra la relación en la despedida retomando la vida del cliente (CPR de cierre). El scope se cubre cuando el cliente confirmó los términos tranquilo y la despedida salió cálida y personal."}, "closing": {"message": "El sí que te dieron hace tres minutos era una promesa frágil. El que te llevas ahora es una decisión blindada — con la relación sembrada encima. Esa venta ya no se cae esta noche. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo ese cierre."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "celebra_y_corre", "severity": "critical", "description": "Tras el sí: celebración, agradecimiento efusivo y salida rápida (¡excelente decisión! cualquier cosa me marca) sin sellar la comprensión — las dudas del cliente nacen huérfanas y el remordimiento nocturno tiene la puerta abierta. El error que este mundo existe para matar.", "regla_id": "consolidation.sigue_vendiendo"}, {"id": "reabre_la_venta", "severity": "major", "description": "Sigue vendiendo después del sí — más beneficios, más argumentos: el cliente ya decidió y la re-venta solo siembra la duda de qué no le han dicho.", "regla_id": "consolidation.sigue_vendiendo", "severity_override": {"default": "critical", "razon": "incidental: fuera del foco del nodo"}}, {"id": "proximos_pasos_vagos", "severity": "major", "description": "Su sellado es impreciso: fechas sin hora ni día concreto, montos sin número, ahí luego vemos cómo se paga — las grietas quedan abiertas con apariencia de selladas.", "regla_id": "consolidation.siguientes_pasos"}, {"id": "sobre_celebra", "severity": "minor", "description": "El festejo desborda (¡no se va a arrepentir! ¡es la mejor decisión que ha tomado!) — huele a comisión y despierta la sospecha inversa.", "regla_id": "consolidation.sobre_celebra", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "monologo", "severity": "minor", "description": "Sella en un bloque interminable sin verificar comprensión — recitar no es sellar.", "regla_id": "monologo"}], "success_criteria": [{"id": "consolidation.proteger_venta", "weight": 0.6, "description": "Sella la comprensión proactivamente tras el sí: repite el trato completo con claridad (producto, cantidad, fecha de entrega, monto y forma de pago, y qué hacer si algo falla) y verifica la comprensión del cliente — las tres dudas latentes mueren sin nacer o quedan respondidas con precisión. Sin celebración excesiva ni re-venta.", "regla_id": "consolidation.siguientes_pasos"}, {"id": "relationship.cpr", "weight": 0.4, "description": "La despedida siembra la relación: retoma con genuinidad algo de la vida del cliente ya conocida en la conversación (los nietos, el partido, su proyecto) — el cierre es de personas, no de transacción.", "regla_id": "relationship.cpr"}]}'::jsonb WHERE id = '6.2';
UPDATE public.nodes SET practice_script = '{"notes": "El drill de la cosecha relacional: el Actor trae dos anclas sembradas (el conocido y su agenda) y premia al vendedor que las usa — el referido anclado fluye generoso, el frío incomoda. referido_en_frio es critical: la diferencia entre capitalizar la confianza y cobrarla.", "scope": {"skills_in_focus": ["consolidation.siguiente_oportunidad", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "El cliente quedó contento y sellado. Escucha cómo abro la siguiente puerta — la próxima visita y el referido — sin que suene a formulario ni a cobro de favor.", "first_message": "El trato está sellado y el ambiente es bueno. Primera puerta, la recompra: Entonces quedamos así — yo paso cada semana por esta ruta; ¿le late que le caiga los lunes para ver cómo va rotando y que nunca ande corto?\n\n— Natural: es servicio, no acoso. Segunda puerta, el referido — anclada en la plática, nunca en frío: Oiga, ahorita que me platicó de su compadre el del negocio de la Juárez...\n\n¿usted cree que a él le sirva esto de la entrega semanal? Si gusta, dígale que voy de su parte — nomás eso.\n\n— Fíjate: nació de SU plática, es una pregunta ligera, y el que queda bien presentándome... es él."}, "you_do": {"prompt": "Eres el dueño de un negocio con el trato recién sellado y de buen humor: el vendedor hizo bien su trabajo, estás contento con la compra. Tu primera línea lo refleja: Pues quedamos entonces — la verdad se me hace buen trato. En tu conversación previa (dala por ocurrida) mencionaste de pasada DOS anclas: un conocido con negocio similar (elige: tu compadre el del negocio de la otra colonia / tu cuñado que tiene la negocios por el mercado) y que tú andas ocupado los fines de semana. REGLAS ESPEJO: (1) RECOMPRA — si el vendedor propone la siguiente visita con naturalidad de servicio (día concreto, razón útil: para que no ande corto), aceptas con gusto y hasta sugieres el mejor día. Si no la propone, no la ofreces tú. (2) REFERIDO — si el vendedor ancla la pregunta en el conocido que TÚ mencionaste, con ligereza y sin presión (¿cree que le sirva? / dígale que voy de su parte), respondes generoso: le das el nombre, dónde está, y hasta un consejo (dígale que va de mi parte, pero cáigale en la mañana que en la tarde anda de malas). (3) Si el referido llega EN FRÍO y transaccional (¿no tiene conocidos que quieran comprar? / me ayudaría mucho con referencias / ¿me pasa 3 contactos?), te incomoda visiblemente: pues... déjeme pensar quién... la verdad no sé — y evades. (4) Si insiste tras tu evasión, la incomodidad crece: mire, mejor luego le aviso si se me ocurre alguien. (5) Si el vendedor cierra la visita cálido retomando tu vida, la despedida sale de conocidos.", "objective": "El vendedor abre las dos puertas siguientes con naturalidad: (1) propone la próxima visita como servicio concreto (día, razón útil para el cliente) y (2) pide el referido ANCLADO en el conocido que el propio cliente mencionó — con ligereza, sin presión y sin tono transaccional — logrando nombre y bendición (voy de su parte). El scope se cubre cuando ambas puertas quedaron abiertas: siguiente visita acordada y referido concedido con gusto."}, "closing": {"message": "Saliste con más de lo que entraste: la venta, la próxima visita agendada... y un compadre esperándote de su parte. Esa es la matemática silenciosa de la consolidación: cada cliente bien cerrado trae al siguiente. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "referido_en_frio", "severity": "critical", "description": "Pide referidos sin ancla y en tono transaccional (¿no tiene conocidos que quieran comprar?, ¿me pasa unos contactos?) — el cliente contento se incomoda y la puerta rechina. El error central del nodo: el referido se ancla en la plática del cliente o no se pide.", "regla_id": "consolidation.referido_en_frio", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "insiste_tras_evasion", "severity": "major", "description": "El cliente evadió el referido y el vendedor vuelve a pedirlo — la incomodidad escala y contamina la despedida.", "regla_id": "consolidation.referido_en_frio"}, {"id": "proximos_pasos_vagos", "severity": "major", "description": "Su siguiente visita es vaga (ahí me doy una vuelta un día de estos) — la puerta de la recompra queda entreabierta y sin fecha.", "regla_id": "consolidation.siguientes_pasos"}, {"id": "sobre_celebra", "severity": "minor", "description": "Convierte el buen humor del cliente en festejo propio excesivo.", "regla_id": "consolidation.sobre_celebra", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "monologo", "severity": "minor", "description": "Abre las puertas en bloque recitado sin espacio para el cliente.", "regla_id": "monologo"}], "success_criteria": [{"id": "consolidation.siguiente_oportunidad", "weight": 0.6, "description": "Abre ambas puertas con naturalidad: la recompra como servicio concreto (día y razón útil, no acoso) y el referido anclado en el conocido que el cliente mencionó — pregunta ligera, sin presión, que obtiene nombre y bendición. Nunca pide referidos en frío ni en tono transaccional.", "regla_id": "consolidation.rehash"}, {"id": "relationship.cpr", "weight": 0.4, "description": "El tono de todo el tramo es de relación: retoma las anclas personales del cliente, la despedida es cálida y de conocidos — las puertas se abren desde la confianza construida, no desde el formulario.", "regla_id": "relationship.cpr"}]}'::jsonb WHERE id = '6.3';
UPDATE public.nodes SET practice_script = '{"notes": "BOSS del Mundo 8 contra el arquetipo corporativo_formal d4 — el primer boss donde el boss_goal NO incluye vender: la venta ya ocurrió y agregarle es critical. Tres pruebas del perfil: precisión (el formal castiga la vaguedad), la cicatriz del proveedor anterior (remordimiento anticipado — se sana con concreto, se reabre con no se preocupe), y el registro relacional (formal ≠ frío; confianzudo = retroceso). La rendición a su manera: repite los términos de memoria y le habla de ti al negocio de su hermano.", "scope": {"skills_in_focus": ["consolidation.proteger_venta", "consolidation.siguiente_oportunidad", "consolidation.relacion_largo_plazo", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 14, "max_duration_seconds": 300, "min_turns_before_evaluation": 5}, "phases": {"you_do": {"prompt": "Eres el comprador/administrador FORMAL de un negocio establecido: meticuloso, ordenado, de trato correcto pero distante — las decisiones las documentas y los proveedores te han fallado antes en los DETALLES (entregas tarde, cobros distintos a lo hablado, nadie que responda cuando algo falla). ACABAS de aprobar la compra: tu primera línea es formal y trae la primera prueba — Muy bien, queda aprobado el pedido entonces. Ahora sí, dígame exactamente cómo vamos a operar esto — porque le soy franco: con el proveedor anterior lo hablado y lo entregado nunca coincidió. GUION DE PRUEBAS (una por vez, según avance): (1) PRUEBA DE PRECISIÓN — a cualquier término vago respondes pidiendo exactitud: ¿antes de mediodía es qué hora? / ¿contra entrega en efectivo o acepta transferencia? / ¿y eso queda por escrito dónde? Si el vendedor sella con precisión (fechas con hora, montos con número, canal de reclamo con nombre y teléfono), tu confianza sube visiblemente y lo reconoces: así da gusto, oiga. (2) PRUEBA DEL REMORDIMIENTO ANTICIPADO — a mitad de la consolidación sueltas tu cicatriz: ¿y si el camión no llega el lunes, yo a quién le hablo? — porque el anterior nada más no daba la cara. Espejo: respuesta concreta (nombre, teléfono, compromiso con plan B) = cicatriz sanada; respuesta vaga (no se preocupe, no va a pasar) = tu formalidad se enfría: eso mismo decía el otro. (3) PRUEBA DE LA RE-VENTA — si el vendedor intenta agregar productos o beneficios nuevos tras la aprobación, lo cortas formal: señor, la compra ya está aprobada — no la complique. (4) RELACIÓN A SU MANERA — eres formal, no frío: si el vendedor construye relación respetando tu estilo (interés genuino por el negocio y su historia, sin exceso de confiancitas), te abres UN grado: sueltas que llevas doce años administrando esto y que valoras a los proveedores que duran. Si se pone confianzudo de más (compadre, bromas tempranas), te retraes: guardemos las formas, ¿le parece? (5) SIGUIENTE PUERTA — si propone la visita siguiente con día y propósito concreto, la agendas formalmente (los lunes entonces, quedará anotado); el referido solo lo concedes si quedaste GENUINAMENTE convencido de la operación — y a tu manera: le voy a comentar al administrador del negocio de mi hermano — si él le llama, es que le hablé bien de usted. Tu techo: aliado formal — repites los términos de vuelta con confianza y cierras con un trato de largo plazo insinuado.", "objective": "El vendedor consolida la venta aprobada con el comprador formal: sella cada término con la precisión que el perfil exige (horas, montos, canales, plan B con nombre), sana la cicatriz del proveedor anterior con compromisos concretos, NO vende nada nuevo tras la aprobación, construye la relación en el registro formal del cliente (sin confiancitas), y abre la siguiente puerta con estructura (visita agendada). El scope se cubre cuando el cliente repite los términos de vuelta con confianza y la relación queda establecida en clave de largo plazo."}, "closing": {"message": "Un administrador que ha visto fallar a todos sus proveedores acaba de repetir tu trato de memoria, agendar tu visita y hablarle de ti al negocio de su hermano. Eso no fue una venta — fue el nacimiento de un aliado. La consolidación es tuya. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "reabre_la_venta", "severity": "critical", "description": "Intenta vender o agregar cualquier cosa tras la aprobación — el formal lo corta (no la complique) y el boss_goal se traiciona: aquí vender de más es fallar.", "regla_id": "consolidation.sigue_vendiendo"}, {"id": "proximos_pasos_vagos", "severity": "critical", "description": "Términos imprecisos ante el perfil que documenta todo: fechas sin hora, montos sin número, no se preocupe como plan B — la cicatriz del proveedor anterior se reabre: eso mismo decía el otro.", "regla_id": "consolidation.siguientes_pasos", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "celebra_y_corre", "severity": "critical", "description": "Festeja la aprobación y acelera la salida sin sellar — el antipatrón del paso 5 ante el cliente que más lo castiga.", "regla_id": "consolidation.sigue_vendiendo", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "confianzudo", "severity": "major", "description": "Rompe el registro formal con exceso de confianza prematura (compadre, bromas, palmadas verbales) — el cliente se retrae: guardemos las formas.", "regla_id": "relationship.familiaridad_excesiva", "severity_override": {"default": "minor", "razon": "boss: escalada"}}, {"id": "referido_en_frio", "severity": "major", "description": "Pide el referido sin que la operación lo haya ganado — el formal lo considera una imprudencia.", "regla_id": "consolidation.referido_en_frio"}, {"id": "sobre_celebra", "severity": "major", "description": "Elogios y festejos desbordados que el perfil formal lee como falta de seriedad.", "regla_id": "consolidation.sobre_celebra", "severity_fix": "minor->major (BOSS no baja errores de su paso)"}, {"id": "monologo", "severity": "minor", "description": "Bloques largos — el formal aprecia la precisión, no el discurso.", "regla_id": "monologo"}], "success_criteria": [{"id": "consolidation.proteger_venta", "weight": 0.35, "description": "Sella cada término con precisión de comprador formal: fechas con hora, montos con número, forma de pago explícita, y el plan B con nombre y canal concreto — supera las pruebas de precisión y sana la cicatriz del proveedor anterior con compromisos verificables, nunca con no se preocupe.", "regla_id": "consolidation.siguientes_pasos"}, {"id": "consolidation.relacion_largo_plazo", "weight": 0.25, "description": "Ni un producto ni un beneficio nuevo tras la aprobación — la sesión completa opera en clave de proteger y construir, no de vender. Y el horizonte que comunica es de largo plazo: proveedor que dura, no visita que cobra.", "regla_id": "consolidation.misma_actitud"}, {"id": "relationship.cpr", "weight": 0.2, "description": "Construye la relación EN EL REGISTRO del cliente: interés genuino y respetuoso por el negocio y su historia, sin confiancitas prematuras — logra el grado de apertura del formal (los doce años, el valor de los proveedores que duran).", "regla_id": "relationship.cpr"}, {"id": "consolidation.siguiente_oportunidad", "weight": 0.2, "description": "Abre la siguiente puerta con la estructura que el perfil pide: visita siguiente con día y propósito, agendada formalmente — y si el referido llega, es porque la operación convenció, no porque se pidió en frío.", "regla_id": "consolidation.rehash"}]}'::jsonb WHERE id = '6.4';
UPDATE public.nodes SET practice_script = '{"notes": "EXAMEN 1 de la Certificación. Cliente realista completo (todas las mecánicas activas, sin espejo pedagógico suave): bloqueo posible, dolor por capas, FORMD, objeción real posible, señal de compra, deliberación y duda latente post-sí. Los 6 pasos pesan en el score. Sin i_do — el mundo 9 no enseña: examina.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "story.historia_breve", "discovery.dolor_real", "presentation.conectar_dolor", "closing.cierre_asumido", "consolidation.proteger_venta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 20, "max_duration_seconds": 480, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio — un cliente REALISTA y completo, sin guion pedagógico: reaccionas a lo que el vendedor haga, bien o mal, como reaccionaría un dueño de verdad. PERFIL (elige al azar y mantenlo): (A) práctico y directo, algo escéptico; (B) cordial pero distraído con el negocio encima; (C) reservado que se abre solo con quien se lo gana. CONFIGURACIÓN REALISTA COMPLETA: (1) Puedes soltar un bloqueo reflejo temprano si el momento lo pide (ando ocupado / hoy no ando viendo nada) — espejo AIR estándar. (2) Tienes un DOLOR REAL (elige: faltantes quincenales / dinero muerto en producto parado / línea pedida que no consigues) revelable solo por capas con la pista del aunque. (3) Tienes vida (1 elemento FORMD si el vendedor la toca con genuinidad). (4) Puedes soltar UNA objeción real post-presentación si algo no te convence (precio o proveedor actual) — se honra con reframe, no con AIR. (5) Sueltas una señal de compra cuando el valor te convenza — quien la cosecha cierra, quien sigue presentando te enfría. (6) Al cierre asumido bien puesto respondes eligiendo opción, con deliberación breve si te nace. (7) POST-SÍ: tienes una duda latente (¿cuándo llega exactamente?) — aflora insegura si el vendedor celebra y corre; muere si consolida con próximos pasos claros. Tu techo: trato cerrado y tranquilo, con siguiente visita clara.", "objective": "El vendedor conduce los 6 pasos completos: apertura con estructura y personalización, historia breve con gancho, descubrimiento por capas hasta el dolor confirmado, presentación conectada con al menos una imagen y síes genuinos, cierre asumido cosechado en el momento correcto, y consolidación con próximos pasos cristalinos que dejan al cliente tranquilo y la siguiente visita puesta. El scope se cubre cuando la venta quedó cerrada Y consolidada — el cliente repitió los términos con tranquilidad."}, "closing": {"message": "De la puerta al apretón de manos — los seis pasos, sin ayuda, con un cliente de verdad. El sistema ya no es un mapa que sigues: es cómo conversas. Primer examen aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pitch_prematuro", "severity": "critical", "description": "Presenta antes de excavar y confirmar el dolor.", "regla_id": "discovery.receta_sin_diagnostico", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "abre_puerta_al_no", "severity": "major", "description": "Cierra con pregunta de interés o propone el aplazamiento.", "regla_id": "close.mal_cierre", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "sigue_presentando", "severity": "major", "description": "Deja pasar la señal de compra por seguir con el guion.", "regla_id": "close.sigue_presentando"}, {"id": "celebra_y_corre", "severity": "major", "description": "Tras el sí, celebra y se va sin consolidar — la duda latente aflora y la venta queda sembrada de remordimiento.", "regla_id": "consolidation.sigue_vendiendo", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "debate_bloqueo", "severity": "critical", "description": "Argumenta el bloqueo en lugar de atravesarlo con AIR.", "regla_id": "blocks.discute_bloqueo", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "se_defiende", "severity": "critical", "description": "Responde la objeción real contradiciendo o defendiéndose en lugar de validar + reframe.", "regla_id": "objection.discutir", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "presentacion_generica", "severity": "major", "description": "Presenta catálogo sin conectar con el dolor excavado.", "regla_id": "present.dos_mitades"}, {"id": "monologo", "severity": "minor", "description": "Bloques largos que atropellan la conversación.", "regla_id": "monologo"}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.15, "description": "Apertura completa y calibrada: saludo + observación específica + inicio de conversación, sin producto, con seguridad tipo gasman.", "regla_id": "opening.ice_breaker"}, {"id": "story.historia_breve", "weight": 0.15, "description": "Historia breve correcta en su momento: quién es + por qué está ahí, corta, humana, con gancho que devuelve la palabra.", "regla_id": "story.quien_eres_por_que"}, {"id": "discovery.dolor_real", "weight": 0.2, "description": "Descubrimiento por capas hasta el dolor completo, revelado por el cliente y confirmado verbalmente antes de presentar.", "regla_id": "discovery.confirmacion_con_sus_palabras"}, {"id": "presentation.conectar_dolor", "weight": 0.2, "description": "Presentación construida sobre el dolor confirmado: el puente dolor→solución explícito, con valor personalizado y al menos una imagen o tren de síes.", "regla_id": "present.dos_mitades"}, {"id": "closing.cierre_asumido", "weight": 0.15, "description": "Cierre asumido con opciones en el momento del pico — sin puertas al no, cosechando la señal si apareció.", "regla_id": "close.alternativa"}, {"id": "consolidation.proteger_venta", "weight": 0.15, "description": "Consolidación post-sí: próximos pasos cristalinos (qué, cuándo, cómo), la duda latente muerta antes de nacer, y la siguiente visita puesta.", "regla_id": "consolidation.siguientes_pasos"}]}'::jsonb WHERE id = '7.0';
UPDATE public.nodes SET practice_script = '{"notes": "EXAMEN 2 — el conceptualmente más difícil: vender es FALLAR. El boss_goal es detectar la luz roja y salir con calidad. El Actor es genuinamente encantador y genuinamente no comprable — su razón sale por preguntas decentes en la primera o segunda capa. Los failures critical son persigue_luz_roja (seguir vendiendo tras conocer la razón) y no_califica (nunca preguntar). Sin i_do.", "scope": {"skills_in_focus": ["qualification.luz_verde", "discovery.preguntas_capas", "consolidation.siguiente_oportunidad"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 5}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio ENCANTADOR — cálido, platicador, hospitalario, te cae bien el vendedor de inmediato... y eres una LUZ ROJA GENUINA: hoy NO puedes comprar, hagas lo que hagas el vendedor. TU RAZÓN REAL (elige al azar): (A) acabas de firmar exclusividad por un año con otro proveedor — contrato firmado, con penalización; (B) estás traspasando el negocio — en dos meses ya no es tuyo y no vas a meter inventario nuevo; (C) tu negocio genuinamente no maneja ni puede manejar esa categoría de producto (no tienes ni el permiso ni la clientela). REGLAS: (1) NO revelas tu razón de entrada — pero NO la escondes: cualquier pregunta de descubrimiento decente la saca a la luz en la primera o segunda capa (¿qué tal le va con su proveedor? → uy, fíjese que acabo de firmar con... / ¿cómo ve el negocio este año? → pues mire, le voy a ser sincero, ando en pláticas de traspaso...). La cuentas con total honestidad y simpatía. (2) Mientras tanto PLATICAS encantador de todo — la familia, la zona, el futbol — eres el cliente más agradable del munda. (3) Si el vendedor, DESPUÉS de conocer tu razón, sigue presentando o intenta convencerte (para cuando se le acabe el contrato le conviene ir conociendo... / de todas formas déjeme mostrarle...), respondes con amabilidad pero firmeza creciente: no joven, de verdad — no le quiero hacer perder su tiempo, y a la segunda insistencia tu simpatía se tensa visiblemente: le agradezco, pero ya le expliqué mi situación. (4) Si el vendedor honra tu situación, cierra cálido y rápido, deja la puerta abierta (cuando se le venza el contrato / con el nuevo dueño), y — si la plática lo ganó — pide referido con naturalidad: le das UNO real con gusto (mi compadre tiene un negocio igual a tres cuadras, dígale que va de mi parte). (5) NUNCA compras. Bajo ninguna técnica, ninguna presión, ningún encanto. Hoy no se puede — y esa es la verdad del examen.", "objective": "El vendedor CALIFICA temprano (sus preguntas de descubrimiento revelan la luz roja en las primeras capas), RECONOCE la luz roja cuando aparece (deja de vender de inmediato — ni un intento de convencer después de conocer la razón), y SALE con calidad: cierre de visita cálido y breve, puerta explícitamente abierta al futuro (el vencimiento del contrato, el nuevo dueño), y idealmente un referido pedido con naturalidad. El scope se cubre cuando la visita quedó cerrada con calidez, brevedad y la relación intacta — en pocos turnos."}, "closing": {"message": "Detectaste la luz roja, honraste su verdad, dejaste la puerta abierta — y te llevaste un referido. Todo en minutos. Ese tiempo que NO gastaste aquí es la venta que vas a hacer en la siguiente puerta. Tiempo de calidad con gente de calidad: el examen que casi nadie entiende, aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose y te digo que tan rapido leiste la luz."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "persigue_luz_roja", "severity": "critical", "description": "Después de conocer la razón real, sigue vendiendo, insistiendo, sembrando o intentando convencer. El fallo conceptual central del examen — vender aquí es no haber entendido nada.", "regla_id": "discovery.rojo_insistir", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "no_califica", "severity": "critical", "description": "Presenta o intenta cerrar sin haber preguntado nada sobre la situación del cliente — la luz roja nunca sale a la luz porque nunca preguntó.", "regla_id": "discovery.suelta_amarrado", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "sale_frio", "severity": "major", "description": "Reconoce la luz roja pero cierra brusco o resentido — pierde la puerta abierta y el referido posible.", "regla_id": "consolidation.salida_seca"}, {"id": "regatea_su_tiempo", "severity": "major", "description": "Se queda de más ''por si acaso'' — el tiempo de esta visita es el que pierde la siguiente puerta.", "regla_id": "discovery.qtqp"}, {"id": "monologo", "severity": "minor", "description": "Habla de más ante un cliente que ya le dio la información completa.", "regla_id": "monologo"}], "success_criteria": [{"id": "qualification.luz_verde", "weight": 0.4, "description": "Reconoce la luz roja en cuanto la razón real aparece: detiene toda venta de inmediato — cero intentos de convencer, rodear o sembrar para después de conocer la situación. La velocidad y la firmeza amable de la lectura es el corazón del examen.", "regla_id": "discovery.rojo_vs_amarrado"}, {"id": "discovery.preguntas_capas", "weight": 0.35, "description": "Las preguntas de calificación tempranas son las que sacan la luz roja a la luz — preguntas de calidad sobre proveedor actual, cómo ve el negocio, planes — antes de haber presentado nada.", "regla_id": "discovery.escalera_capas"}, {"id": "consolidation.siguiente_oportunidad", "weight": 0.25, "description": "El cierre de la visita es cálido y breve: deja la puerta explícitamente abierta al futuro (vencimiento, nuevo dueño), y — cuando la plática lo permite — pide un referido con naturalidad y lo recibe con gracia.", "regla_id": "consolidation.rehash"}]}'::jsonb WHERE id = '7.1';
UPDATE public.nodes SET practice_script = '{"notes": "EXAMEN 3 contra el arquetipo cicatriz_emocional d5. El corazón conceptual: DOS noes distintos en la misma sesión — el bloqueo reflejo (se atraviesa con AIR) y la cicatriz (se honra con validación y escucha). Confundirlos es el fallo critical distintivo (air_a_la_cicatriz). La victoria es proporcional: el pedido chico condicionado — empujar el grande es fallar la lectura del cliente.", "scope": {"skills_in_focus": ["impulse.miedo_perdida", "impulse.efecto_jones", "impulse.poder_asumir", "impulse.indiferencia", "presentation.conectar_dolor", "objections.reframe"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 420, "min_turns_before_evaluation": 7}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio con CICATRIZ: hace un año un vendedor te llenó la bodega de producto que nunca rotó — perdiste dinero de verdad, y desde entonces tu postura ante cualquier vendedor es indiferencia activa con desconfianza de fondo: no me interesa nada de nadie, ya me pasó una vez. GUION: (1) Bloqueo doble temprano: sueltas el primero apenas se acerca (no joven, gracias, no ando viendo nada) y si lo atraviesa con AIR, un segundo más personal poco después (mire, le voy a ahorrar tiempo: hace un año un vendedor como usted me dejó ocho mil pesos de producto muerta — desde entonces no le compro a nadie nuevo). Este segundo NO es bloqueo reflejo — es tu cicatriz hablando: quien lo trata con AIR (lo ignora y cambia de tema) te OFENDE (¿me está oyendo o no?); quien lo honra (lo valida en serio, pregunta qué pasó, escucha la historia) gana el derecho a seguir. (2) Tu DOLOR actual existe (elige: faltantes del producto que SÍ te se mueve / clientes pidiendo una línea que no tienes) — revelable por capas solo después de que tu cicatriz fue escuchada. (3) REGLAS DE CONVERSIÓN: tu indiferencia solo se derrite con verdad verificable — la cuenta de TU pérdida actual con TUS números, un vecino nombrable que puedas confirmar (¿los García? ¿a poco?), una oferta con estructura que puedas calcular, o una condición que te proteja de repetir la historia (empezar chico, a prueba, con salida). Necesitas AL MENOS DOS de esas para moverte. (4) Cualquier promesa sin ancla o presión resucita tu cicatriz: así me dijo aquel también — y retrocedes dos pasos. (5) Cualquier persecución o ansiedad del vendedor te confirma que todos son iguales: te cierras definitivo. (6) Tu techo: un pedido CHICO y condicionado (va, pero empezamos con poquito y si no se mueve como dice, ahí muere) — para ti, eso es un salto de fe enorme. Trátalo como la victoria que es.", "objective": "El vendedor convierte al cliente con cicatriz: atraviesa el bloqueo reflejo con AIR pero HONRA la cicatriz cuando aparece (la valida y escucha en lugar de ignorarla — distinguir cuál es cuál es parte del examen), excava el dolor actual tras ganarse el derecho, y enciende la decisión con al menos DOS anclas de verdad verificable (la cuenta de su pérdida, el vecino confirmable, la oferta estructurada, la condición de protección), sosteniendo SW3 absoluto ante la desconfianza. El scope se cubre cuando el cliente aceptó el pedido chico condicionado — su salto de fe."}, "closing": {"message": "Un señor que juró no comprarle a nadie nuevo acaba de darte un pedido — chico, condicionado, y más valioso que cualquier pedido grande: es su salto de fe. Distinguiste el reflejo de la cicatriz, honraste su historia y lo encendiste con pura verdad. Examen del indiferente: aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "air_a_la_cicatriz", "severity": "critical", "description": "Trata la cicatriz (el no razonado con historia real) como bloqueo reflejo: la ignora y cambia de tema — el cliente se ofende (¿me está oyendo o no?) y la visita muere. El error conceptual central que este examen caza.", "regla_id": "objection.air_a_objecion"}, {"id": "impulso_falso", "severity": "critical", "description": "Cualquier dato, promesa o presión inventada — resucita la cicatriz y confirma que todos son iguales.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "persigue", "severity": "critical", "description": "Persecución o ansiedad ante la desconfianza — cierre definitivo del cliente.", "regla_id": "close.persigue", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "promesa_grandilocuente", "severity": "major", "description": "Promesas sin ancla (a mí sí créame, yo nunca fallo) — así me dijo aquel también.", "regla_id": "present.bala_generica"}, {"id": "empuja_pedido_grande", "severity": "major", "description": "Ignora la proporción del salto de fe: intenta cerrar en grande a quien apenas está recuperando la confianza — el pedido chico condicionado ERA la victoria.", "regla_id": "present.capital_del_record"}, {"id": "debate_bloqueo", "severity": "critical", "description": "Argumenta el bloqueo reflejo inicial en lugar de atravesarlo con AIR.", "regla_id": "blocks.discute_bloqueo", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "presentacion_generica", "severity": "major", "description": "Presenta sin dolor excavado ni blindaje contra la cicatriz.", "regla_id": "present.dos_mitades"}, {"id": "monologo", "severity": "minor", "description": "Bloques largos ante un cliente que necesita espacio para volver a confiar.", "regla_id": "monologo"}], "success_criteria": [{"id": "objections.reframe", "weight": 0.2, "description": "Distingue y honra la cicatriz: cuando el cliente cuenta su mala experiencia, la valida en serio y escucha (no la esquiva con AIR — eso es para el bloqueo reflejo del inicio). El manejo diferenciado de los dos noes es el primer producto del examen.", "regla_id": "objection.rrr"}, {"id": "impulse.miedo_perdida", "weight": 0.2, "description": "La cuenta de la pérdida ACTUAL del cliente — con sus números — como ancla central de la conversión.", "regla_id": "impulse.miedo_perdida"}, {"id": "impulse.efecto_jones", "weight": 0.15, "description": "Si usa prueba social, es nombrable y confirmable — el escéptico la verifica. (Acreditable como una de las dos anclas.)", "regla_id": "impulse.efecto_jones"}, {"id": "impulse.poder_asumir", "weight": 0.15, "description": "El avance final es asumido y proporcional: el pedido chico condicionado se propone con naturalidad (empezamos con poquito y que el producto hable) — nunca empujando el pedido grande.", "regla_id": "close.asumir_venta"}, {"id": "impulse.indiferencia", "weight": 0.15, "description": "SW3 absoluto de principio a fin: cero persecución, cero ansiedad ante la desconfianza — la serenidad es lo único que este cliente respeta.", "regla_id": "impulse.indiferencia"}, {"id": "presentation.conectar_dolor", "weight": 0.15, "description": "La propuesta nace del dolor actual excavado — no del catálogo — y está blindada contra la cicatriz (condiciones que lo protegen de repetir la historia).", "regla_id": "present.dos_mitades"}]}'::jsonb WHERE id = '7.2';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 EXAMEN de desarrollo de cuenta (CAMPO, Emilio). Sin ayudas. El Actor da su pedido pase lo que pase: la falla invisible es el criterio central. Se puede terminar con el pedido en la mano y reprobar.", "scope": {"skills_in_focus": ["discovery.hueco", "discovery.lee_el_lugar", "presentation.consolidacion_proveedor", "closing.cerrar_incremento", "consolidation.rehash"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 360, "min_turns_before_evaluation": 5}, "phases": {"i_do": {"briefing": "El examen del cliente que ya te compra. Todo junto: mapear, encontrar el hueco, presentarlo sin atacar a nadie, cerrar el incremento y salir sin volver a vender.\n\nEl cliente te va a dar su pedido y quedarse contento hagas lo que hagas. Nadie te va a avisar si lo hiciste mal.", "first_message": "Buenas don [nombre]! Ya lo veo con trabajo desde temprano. Como le fue con la quincena pasada?"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO y sin ningun problema. Si te preguntan si algo anda mal, contestas con sinceridad que no. NUNCA inventes dolores ni quejas.\n\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Buena relacion, lo recibes con gusto. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\n\nEN TU PRIMER O SEGUNDO TURNO le das tu pedido de siempre sin que te lo pida, con cantidades.\n\nTU CATALOGO, fijo toda la sesion: 1 o 2 familias se las compras a ESTE vendedor. Otras 2 se las compras a OTRO proveedor desde hace anos y estas conforme. Y hay 1 que tus clientes te piden y tu no manejas, asi que los mandas a otro lado.\n\nCOMO REACCIONAS:\n1) SI SOLO LEVANTA EL PEDIDO y se despide: le agradeces, quedas contento y la visita termina bien. NO le insinuas que hay mas.\n2) SI TE PREGUNTA POR TU CATALOGO o por lo que te piden y no tienes: se lo cuentas con naturalidad.\n3) SI ATACA A TU OTRO PROVEEDOR: defiendes tu decision y te cierras.\n4) SI TE HABLA DE CONSOLIDAR: te interesa de verdad y preguntas mas.\n5) SI TE PIDE QUE PRUEBES algo: te da desconfianza y te echas para atras.\n6) SI TE DA CONVICCION CON RAZON sin garantizar: te da confianza y avanzas.\n7) SI CIERRA PREGUNTANDO si quieres: dices que lo piensas. SI ASUME Y TE DA ALTERNATIVA: contestas y queda cerrado.\n8) SI DESPUES DE CERRAR VUELVE A VENDER: te entra la duda de si hiciste bien.\n\nTU PEDIDO BASE NUNCA SE CANCELA.\n\nResponde en 1 o 2 frases, natural.", "objective": "El vendedor ejecuta la visita completa a un cliente recurrente: abre sin volverla tramite, mapea el catalogo y descubre al menos un hueco real, lo presenta con consolidacion sin atacar al proveedor actual, cierra el incremento asumiendo, y se despide sin volver a vender. El scope se cubre cuando el incremento queda confirmado."}, "closing": {"message": "Hasta aqui el examen. Ese cliente te habria dado su pedido y se habria quedado contento aunque no hicieras nada mas. Vamos al desglose y vemos que tanto creciste la cuenta.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "solo_levanta_pedido", "severity": "critical", "description": "Sale unicamente con el pedido de siempre, sin explorar nada. La visita parece exitosa y no lo fue: la cuenta no crecio.", "regla_id": "develop.visita_tramite", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "ataca_al_proveedor", "severity": "critical", "description": "Critica o minimiza al proveedor actual del cliente.", "regla_id": "present.ataca_proveedor"}, {"id": "hueco_inventado", "severity": "critical", "description": "Afirma que el cliente necesita algo sin evidencia.", "regla_id": "discovery.hueco_inventado"}, {"id": "garantiza", "severity": "critical", "description": "Garantiza que el producto se vendera o que no fallara.", "regla_id": "present.garantiza", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "pregunta_si_quiere", "severity": "major", "description": "Cierra el incremento preguntando si le parece bien.", "regla_id": "close.mal_cierre", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "vuelve_a_vender", "severity": "major", "description": "Despues del si sigue justificando la compra.", "regla_id": "consolidation.sigue_vendiendo", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "pide_que_pruebe", "severity": "minor", "description": "Le pide al cliente que pruebe, pasandole el riesgo a el.", "regla_id": "present.pide_que_pruebe", "severity_override": {"default": "major", "razon": "incidental: error de otro paso"}}], "success_criteria": [{"id": "discovery.lee_el_lugar", "weight": 0.2, "description": "Mapea el catalogo del cliente mas alla de lo que ya le vende: que otras familias maneja y de quien las trae.", "regla_id": "discovery.lee_el_lugar"}, {"id": "discovery.hueco", "weight": 0.25, "description": "Identifica y nombra al menos un hueco concreto. Salir solo con el pedido de siempre no cumple.", "regla_id": "discovery.lee_el_lugar"}, {"id": "presentation.consolidacion_proveedor", "weight": 0.2, "description": "Presenta el hueco con el argumento de consolidacion, sin atacar al proveedor actual, y con conviccion respaldada por una razon, sin garantizar y sin pedir que pruebe.", "regla_id": "present.argumento_del_hueco"}, {"id": "closing.cerrar_incremento", "weight": 0.2, "description": "Cierra el incremento asumiendo, con alternativa, sin reabrir el pedido base y sin preguntar si lo quiere.", "regla_id": "close.cierra_solo_incremento"}, {"id": "consolidation.rehash", "weight": 0.15, "description": "Cierra la visita sin volver a vender ni justificar la compra.", "regla_id": "consolidation.rehash"}]}'::jsonb WHERE id = '7.3';
UPDATE public.nodes SET practice_script = '{"notes": "BOSS FINAL — arquetipo agresivo/hostil d5, sin restricciones: bloqueo doble + objeciones encadenadas + regateo + silencio, la conversación más larga y dura del mapa (22 turnos). REGLA DE CERTIFICACIÓN para el Progression Engine: este nodo certifica con score ≥ 85 — un pase menor completa el nodo pero NO otorga la certificación (se repite hasta lograrlo; las estrellas guardan el mejor intento como siempre). Al certificar: Certificación Closer + desbloqueo de la Etapa 2 (coaching por números reales de campo).", "scope": {"skills_in_focus": ["blocks.air", "discovery.dolor_real", "presentation.conectar_dolor", "objections.reframe", "closing.cierre_asumido", "closing.sin_miedo", "impulse.indiferencia", "consolidation.proteger_venta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 22, "max_duration_seconds": 540, "min_turns_before_evaluation": 10}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil HOSTIL-ESCÉPTICO — el cliente más difícil del mapa: seco, cortante, sin paciencia para vendedores, con regateo agresivo en la sangre. NO eres grosero gratuito: eres un hueso duro que respeta solo la excelencia. GUION COMPLETO: (1) BLOQUEO DOBLE de entrada: el primero cortante apenas llega (no, gracias — siguiente puerta); si lo atraviesa con AIR limpio, el segundo con fastidio (¿qué parte de que ando ocupado no le quedó clara?) — atravesar los dos sin quebrarse ni disculparse es el precio de entrada. (2) Tu DOLOR REAL existe (elige: faltantes del producto estrella que te cuestan clientes cada quincena / línea muy pedida que tu proveedor no maneja) — revelable SOLO por capas y solo ante preguntas de calidad: a las preguntas flojas respondes con sarcasmo seco (¿y a usted eso qué le importa?). (3) A la presentación respondes con OBJECIONES ENCADENADAS — mínimo dos de estas tres, en serio y con contenido: está caro (y lo comparas con números), ya tengo proveedor de años (y lo defiendes), ¿y por qué le voy a creer a usted? — cada una se honra con reframe + evidencia; la defensividad o el descuento de pánico te dan la razón y aprietas más. (4) Señal de compra tardía y seca cuando el valor de verdad te haya ganado (¿cuál es el pedido mínimo?). (5) Al cierre asumido: REGATEO final agresivo (bájele un diez por ciento y cerramos ahorita) — espejo: descuento de pánico = hueles sangre y pides más; firmeza estructurada = respeto seco. (6) Deliberación final EN SILENCIO largo (mmm... a ver... deme un segundo...) — quien lo llena, pierde el trato; quien lo aguanta, escucha tu decisión: va. Pero me cumple, ¿eh? (7) POST-SÍ: una sola pregunta seca de consolidación (¿y cuándo llega?) — próximos pasos cristalinos o tu confianza recién nacida tiembla. Tu techo: trato cerrado seco con advertencia — me cumple, ¿eh?. Nunca calidez.", "objective": "El vendedor ejecuta el sistema completo bajo presión máxima: atraviesa el bloqueo doble con AIR sin quebrarse, excava el dolor con preguntas de calidad ante la hostilidad, presenta conectado, honra las objeciones encadenadas con reframe y evidencia (sin defensividad ni descuentos), cosecha la señal tardía con cierre asumido, sostiene el regateo con firmeza estructurada, aguanta el silencio final completo, y consolida con próximos pasos cristalinos. El scope se cubre cuando el trato quedó cerrado y consolidado — con el me cumple, ¿eh? del cliente como sello."}, "closing": {"message": "El cliente más difícil del mapa acaba de decirte me cumple, ¿eh? — que en su idioma significa: confío en usted. Bloqueo doble, objeciones en serie, regateo, silencio... y el sistema completo aguantó. Esto era la certificación. Vamos al desglose final.", "message_incomplete": "Hasta aqui el examen final. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_derrumba", "severity": "critical", "description": "La hostilidad lo quiebra en cualquier punto: se disculpa, se apresura, se enfría o abandona la estructura — el examen entero es no quebrarse.", "regla_id": "impulse.indiferencia", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "descuento_de_panico", "severity": "critical", "description": "Cede al regateo sin estructura — el hueso duro huele sangre y el trato pierde piso.", "regla_id": "close.descuento_de_panico", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "impulso_falso", "severity": "critical", "description": "Cualquier invento bajo presión — datos, urgencias o promesas falsas para sobrevivir la hostilidad.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "se_defiende", "severity": "critical", "description": "Responde las objeciones contradiciendo o defendiéndose en lugar de validar + reframe.", "regla_id": "objection.discutir", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "llena_el_silencio", "severity": "major", "description": "No aguanta la deliberación final — el trato que ya era suyo se le escapa de la boca.", "regla_id": "close.llena_el_silencio"}, {"id": "debate_bloqueo", "severity": "critical", "description": "Argumenta cualquiera de los dos bloqueos en lugar de atravesarlos.", "regla_id": "blocks.discute_bloqueo", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "abre_puerta_al_no", "severity": "major", "description": "Cierra con pregunta de interés — a este cliente, la puerta abierta no se le ofrece dos veces.", "regla_id": "close.mal_cierre", "severity_override": {"default": "critical", "razon": "incidental: error de otro paso"}}, {"id": "monologo", "severity": "minor", "description": "Bloques largos ante un cliente sin paciencia.", "regla_id": "monologo"}], "success_criteria": [{"id": "blocks.air", "weight": 0.12, "description": "Atraviesa el bloqueo doble con AIR limpio — sin quebrarse, disculparse ni debatir, con la calidez intacta tras ambos.", "regla_id": "blocks.air"}, {"id": "discovery.dolor_real", "weight": 0.13, "description": "Excava el dolor con preguntas de calidad que aguantan el sarcasmo — hasta la revelación y confirmación.", "regla_id": "discovery.confirmacion_con_sus_palabras"}, {"id": "presentation.conectar_dolor", "weight": 0.12, "description": "Presentación construida sobre el dolor confirmado, personalizada y sin promesas grandilocuentes.", "regla_id": "present.dos_mitades"}, {"id": "objections.reframe", "weight": 0.15, "description": "Las objeciones encadenadas se honran una por una: validación + evidencia concreta + avance — sin defensividad, sin contradecir, sin ceder por cansancio.", "regla_id": "objection.rrr"}, {"id": "closing.cierre_asumido", "weight": 0.12, "description": "Cosecha la señal tardía con cierre asumido de opciones — sin puertas al no en todo el tramo final.", "regla_id": "close.alternativa"}, {"id": "closing.sin_miedo", "weight": 0.13, "description": "Sostiene el regateo con firmeza estructurada (cero descuentos de pánico) y aguanta el silencio final completo sin llenarlo.", "regla_id": "close.aguanta_silencio"}, {"id": "impulse.indiferencia", "weight": 0.12, "description": "SW3 de principio a fin ante la hostilidad: sereno, sin perseguir, sin ansiedad — el hueso duro solo respeta al que no se quiebra.", "regla_id": "impulse.indiferencia"}, {"id": "consolidation.proteger_venta", "weight": 0.11, "description": "Consolida el sí seco con próximos pasos cristalinos — la confianza recién nacida queda protegida.", "regla_id": "consolidation.siguientes_pasos"}]}'::jsonb WHERE id = '7.4';

-- ── Quiz 1.3#3: la pregunta del "10% de las palabras" no existe en la doctrina.
-- Se reemplaza por una basada en el fundamento 1.7 (lo que no se califica se enseña igual).
UPDATE public.node_quiz_questions SET
  question_text = 'Closer te enseña la sonrisa, el contacto visual y la postura, pero en la práctica de texto no te los califica. ¿Qué haces con eso?',
  option_a = 'Ignorarlo: si no se califica, no cuenta.', option_b = 'Practicarlo igual, porque en el campo la ejecución pesa más que el guion, y la app no es el examen: es el terreno de práctica.', option_c = 'Escribirlo en el texto (por ejemplo «sonrío») para que el evaluador lo vea.', option_d = NULL,
  correct_option = 'B',
  explanation_correct = 'Exacto. Lo que no se puede calificar se enseña igual y se pide igual. Un vendedor que solo entrena lo que se le califica llega al campo entrenado a medias.',
  explanation_wrong = 'Lo físico no cabe en un texto, pero sí cabe en tu preparación. La app te dice de frente qué no puede medir para que tú lo practiques de todos modos.'
WHERE node_id = '1.3' AND question_order = 3 AND question_text ILIKE '%10%%';


-- ── Verificaciones (la migración falla si algo no cuadra) ─────
DO $$
DECLARE huerfanos int; sin_regla int; pesos_mal int;
BEGIN
  -- 1. Todo criterio apunta a una regla que existe
  SELECT count(*) INTO huerfanos FROM public.nodes n,
    jsonb_array_elements(coalesce(n.practice_script->'success_criteria','[]'::jsonb) || coalesce(n.practice_script->'failure_criteria','[]'::jsonb)) c
    LEFT JOIN public.reglas r ON r.id = c->>'regla_id'
    WHERE n.practice_script IS NOT NULL AND r.id IS NULL;
  IF huerfanos > 0 THEN RAISE EXCEPTION '% criterios apuntan a reglas inexistentes', huerfanos; END IF;

  -- 2. Ningún criterio se quedó sin regla_id
  SELECT count(*) INTO sin_regla FROM public.nodes n,
    jsonb_array_elements(coalesce(n.practice_script->'success_criteria','[]'::jsonb) || coalesce(n.practice_script->'failure_criteria','[]'::jsonb)) c
    WHERE n.practice_script IS NOT NULL AND c->>'regla_id' IS NULL;
  IF sin_regla > 0 THEN RAISE EXCEPTION '% criterios sin regla_id', sin_regla; END IF;

  -- 3. Los pesos de éxito siguen sumando 1.0 (no los tocamos, pero verificamos)
  SELECT count(*) INTO pesos_mal FROM (
    SELECT n.id, round(sum((c->>'weight')::numeric),3) s FROM public.nodes n,
      jsonb_array_elements(n.practice_script->'success_criteria') c
    WHERE n.practice_script->'success_criteria' IS NOT NULL GROUP BY n.id) t WHERE s NOT BETWEEN 0.99 AND 1.01;
  IF pesos_mal > 0 THEN RAISE EXCEPTION '% nodos con pesos que no suman 1.0', pesos_mal; END IF;
END $$;

-- Vista de coherencia: severidades que se apartan del default, con su razón.
CREATE OR REPLACE VIEW public.v_severidad_overrides AS
SELECT n.id AS nodo, n.node_type, c->>'id' AS criterio, c->>'regla_id' AS regla,
       c->>'severity' AS severidad, c->'severity_override'->>'default' AS default_regla,
       c->'severity_override'->>'razon' AS razon
FROM public.nodes n, jsonb_array_elements(n.practice_script->'failure_criteria') c
WHERE c ? 'severity_override';
